/// v3.12.0 (CIRISPersist#153 Ask 1) — Postgres row →
/// [`crate::federation::IdentityOccurrence`].
fn pg_row_to_identity_occurrence(
    row: tokio_postgres::Row,
) -> Result<crate::federation::IdentityOccurrence, crate::federation::Error> {
    let mk_err = crate::federation::Error::Backend;
    let enc_x25519: Option<String> = row.safe_get_with("pubkey_x25519_base64", mk_err)?;
    let enc_ml_kem: Option<String> = row.safe_get_with("pubkey_ml_kem_768_base64", mk_err)?;
    Ok(crate::federation::IdentityOccurrence {
        identity_key_id: row.safe_get_with("identity_key_id", mk_err)?,
        occurrence_key_id: row.safe_get_with("occurrence_key_id", mk_err)?,
        device_class: row.safe_get_with("device_class", mk_err)?,
        hardware_attestation: row.safe_get_with("hardware_attestation", mk_err)?,
        asserted_at: row.safe_get_with("asserted_at", mk_err)?,
        valid_until: row.safe_get_with("valid_until", mk_err)?,
        encryption_pubkeys: match (enc_x25519, enc_ml_kem) {
            (Some(x25519_base64), Some(ml_kem_768_base64)) => {
                Some(crate::federation::EncryptionPubkeys {
                    x25519_base64,
                    ml_kem_768_base64,
                })
            }
            _ => None,
        },
        // #418 — nullable (grandfathered rows are NULL). v31.0.0 (#644): TEXT
        // since V122, so this parses rather than reparsing a JSONB round-trip.
        transport_binding: {
            let tb: Option<String> = row.safe_get_with("transport_binding", mk_err)?;
            tb.map(|t| serde_json::from_str(&t))
                .transpose()
                .map_err(|e| {
                    crate::federation::Error::Backend(format!("transport_binding decode: {e}"))
                })?
        },
        persist_row_hash: row.safe_get_with("persist_row_hash", mk_err)?,
    })
}

/// v14.1.0 (#418 replication read) — Postgres row →
/// [`crate::federation::SignedIdentityOccurrence`]. Reconstructs the signature
/// container from the stored JSONB `{attesting_key_id, signed_envelope,
/// signature}` columns. The extra columns are read before delegating to
/// [`pg_row_to_identity_occurrence`], which consumes `row`. Callers gate on
/// non-NULL sig columns.
fn pg_row_to_signed_identity_occurrence(
    row: tokio_postgres::Row,
) -> Result<crate::federation::SignedIdentityOccurrence, crate::federation::Error> {
    let mk_err = crate::federation::Error::Backend;
    let attesting_key_id: String = row.safe_get_with("attesting_key_id", mk_err)?;
    // v31.0.0 (#644) — the V102 trio is TEXT since V122.
    let signed_envelope = pg_envelope_value(
        &row.safe_get_with::<String, _, _, _>("signed_envelope", mk_err)?,
        "signed_envelope",
    )?;
    let signature_text: String = row.safe_get_with("signature", mk_err)?;
    let signature = serde_json::from_str(&signature_text)
        .map_err(|e| crate::federation::Error::Backend(format!("signature decode: {e}")))?;
    let identity_occurrence = pg_row_to_identity_occurrence(row)?;
    Ok(crate::federation::SignedIdentityOccurrence {
        identity_occurrence,
        attesting_key_id,
        signed_envelope,
        signature,
    })
}

