    /// Mission category §4 "Idempotency": ON CONFLICT DO NOTHING.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn insert_idempotent() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let row = TraceEventRow {
            trace_id: format!("trace-pg-{}", uuid_like()),
            thought_id: "th-1".into(),
            task_id: None,
            step_point: None,
            event_type: ReasoningEventType::ThoughtStart,
            attempt_index: 0,
            ts: chrono::Utc::now(),
            agent_name: None,
            agent_id_hash: "deadbeef".into(),
            cognitive_state: None,
            trace_level: crate::schema::TraceLevel::Generic,
            payload: serde_json::Map::new(),
            cost_llm_calls: None,
            cost_tokens: None,
            cost_usd: None,
            signature: "AAAA".into(),
            signing_key_id: "test-key".into(),
            signature_verified: true,
            verification_source: crate::store::VerificationSource::Persist,
            schema_version: "2.7.0".into(),
            pii_scrubbed: false,
            original_content_hash: None,
            scrub_signature: None,
            scrub_key_id: None,
            scrub_timestamp: None,
            agent_role: None,
            agent_template: None,
            deployment_domain: None,
            deployment_type: None,
            deployment_region: None,
            deployment_trust_mode: None,
            cohort_scope: "federation".to_string(),
            cohort_target_id: None,
            signature_ml_dsa_65: None,
            pubkey_ml_dsa_65: None,
            pqc_key_id: None,
        };

        let r1 = backend
            .insert_trace_events_batch(std::slice::from_ref(&row))
            .await
            .unwrap();
        assert_eq!(r1.inserted, 1);
        assert_eq!(r1.conflicted, 0);

        let r2 = backend.insert_trace_events_batch(&[row]).await.unwrap();
        assert_eq!(r2.inserted, 0);
        assert_eq!(r2.conflicted, 1);
    }

    fn uuid_like() -> String {
        // Avoid pulling in the uuid crate for a single test helper.
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        format!("{nanos:x}")
    }

    /// v12.6.0 (CIRISPersist#171, §10.1.3 transit-not-rest) — Postgres parity
    /// for the FULL consent-SLA loop through the REAL admission path: a
    /// crypto-valid subject-side `consent:state:revoked` is ADMITTED as a
    /// transit local-tier write, and `run_consent_sla_watch` fires
    /// `consent_revocation_promotion_overdue` for it past the 24 h window (not
    /// before). A crypto-INVALID one is rejected at admission. Suffix-scoped so
    /// the assertions bind only to this run's fixtures on the shared test DB.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_consent_revocation_transit_admits_and_sla_fires_end_to_end() {
        use crate::federation::types::{attestation_tier, attestation_type, LocalAttestationInput};
        use crate::federation::FederationDirectory;
        use std::time::Duration;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.expect("connect");
        backend.run_migrations().await.expect("migrations run");

        let now0 = chrono::Utc::now();
        let suffix = uuid_like();
        let subject = format!("subject-c-{suffix}");
        let target = format!("target-c-{suffix}");
        for kid in [&subject, &target] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "registry", now0, true),
                })
                .await
                .unwrap();
        }

        // v31.0.0 (CIRISPersist#598) — a `consent:state:*` row states its own
        // instant in the SIGNED envelope; the local write door stamps the
        // column FROM it (`admission::local_row_instant`).
        // v31.0.0 (CIRISPersist#656) — and it states the typed-column MIRROR in
        // those same signed bytes. The transit door RECEIVES bytes it did not
        // mint, so it checks the mirror rather than stamping one; the producer
        // therefore also states the `attestation_id` it bound.
        backend
            .attestation_upsert_local(
                crate::federation::tier_ingest::test_support::bound_transit_revocation_input(
                    &format!("rev-{suffix}"),
                    &subject,
                    &target,
                    vec![subject.clone()],
                    crate::federation::types::cohort_scope::SELF,
                    chrono::Utc::now(),
                    serde_json::json!({ "id": format!("rev-{suffix}") }),
                ),
            )
            .await
            .expect("crypto-valid subject-side revocation transits the local tier");

        // Find THIS run's transit row (shared DB → filter by our subject).
        let mine = backend
            .list_consent_revocations(Some(now0))
            .await
            .unwrap()
            .into_iter()
            .find(|a| a.attesting_key_id == subject)
            .expect("revocation scan sees our transit row");
        assert_eq!(mine.tier, attestation_tier::LOCAL);
        assert!(mine.promoted_at.is_none());
        assert!(
            !mine.scrub_signature_classical.is_empty() && mine.scrub_signature_pqc.is_some(),
            "transit row round-trips its real bound-hybrid signature"
        );
        let revoked_at = mine.asserted_at;
        let window = Duration::from_secs(86_400);

        // Helper: does OUR overdue hard_case exist? (shared test DB → filter
        // to this run's subject/target).
        async fn ours_fired(
            backend: &PostgresBackend,
            since: chrono::DateTime<chrono::Utc>,
            subject: &str,
            target: &str,
        ) -> bool {
            use crate::federation::hard_case::{kind, HardCaseFilter};
            use crate::federation::FederationDirectory as _;
            backend
                .list_hard_case_events(HardCaseFilter {
                    kind: Some(kind::CONSENT_REVOCATION_PROMOTION_OVERDUE.into()),
                    since: Some(since),
                })
                .await
                .unwrap()
                .into_iter()
                .any(|e| {
                    e.subject_key_id.as_deref() == Some(subject)
                        && e.target_key_id.as_deref() == Some(target)
                })
        }

        // BEFORE the boundary → our revocation is in flight, not overdue.
        let before = revoked_at + chrono::Duration::seconds(86_400 - 1);
        backend.run_consent_sla_watch(before, window).await.unwrap();
        assert!(
            !ours_fired(&backend, now0, &subject, &target).await,
            "within the window: our overdue hard_case must NOT have fired"
        );

        // AFTER the boundary → our overdue hard_case fires.
        let after = revoked_at + chrono::Duration::seconds(86_400 + 1);
        backend.run_consent_sla_watch(after, window).await.unwrap();
        assert!(
            ours_fired(&backend, now0, &subject, &target).await,
            "past the window: our overdue hard_case fires"
        );

        // crypto-INVALID revocation → rejected at admission (never transits).
        let bad = backend
            .attestation_insert_local(LocalAttestationInput {
                attestation_id: None,
                attesting_key_id: subject.clone(),
                attested_key_id: Some(target.clone()),
                attestation_type: attestation_type::SCORES.into(),
                weight: None,
                expires_at: None,
                attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                    serde_json::json!({
                        "id": format!("rev-bad-{suffix}"), "dimension": "consent:state:revoked:v1",
                        "score": 1.0, "confidence": 0.9,
                    }),
                )
                .unwrap(),
                subject_key_ids: vec![subject.clone()],
                cohort_scope: crate::federation::types::cohort_scope::SELF.to_string(),
                scrub_signature_classical: Some("AAAA".into()),
                scrub_signature_pqc: Some("AAAA".into()),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(
                bad,
                crate::federation::Error::FederationTierUnverified { .. }
            ),
            "crypto-invalid revocation rejected at admission, got {bad:?}"
        );
    }

    /// v16 (CIRISPersist#434, CC 5.3.2.2) — the promotion-overdue READER
    /// (`list_consent_revocation_promotion_overdue`, what the PyO3
    /// `list_consent_revocation_promotion_overdue_json` dispatches onto)
    /// on live PG, over the REAL local-write admission path: an over-SLA
    /// transit revocation is returned + flagged idempotently (deduping
    /// against the watcher's event_id), a within-SLA scan returns nothing
    /// of ours, and promotion clears it. Suffix-scoped for the shared DB.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_consent_promotion_overdue_reader() {
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::attestation_tier;
        use crate::federation::FederationDirectory;
        use std::time::Duration;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.expect("connect");
        backend.run_migrations().await.expect("migrations run");

        let now0 = chrono::Utc::now();
        let suffix = uuid_like();
        let subject = format!("subject-r-{suffix}");
        let target = format!("target-r-{suffix}");
        for kid in [&subject, &target] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "registry", now0, true),
                })
                .await
                .unwrap();
        }
        // v31.0.0 (CIRISPersist#598/#656) — see the twin above: the producer
        // binds both the signed instant and the typed-column mirror, and
        // therefore states the `attestation_id` it bound.
        let att_id = backend
            .attestation_upsert_local(
                crate::federation::tier_ingest::test_support::bound_transit_revocation_input(
                    &format!("rev-r-{suffix}"),
                    &subject,
                    &target,
                    vec![subject.clone()],
                    crate::federation::types::cohort_scope::SELF,
                    chrono::Utc::now(),
                    serde_json::json!({ "id": format!("rev-r-{suffix}") }),
                ),
            )
            .await
            .expect("transit local-tier revocation admits");
        let revoked_at = backend
            .list_consent_revocations(Some(now0))
            .await
            .unwrap()
            .into_iter()
            .find(|a| a.attesting_key_id == subject)
            .expect("our transit row is scanned")
            .asserted_at;
        let sla = Duration::from_secs(86_400);
        // Shared test DB → bind assertions to OUR rows only.
        let mine = |rows: Vec<crate::federation::ConsentPromotionOverdueRow>| {
            rows.into_iter()
                .filter(|r| r.subject_key_id == subject)
                .collect::<Vec<_>>()
        };

        // Within the SLA → our row never appears.
        let before = revoked_at + chrono::Duration::seconds(86_400 - 1);
        let rows = mine(
            backend
                .list_consent_revocation_promotion_overdue(before, sla)
                .await
                .unwrap(),
        );
        assert!(rows.is_empty(), "within-SLA: our revocation never appears");

        // Past the SLA → returned (with the promote handle) + flagged.
        let after = revoked_at + chrono::Duration::seconds(86_400 + 60);
        let rows = mine(
            backend
                .list_consent_revocation_promotion_overdue(after, sla)
                .await
                .unwrap(),
        );
        assert_eq!(rows.len(), 1, "our over-SLA revocation is overdue");
        assert_eq!(rows[0].attestation_id, att_id);
        assert_eq!(rows[0].target_key_id, target);
        assert_eq!(rows[0].tier, attestation_tier::LOCAL);
        let our_flags = |events: Vec<crate::federation::HardCaseEvent>| {
            events
                .into_iter()
                .filter(|e| e.subject_key_id.as_deref() == Some(subject.as_str()))
                .collect::<Vec<_>>()
        };
        let evs = our_flags(
            backend
                .list_hard_case_events(HardCaseFilter {
                    kind: Some(kind::CONSENT_REVOCATION_PROMOTION_OVERDUE.into()),
                    since: Some(now0),
                })
                .await
                .unwrap(),
        );
        assert_eq!(evs.len(), 1, "our overdue row was flagged");

        // Re-scan → still listed, NO duplicate hard_case.
        let rows = mine(
            backend
                .list_consent_revocation_promotion_overdue(after, sla)
                .await
                .unwrap(),
        );
        assert_eq!(rows.len(), 1);
        assert_eq!(
            our_flags(
                backend
                    .list_hard_case_events(HardCaseFilter {
                        kind: Some(kind::CONSENT_REVOCATION_PROMOTION_OVERDUE.into()),
                        since: Some(now0),
                    })
                    .await
                    .unwrap(),
            )
            .len(),
            1,
            "re-scan writes no duplicate hard_case"
        );

        // Promote (tier=federation) → drops out of subsequent scans.
        // v30.6.0 (CIRISPersist#622) — bound as TEXT; the column stopped being
        // `uuid` in V121.
        let client = backend.get_client().await.unwrap();
        client
            .execute(
                "UPDATE cirislens.federation_attestations \
                 SET tier = 'federation', promoted_at = $2 \
                 WHERE attestation_id = $1",
                &[&att_id, &after],
            )
            .await
            .unwrap();
        let rows = mine(
            backend
                .list_consent_revocation_promotion_overdue(
                    after + chrono::Duration::seconds(1),
                    sla,
                )
                .await
                .unwrap(),
        );
        assert!(
            rows.is_empty(),
            "a promoted revocation is no longer overdue"
        );
    }

    // ─── Lens-derived schemas (v0.4.3, CIRISPersist#18) ────────────

    /// Smoke: detection event round-trip through put + get.
    /// Note: this test calls the storage trait directly (post-verify
    /// surface). The Engine PyO3 method enforces hybrid verify; this
    /// test does NOT exercise that — see hybrid_verify_strict_*
    /// tests in src/verify/hybrid.rs for the verify enforcement.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn detection_event_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        use crate::derived::{
            ConformityVariant, DerivedSchema, DetectionEvent, DetectionSeverity, EventFilter,
        };
        let event = DetectionEvent {
            detection_id: uuid::Uuid::new_v4(),
            trace_id: format!("trace-derived-{}", uuid_like()),
            body_sha256: vec![0xAB; 32],
            detector: "manifold_conformity_outlier".into(),
            severity: DetectionSeverity::Warning,
            cohort_cell: serde_json::json!({
                "agent_role": "ally",
                "agent_template": "ally-v3-default",
                "deployment_domain": "moderation",
                "deployment_type": "production",
                "deployment_region": "US",
                "deployment_trust_mode": "federated_peer"
            }),
            conformity_variant: ConformityVariant::Numeric,
            conformity_payload: serde_json::json!({"score": 3.7}),
            lens_core_version: "0.1.0".into(),
            ratchet_calibration_version: 1,
            canonical_bytes: b"{\"detection_id\":\"x\"}".to_vec(),
            ed25519_sig: vec![0x01; 64],
            ml_dsa_65_sig: vec![0x02; 3309],
            signing_key_id: "lens-core-test:1".into(),
            ts: chrono::Utc::now(),
        };

        backend.put_detection_event(event.clone()).await.unwrap();

        // Idempotent on detection_id collision with same content.
        backend.put_detection_event(event.clone()).await.unwrap();

        // Read back via filter on trace_id.
        let filter = EventFilter {
            trace_id: Some(event.trace_id.clone()),
            ..Default::default()
        };
        let rows = backend.get_detection_events(filter).await.unwrap();
        assert_eq!(rows.len(), 1);
        let got = &rows[0];
        assert_eq!(got.detection_id, event.detection_id);
        assert_eq!(got.detector, event.detector);
        assert_eq!(got.severity, DetectionSeverity::Warning);
        assert_eq!(got.conformity_variant, ConformityVariant::Numeric);
    }

    /// v7.0.0 (CIRISPersist#222) — full Art. 17 erasure on PG: hard-
    /// delete the agent's trace_events + trace_llm_calls across all keys,
    /// TOMBSTONE the derived detection_events (PII NULLed, erased_at set,
    /// row retained), emit the audit row, idempotent. Self-isolating:
    /// uuid-suffixed agent_id_hash + trace_ids so a reused PG is safe.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn erasure_tombstones_detections_and_hard_deletes_traces_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        use crate::derived::{ConformityVariant, DerivedSchema, DetectionEvent, DetectionSeverity};
        use crate::federation::{hard_case, FederationDirectory, HardCaseFilter};

        let suffix = uuid_like();
        let agent = format!("erase-agent-{suffix}");
        let trace_a = format!("trace-A-{suffix}");
        let trace_b = format!("trace-B-{suffix}");
        let trace_unrelated = format!("trace-Z-{suffix}");

        // Two traces for the target agent (distinct keys to prove the
        // all-keys scope), one unrelated agent's trace.
        let mk_event = |trace_id: &str, agent_id: &str, key: &str| TraceEventRow {
            trace_id: trace_id.to_owned(),
            thought_id: format!("th-{suffix}"),
            task_id: None,
            step_point: None,
            event_type: ReasoningEventType::ThoughtStart,
            attempt_index: 0,
            ts: chrono::Utc::now(),
            agent_name: None,
            agent_id_hash: agent_id.to_owned(),
            cognitive_state: None,
            trace_level: crate::schema::TraceLevel::Generic,
            payload: serde_json::Map::new(),
            cost_llm_calls: None,
            cost_tokens: None,
            cost_usd: None,
            signature: "AAAA".into(),
            signing_key_id: key.to_owned(),
            signature_verified: true,
            verification_source: crate::store::VerificationSource::Persist,
            schema_version: "2.7.0".into(),
            pii_scrubbed: false,
            original_content_hash: None,
            scrub_signature: None,
            scrub_key_id: None,
            scrub_timestamp: None,
            agent_role: None,
            agent_template: None,
            deployment_domain: None,
            deployment_type: None,
            deployment_region: None,
            deployment_trust_mode: None,
            cohort_scope: "federation".to_string(),
            cohort_target_id: None,
            signature_ml_dsa_65: None,
            pubkey_ml_dsa_65: None,
            pqc_key_id: None,
        };
        let other_agent = format!("other-agent-{suffix}");
        backend
            .insert_trace_events_batch(&[
                mk_event(&trace_a, &agent, "key1"),
                mk_event(&trace_b, &agent, "key2"),
                mk_event(&trace_unrelated, &other_agent, "key1"),
            ])
            .await
            .unwrap();

        // Detections: one derived from trace_a (tombstoned), one from
        // the unrelated trace (must survive).
        let det_a = uuid::Uuid::new_v4();
        let det_z = uuid::Uuid::new_v4();
        let mk_det = |id: uuid::Uuid, trace_id: &str| DetectionEvent {
            detection_id: id,
            trace_id: trace_id.to_owned(),
            body_sha256: vec![0xAB; 32],
            detector: "manifold_conformity_outlier".into(),
            severity: DetectionSeverity::Warning,
            cohort_cell: serde_json::json!({"deployment_domain": "legal"}),
            conformity_variant: ConformityVariant::Numeric,
            conformity_payload: serde_json::json!({"score": 3.1}),
            lens_core_version: "0.1.0".into(),
            ratchet_calibration_version: 1,
            canonical_bytes: format!("canon-{trace_id}").into_bytes(),
            ed25519_sig: vec![0x01; 64],
            ml_dsa_65_sig: vec![0x02; 3309],
            signing_key_id: "lens-core-test:1".into(),
            ts: chrono::Utc::now(),
        };
        backend
            .put_detection_event(mk_det(det_a, &trace_a))
            .await
            .unwrap();
        backend
            .put_detection_event(mk_det(det_z, &trace_unrelated))
            .await
            .unwrap();

        let summary = backend
            .delete_traces_for_agent_id_hash(&agent)
            .await
            .unwrap();
        assert_eq!(summary.trace_events, 2, "both keys' traces hard-deleted");
        assert_eq!(summary.detection_events_tombstoned, 1);

        // Traces gone.
        assert!(backend
            .fetch_trace_events_page(0, 100, Some(&agent))
            .await
            .unwrap()
            .is_empty());

        // Tombstone survives as a row with NULLed PII + erased_at set.
        let client = backend.get_client().await.unwrap();
        let tomb_row = client
            .query_one(
                "SELECT trace_id, body_sha256, canonical_bytes, erased_at \
                 FROM cirislens_derived.detection_events WHERE detection_id = $1",
                &[&det_a],
            )
            .await
            .unwrap();
        let tomb_trace: Option<String> = tomb_row
            .safe_get_with::<Option<String>, _, _, _>("trace_id", Error::Backend)
            .unwrap();
        let tomb_body: Option<Vec<u8>> = tomb_row
            .safe_get_with::<Option<Vec<u8>>, _, _, _>("body_sha256", Error::Backend)
            .unwrap();
        let tomb_canon: Option<Vec<u8>> = tomb_row
            .safe_get_with::<Option<Vec<u8>>, _, _, _>("canonical_bytes", Error::Backend)
            .unwrap();
        let tomb_erased: Option<chrono::DateTime<chrono::Utc>> = tomb_row
            .safe_get_with::<Option<chrono::DateTime<chrono::Utc>>, _, _, _>(
                "erased_at",
                Error::Backend,
            )
            .unwrap();
        assert!(tomb_trace.is_none(), "trace_id NULLed");
        assert!(tomb_body.is_none(), "body_sha256 NULLed");
        assert!(tomb_canon.is_none(), "canonical_bytes NULLed");
        assert!(tomb_erased.is_some(), "erased_at stamped");

        // Unrelated detection untouched.
        let z_row = client
            .query_one(
                "SELECT trace_id, erased_at FROM cirislens_derived.detection_events \
                 WHERE detection_id = $1",
                &[&det_z],
            )
            .await
            .unwrap();
        let z_trace: Option<String> = z_row
            .safe_get_with::<Option<String>, _, _, _>("trace_id", Error::Backend)
            .unwrap();
        let z_erased: Option<chrono::DateTime<chrono::Utc>> = z_row
            .safe_get_with::<Option<chrono::DateTime<chrono::Utc>>, _, _, _>(
                "erased_at",
                Error::Backend,
            )
            .unwrap();
        assert_eq!(z_trace.as_deref(), Some(trace_unrelated.as_str()));
        assert!(z_erased.is_none(), "unrelated detection not tombstoned");

        // Audit row emitted, scoped to this agent.
        let events = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(hard_case::kind::TRACE_ERASURE.into()),
                since: None,
            })
            .await
            .unwrap();
        let mine: Vec<_> = events
            .into_iter()
            .filter(|e| e.target_key_id.as_deref() == Some(agent.as_str()))
            .collect();
        assert_eq!(mine.len(), 1, "exactly one audit row for this agent");
        assert_eq!(mine[0].detail["detection_events_tombstoned"], 1);

        // Idempotent: second erasure is a clean all-zero no-op.
        let summary2 = backend
            .delete_traces_for_agent_id_hash(&agent)
            .await
            .unwrap();
        assert_eq!(summary2.trace_events, 0);
        assert_eq!(summary2.detection_events_tombstoned, 0);
    }

    /// Conflict on same detection_id with DIFFERENT canonical_bytes
    /// surfaces as derived::Error::Conflict.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn detection_event_conflict_on_different_content() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        use crate::derived::{ConformityVariant, DerivedSchema, DetectionEvent, DetectionSeverity};
        let did = uuid::Uuid::new_v4();
        let event_a = DetectionEvent {
            detection_id: did,
            trace_id: format!("trace-conflict-{}", uuid_like()),
            body_sha256: vec![0xAB; 32],
            detector: "test".into(),
            severity: DetectionSeverity::Info,
            cohort_cell: serde_json::json!({}),
            conformity_variant: ConformityVariant::Indeterminate,
            conformity_payload: serde_json::json!({"reason": "missing"}),
            lens_core_version: "0.1.0".into(),
            ratchet_calibration_version: 1,
            canonical_bytes: b"original".to_vec(),
            ed25519_sig: vec![0x01; 64],
            ml_dsa_65_sig: vec![0x02; 3309],
            signing_key_id: "test:1".into(),
            ts: chrono::Utc::now(),
        };
        backend.put_detection_event(event_a.clone()).await.unwrap();

        let event_b = DetectionEvent {
            canonical_bytes: b"DIFFERENT".to_vec(),
            ..event_a
        };
        let err = backend.put_detection_event(event_b).await.unwrap_err();
        assert!(matches!(err, crate::derived::Error::Conflict(_)));
    }

    /// Calibration bundle put → get_current → atomic flip on next put.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn calibration_bundle_atomic_current_flip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        use crate::derived::{CalibrationBundle, DerivedSchema};

        // Use timestamp-based versions so re-runs don't collide.
        let v1 = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_secs() as i32;
        let v2 = v1 + 1;

        let bundle_v1 = CalibrationBundle {
            ratchet_calibration_version: v1,
            projection_version: "crc-v1".into(),
            calibrated_at: chrono::Utc::now(),
            calibration_corpus_sha256: "abc".into(),
            calibration_corpus_n: 6465,
            sample_size_gate: 30,
            manifold_threshold_global: 3.5,
            projection_metadata: serde_json::json!({}),
            cohort_centroids: serde_json::json!([]),
            is_current: true,
            canonical_bytes: format!("v1-{v1}").into_bytes(),
            ed25519_sig: vec![0x01; 64],
            ml_dsa_65_sig: vec![0x02; 3309],
            signing_key_id: "ratchet-steward:1".into(),
            inserted_at: chrono::Utc::now(),
        };
        backend
            .put_calibration_bundle(bundle_v1.clone())
            .await
            .unwrap();

        let current = backend
            .get_current_calibration_bundle()
            .await
            .unwrap()
            .expect("v1 should be current after put");
        assert_eq!(current.ratchet_calibration_version, v1);
        assert!(current.is_current);

        // Insert v2 with is_current=true; v1 must flip to false atomically.
        let bundle_v2 = CalibrationBundle {
            ratchet_calibration_version: v2,
            canonical_bytes: format!("v2-{v2}").into_bytes(),
            ..bundle_v1.clone()
        };
        backend.put_calibration_bundle(bundle_v2).await.unwrap();

        let current = backend
            .get_current_calibration_bundle()
            .await
            .unwrap()
            .expect("v2 should be current after flip");
        assert_eq!(current.ratchet_calibration_version, v2);
        assert!(current.is_current);

        // v1 must still be readable by version, but is_current=false.
        let v1_row = backend
            .get_calibration_bundle_by_version(v1)
            .await
            .unwrap()
            .expect("v1 should still exist post-flip");
        assert!(!v1_row.is_current, "v1 must be flipped to is_current=false");
    }

