    // ─── ReadEngine §I tests (v0.5.5, CIRISPersist#23) ──────────────

    /// v31.1.0 (CIRISPersist#655, PR #667 round-4) — **the admission position
    /// survives a backward clock step, on this backend's real write path.**
    ///
    /// Twin of the sqlite and memory witnesses, and the one that matters most:
    /// postgres reads its `MAX(admitted_at)` over a connection pool rather than
    /// under a process-local lock, so "the rule is unit-tested" says least
    /// here. The post-step state is planted directly — the last position handed
    /// out is moved an hour into the future, what a node looks like after an
    /// NTP correction — and the next admission must still sort after it.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn admission_position_survives_a_backward_clock_step_pg_655() {
        use crate::federation::FederationDirectory as _;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let tag = uuid::Uuid::new_v4().simple().to_string();
        let a = format!("rvp-a-{tag}");
        let b = format!("rvp-b-{tag}");
        for k in [&a, &b] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(k, k, now - chrono::Duration::minutes(1), false),
                })
                .await
                .unwrap();
        }
        let mk = |subject: &str| {
            let id = uuid::Uuid::new_v4().to_string();
            crate::federation::tier_ingest::test_support::seal_revocation(
                crate::federation::Revocation {
                    revocation_id: id.clone(),
                    revoked_key_id: subject.to_owned(),
                    revoking_key_id: subject.to_owned(),
                    reason: Some("test".into()),
                    revoked_at: now,
                    effective_at: now,
                    revocation_envelope: serde_json::json!({ "id": id }),
                    original_content_hash: String::new(),
                    scrub_signature_classical: String::new(),
                    scrub_signature_pqc: None,
                    scrub_key_id: subject.to_owned(),
                    scrub_timestamp: now,
                    pqc_completed_at: None,
                    observed_region: crate::federation::verify_coord::region::US.into(),
                    revoked_after: None,
                    persist_row_hash: String::new(),
                },
            )
        };
        backend
            .put_revocation(crate::federation::SignedRevocation { revocation: mk(&a) })
            .await
            .expect("first revocation");

        // THE BACKWARD STEP, as state.
        let future = chrono::Utc::now() + chrono::Duration::hours(1);
        {
            let client = backend.get_client().await.unwrap();
            client
                .execute(
                    "UPDATE cirislens.federation_revocations SET admitted_at = $1 \
                     WHERE revoked_key_id = $2",
                    &[&future, &a],
                )
                .await
                .unwrap();
        }

        let second = mk(&b);
        let second_id = second.revocation_id.clone();
        backend
            .put_revocation(crate::federation::SignedRevocation { revocation: second })
            .await
            .expect("second revocation");

        let served = backend
            .list_signed_revocations_since(Some(future), u32::MAX)
            .await
            .unwrap();
        assert!(
            served
                .iter()
                .any(|r| r.revocation.revocation_id == second_id),
            "a revocation admitted after a backward clock step must still be served to a \
             consumer resuming from the pre-step cursor"
        );
    }

    /// Build a federation KeyRecord with controllable valid_from /
    /// pqc_completed.
    fn fix_section_i_key(
        key_id: &str,
        identity_ref: &str,
        valid_from: chrono::DateTime<chrono::Utc>,
        pqc_completed: bool,
    ) -> crate::federation::KeyRecord {
        // v9.0.0 (CC 5.3.2.4.3.1) — register REAL deterministic hybrid
        // pubkeys so the federation-tier ingest gate can verify
        // attestations signed by this key (see `tier_ingest::test_support`).
        // The ML-DSA-65 PUBKEY is always present (the conformant state for
        // a hybrid key); `pqc_completed` still controls the key's own
        // registration scrub_signature_pqc / pqc_completed_at (what the
        // list_hybrid_pending_keys query filters on), independent of
        // pubkey availability.
        let (ed_pk, mldsa_pk) =
            crate::federation::tier_ingest::test_support::hybrid_pubkeys(key_id);
        crate::federation::KeyRecord {
            key_id: key_id.into(),
            pubkey_ed25519_base64: ed_pk,
            pubkey_ml_dsa_65_base64: mldsa_pk,
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: crate::federation::types::identity_type::AGENT.into(),
            identity_ref: identity_ref.into(),
            valid_from,
            valid_until: None,
            registration_envelope: serde_json::json!({"id": key_id}),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: if pqc_completed {
                Some("c2ln".into())
            } else {
                None
            },
            scrub_key_id: key_id.into(),
            scrub_timestamp: valid_from,
            pqc_completed_at: if pqc_completed {
                Some(valid_from)
            } else {
                None
            },
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            attestation_evidence: None,
            consent_role: None,
            additional_scrubs: Vec::new(),
        }
    }

    /// v13.0.0 (CIRISPersist#365, CC 3.4.7.2) — consent_role round-trips
    /// through put/lookup, OQ-1 overwrite-on-revoke via set_consent_role,
    /// and the consent_role_of resolver — on the Postgres twin. Gated on a
    /// live test PG (skips when `CIRIS_PERSIST_TEST_PG_URL` is unset).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn consent_role_round_trip_overwrite_and_resolver_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::consent::consent_role_of;
        use crate::federation::types::consent_role;
        use crate::federation::FederationDirectory;
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let kid = format!("k-cr-{}", uuid_like());

        // Born with consent_role = peer → round-trips.
        let mut key = fix_section_i_key(&kid, "primitive-cr", now, true);
        key.consent_role = Some(consent_role::PEER.into());
        backend
            .put_public_key(crate::federation::SignedKeyRecord { record: key })
            .await
            .unwrap();
        let got = FederationDirectory::lookup_public_key(&backend, &kid)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(got.consent_role.as_deref(), Some(consent_role::PEER));
        assert_eq!(
            consent_role_of(&backend, &kid).await.unwrap().as_deref(),
            Some(consent_role::PEER)
        );

        // OQ-1 overwrite → authorized_review.
        FederationDirectory::set_consent_role(
            &backend,
            &kid,
            Some(consent_role::AUTHORIZED_REVIEW),
        )
        .await
        .unwrap();
        assert_eq!(
            consent_role_of(&backend, &kid).await.unwrap().as_deref(),
            Some(consent_role::AUTHORIZED_REVIEW)
        );

        // Revoke (overwrite to None).
        FederationDirectory::set_consent_role(&backend, &kid, None)
            .await
            .unwrap();
        assert_eq!(consent_role_of(&backend, &kid).await.unwrap(), None);

        // Unknown key: setter errors, resolver stays total.
        let missing = format!("k-cr-missing-{}", uuid_like());
        assert!(
            FederationDirectory::set_consent_role(&backend, &missing, Some("peer"))
                .await
                .is_err()
        );
        assert_eq!(consent_role_of(&backend, &missing).await.unwrap(), None);
    }

    /// V060 community substrate round-trip on Postgres — parity with
    /// the sqlite `community_round_trip` test. Gated on a live test PG
    /// (skips when `CIRIS_PERSIST_TEST_PG_URL` is unset), same as every
    /// other postgres test.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_round_trip_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let coop = format!("acme-coop-{suffix}");
        let alice = format!("alice-root-{suffix}");
        let bob = format!("bob-root-{suffix}");
        let carol = format!("carol-root-{suffix}");
        // The community key itself is infra-class; the `*-root` members are
        // user-role human identities (trivially steward-bound — the v9.0.0
        // CC 3.2 / CC 3.4.7.1 non-infra membership precondition).
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(&coop, "acme", now, true),
            })
            .await
            .unwrap();
        for kid in [&alice, &bob, &carol] {
            let mut k = fix_section_i_key(kid, "acme", now, true);
            k.identity_type = crate::federation::types::identity_type::USER.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }

        let policy = serde_json::json!({ "cohort_scope": "community" });
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    &coop,
                    crate::federation::Community {
                        community_key_id: coop.clone(),
                        community_name: "Acme Co-op".into(),
                        members: [&alice, &bob, &carol]
                            .iter()
                            .map(|k| crate::federation::CommunityMember {
                                key_id: (*k).clone(),
                                joined_at: now,
                                role: None,
                            })
                            .collect(),
                        founded_at: now,
                        consensus_protocol: "majority".into(),
                        policy_blob: Some(policy.clone()),
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();

        let got = backend
            .lookup_community(&coop)
            .await
            .unwrap()
            .expect("community exists");
        assert_eq!(got.community_name, "Acme Co-op");
        assert_eq!(got.members.len(), 3);
        assert_eq!(got.consensus_protocol, "majority");
        assert_eq!(got.policy_blob.as_ref(), Some(&policy));
        assert_eq!(got.persist_row_hash.len(), 64);

        // Membership GIN/@> fan-out returns the community for each member.
        for member in [&alice, &bob, &carol] {
            let communities = backend.list_communities_for_member(member).await.unwrap();
            assert_eq!(communities.len(), 1, "for member {member}");
            assert_eq!(&communities[0].community_key_id, &coop);
        }
        let none = backend
            .list_communities_for_member(&format!("nobody-{suffix}"))
            .await
            .unwrap();
        assert!(none.is_empty());
    }

    /// v4.14.0 (CIRISPersist#152, CEG 0.18 §10.1.4) — the self/family
    /// at-rest DEK cascade end-to-end on Postgres (parity with the sqlite
    /// `at_rest_self_cascade_round_trip_and_fail_secure`): ciphertext at
    /// rest, granted recipient reads plaintext, fail-secure exclusion of a
    /// keyless occurrence, NotGranted for a non-recipient.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn at_rest_self_cascade_round_trip_and_fail_secure_pg() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer,
        };
        use crate::federation::types::cohort_scope::SELF;
        use crate::federation::{BlobStorage, EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let root = format!("root-{suffix}");
        let keyed = format!("occ-keyed-{suffix}");
        let bare = format!("occ-bare-{suffix}");
        let outsider = format!("outsider-{suffix}");
        for kid in [&root, &keyed, &bare, &outsider] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "acme", now, true),
                })
                .await
                .unwrap();
        }

        let x_pub = ciris_crypto::x25519::public_from_secret(&[0x42; 32]);
        let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();

        let occ =
            |occ_key: &str, enc: Option<EncryptionPubkeys>| crate::federation::IdentityOccurrence {
                identity_key_id: root.clone(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: enc,
                transport_binding: None,
                persist_row_hash: String::new(),
            };
        backend
            .put_identity_occurrence_local(occ(
                &keyed,
                Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
            ))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(occ(&bare, None))
            .await
            .unwrap();

        let plaintext = b"a private note, scoped to self (pg)";
        let result = encrypt_and_cascade(&backend, SELF, &root, plaintext, Some("text/plain"))
            .await
            .unwrap();
        assert_eq!(result.granted, vec![keyed.clone()]);
        assert_eq!(result.excluded, vec![bare.clone()]);

        // Ciphertext at rest (≠ plaintext) carrying the at-rest magic.
        let stored = backend
            .get_blob(&result.at_rest_sha256)
            .await
            .unwrap()
            .expect("bytes present");
        let stored_bytes = match stored {
            crate::federation::BlobBody::Inline(b) => b,
            other => panic!("expected inline ciphertext, got {other:?}"),
        };
        assert_ne!(stored_bytes, plaintext.to_vec());
        assert!(crate::federation::at_rest_cascade::AtRestEnvelope::has_magic(&stored_bytes));

        // No holds_bytes (structural invisibility).
        assert!(backend
            .list_local_holders(&result.at_rest_sha256)
            .await
            .unwrap()
            .is_empty());

        // Granted recipient reads plaintext back.
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, &keyed)
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // Fail-secure-excluded + non-recipient both → NotGranted.
        for viewer in [&bare, &outsider] {
            let err = read_for_viewer(&backend, &result.at_rest_sha256, viewer)
                .await
                .unwrap_err();
            assert!(
                matches!(err, crate::federation::BlobError::NotGranted { .. }),
                "viewer {viewer} must be denied, got: {err:?}"
            );
        }

        // Only the keyed occurrence holds a grant row.
        let recipients = backend
            .list_at_rest_grant_recipients(&result.at_rest_sha256)
            .await
            .unwrap();
        assert_eq!(recipients, vec![keyed.clone()]);
    }

    /// v6.1.0 (CIRISPersist#161 Ask 2/4, CEG §11.7.1 / §10.1.4) — the
    /// membership-change re-key keystone on Postgres (parity with the
    /// sqlite `rekey_*` tests): a newcomer family member gains access to a
    /// pre-existing family blob via the retroactive ADD walk; a keyless
    /// newcomer is fail-secure excluded; both are idempotent; the
    /// membership `hard_case:*` rows are emitted.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn rekey_family_member_add_keystone_pg() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let s = uuid_like();
        let fam = format!("fam-{s}");
        let alice = format!("alice-{s}");
        let carol = format!("carol-{s}");
        let bob = format!("bob-{s}");
        let alice_p = format!("alice-phone-{s}");
        let carol_p = format!("carol-phone-{s}");
        let bob_p = format!("bob-phone-{s}");
        for kid in [&fam, &alice, &carol, &bob, &alice_p, &carol_p, &bob_p] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "acme", now, true),
                })
                .await
                .unwrap();
        }

        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        let bare = |occ_key: &str, identity: &str| crate::federation::IdentityOccurrence {
            identity_key_id: identity.into(),
            occurrence_key_id: occ_key.into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: now,
            valid_until: None,
            encryption_pubkeys: None,
            transport_binding: None,
            persist_row_hash: String::new(),
        };

        // alice founds the family + writes a family blob.
        backend
            .put_identity_occurrence_local(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        let family = |members: Vec<&str>| {
            crate::federation::tier_ingest::test_support::sign_family(
                &fam,
                crate::federation::Family {
                    family_key_id: fam.clone(),
                    family_name: "Household".into(),
                    members: members
                        .into_iter()
                        .map(|k| crate::federation::FamilyMember {
                            key_id: k.into(),
                            joined_at: now,
                            role: None,
                        })
                        .collect(),
                    founded_at: now,
                    consensus_protocol: "unanimous".into(),
                    consensus_protocol_entrenched: false,
                    persist_row_hash: String::new(),
                },
            )
        };
        // Roster is set up front (V067 models removal, not roster
        // mutation): alice + bob + carol. Only alice has an occurrence at
        // write time, so the blob reaches only alice-phone; bob's keyed
        // occurrence and carol's keyless one are registered afterwards.
        backend
            .put_family(family(vec![&alice, &bob, &carol]))
            .await
            .unwrap();
        let plaintext = b"family blob written before bob/carol registered devices (pg)";
        let result = encrypt_and_cascade(&backend, FAMILY, &fam, plaintext, None)
            .await
            .unwrap();
        assert_eq!(result.granted, vec![alice_p.clone()]);

        // bob registers a KEYED occurrence → gains access via the walk.
        backend
            .put_identity_occurrence_local(keyed(&bob_p, &bob, 0x22))
            .await
            .unwrap();
        let observed = chrono::Utc::now();
        let rk = rekey_family_member_add(&backend, &fam, &bob, observed)
            .await
            .unwrap();
        assert_eq!(rk.blobs_scanned, 1);
        assert_eq!(rk.granted, vec![(bob_p.clone(), 1)]);
        assert!(rk.excluded.is_empty());
        let recovered = read_for_viewer(&backend, &result.at_rest_sha256, &bob_p)
            .await
            .unwrap();
        assert_eq!(recovered, plaintext);

        // Idempotent: a second walk at the same instant adds zero grants.
        let rk2 = rekey_family_member_add(&backend, &fam, &bob, observed)
            .await
            .unwrap();
        assert_eq!(rk2.granted, vec![(bob_p.clone(), 0)]);

        // carol registers a KEYLESS occurrence → fail-secure excluded.
        backend
            .put_identity_occurrence_local(bare(&carol_p, &carol))
            .await
            .unwrap();
        let observed2 = chrono::Utc::now();
        let rk3 = rekey_family_member_add(&backend, &fam, &carol, observed2)
            .await
            .unwrap();
        assert!(rk3.granted.is_empty());
        assert_eq!(rk3.excluded, vec![carol_p.clone()]);
        assert!(read_for_viewer(&backend, &result.at_rest_sha256, &carol_p)
            .await
            .is_err());

        // hard_case rows present for this family (filter by target via the
        // membership-change kind, then narrow to our family_key_id).
        let mc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::FAMILY_MEMBERSHIP_CHANGE.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(mc
            .iter()
            .any(|e| e.target_key_id.as_deref() == Some(fam.as_str())
                && e.subject_key_id.as_deref() == Some(carol_p.as_str())));
        let exc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(exc
            .iter()
            .any(|e| e.subject_key_id.as_deref() == Some(carol_p.as_str())));
    }

    /// v9.0.0 G5 (CC 4.4.3.2.1 / 4.4.3.2.2) — PG parity for the community
    /// DEK cascade + rotation-on-removal: v2 key_grant per keyed member,
    /// fail-secure exclude + hard_case for a keyless member, the
    /// infrastructure plaintext opt-out, rotation-on-removal forward
    /// secrecy, and the v2-only guarantee — all run-scoped by `uuid_like`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_dek_cascade_rotation_and_v2_only_pg() {
        use crate::federation::community_dek::orchestrate::{
            emit_excluded_hard_cases, encrypt_and_cascade_community, read_for_community_viewer,
        };
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::types::cohort_scope::COMMUNITY;
        use crate::federation::{BlobStorage, EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm = format!("comm-{s}");
        let infra = format!("infra-{s}");
        let fakeinfra = format!("fakeinfra-{s}");
        let alice = format!("alice-{s}");
        let bob = format!("bob-{s}");
        let alice_p = format!("alice-occ-{s}");
        let bob_p = format!("bob-occ-{s}");
        for kid in [&comm, &infra, &fakeinfra, &alice, &bob, &alice_p, &bob_p] {
            let mut record = fix_section_i_key(kid, "acme", now, true);
            // Community members (alice/bob) are user-role humans — trivially
            // steward-bound, satisfying the v9.0.0 G3 steward-binding precondition
            // for non-infra community membership (CC 3.4.7.1). The DEK cascade
            // under test is orthogonal to membership authority.
            if kid == &alice || kid == &bob {
                record.identity_type = crate::federation::types::identity_type::USER.into();
            }
            // SecReview F2: the infra opt-out is honored only when the
            // community's OWN key is the `substrate_persist` governance
            // authority — stamp the infra community's key so the opt-out arm
            // below exercises the AUTHORIZED carve-out.
            if kid == &infra {
                record.identity_type =
                    crate::federation::types::identity_type::SUBSTRATE_PERSIST.into();
            }
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record })
                .await
                .unwrap();
        }

        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        let bare = |occ_key: &str, identity: &str| crate::federation::IdentityOccurrence {
            identity_key_id: identity.into(),
            occurrence_key_id: occ_key.into(),
            device_class: crate::federation::types::device_class::AGENT.into(),
            hardware_attestation: None,
            asserted_at: now,
            valid_until: None,
            encryption_pubkeys: None,
            transport_binding: None,
            persist_row_hash: String::new(),
        };
        backend
            .put_identity_occurrence_local(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(bare(&bob_p, &bob))
            .await
            .unwrap();

        let community = |key: &str, members: Vec<&str>, policy: Option<serde_json::Value>| {
            crate::federation::tier_ingest::test_support::sign_community(
                key,
                crate::federation::Community {
                    community_key_id: key.into(),
                    community_name: "Co-op".into(),
                    members: members
                        .into_iter()
                        .map(|k| crate::federation::CommunityMember {
                            key_id: k.into(),
                            joined_at: now,
                            role: None,
                        })
                        .collect(),
                    founded_at: now,
                    consensus_protocol: "majority".into(),
                    policy_blob: policy,
                    persist_row_hash: String::new(),
                },
            )
        };

        // ── non-infra community: keyed alice granted, keyless bob excluded.
        backend
            .put_community(community(&comm, vec![&alice, &bob], None))
            .await
            .unwrap();
        let r0 =
            encrypt_and_cascade_community(&backend, &comm, b"minutes (pg)", Some("text/plain"))
                .await
                .unwrap();
        assert_eq!(r0.epoch, 0);
        assert_eq!(r0.granted, vec![alice_p.clone()]);
        assert_eq!(r0.excluded, vec![bob_p.clone()]);
        assert_eq!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"minutes (pg)"
        );
        assert!(matches!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &bob_p)
                .await
                .unwrap_err(),
            crate::federation::BlobError::NotGranted { .. }
        ));
        emit_excluded_hard_cases(&backend, &r0, chrono::Utc::now())
            .await
            .unwrap();
        let exc = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::RECIPIENT_EXCLUDED.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(exc
            .iter()
            .any(|e| e.subject_key_id.as_deref() == Some(bob_p.as_str())
                && e.detail.get("cohort_scope").and_then(|v| v.as_str()) == Some(COMMUNITY)));

        // ── infrastructure community opts OUT (no DEK; cascade refuses).
        backend
            .put_community(community(
                &infra,
                vec![&alice],
                Some(serde_json::json!({ "cohort_subkind": "infrastructure" })),
            ))
            .await
            .unwrap();
        assert!(matches!(
            encrypt_and_cascade_community(&backend, &infra, b"root", None)
                .await
                .unwrap_err(),
            crate::federation::BlobError::InvalidArgument(_)
        ));
        assert!(backend
            .community_dek_get_self_retention(&infra, 0)
            .await
            .unwrap()
            .is_none());

        // ── SecReview F2: an `infrastructure`-LABELED community whose own
        //    key is NOT substrate_persist (fakeinfra) is NOT exempted — the
        //    DEK cascade STILL runs (fail-secure: a self-applied infra label
        //    can never force content to plaintext).
        backend
            .put_community(community(
                &fakeinfra,
                vec![&alice],
                Some(serde_json::json!({ "cohort_subkind": "infrastructure" })),
            ))
            .await
            .unwrap();
        let fake = encrypt_and_cascade_community(&backend, &fakeinfra, b"not canonical", None)
            .await
            .expect("unauthorized infra label must NOT opt out of the DEK cascade");
        assert_eq!(fake.epoch, 0);
        assert_eq!(fake.granted, vec![alice_p.clone()]);
        assert!(backend
            .community_dek_get_self_retention(&fakeinfra, 0)
            .await
            .unwrap()
            .is_some());

        // ── rotation-on-removal: remove bob → epoch bumps; fresh DEK; the
        //    pre-rotation blob is unchanged (forward-only).
        backend
            .put_community_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                    &comm,
                    crate::federation::CommunityMembershipRevocation {
                        community_key_id: comm.clone(),
                        removed_identity_key_id: bob.clone(),
                        removed_at: now,
                        effective_at: now,
                        reason: None,
                        witness_set: vec![],
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();
        assert_eq!(backend.community_dek_current_epoch(&comm).await.unwrap(), 1);
        let r1 = encrypt_and_cascade_community(&backend, &comm, b"post-removal (pg)", None)
            .await
            .unwrap();
        assert_eq!(r1.epoch, 1);
        assert_eq!(r1.granted, vec![alice_p.clone()]);
        assert_ne!(r0.at_rest_sha256, r1.at_rest_sha256);
        assert_eq!(
            read_for_community_viewer(&backend, &r1.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"post-removal (pg)"
        );
        // The PRE-rotation blob is untouched — but bob never had a grant
        // (keyless), so he still cannot read; alice still can.
        assert_eq!(
            read_for_community_viewer(&backend, &r0.at_rest_sha256, &alice_p)
                .await
                .unwrap(),
            b"minutes (pg)"
        );

        // ── v2-only: every member-grant row is the v2 hybrid algorithm.
        let client = backend.get_client().await.unwrap();
        let rows = client
            .query(
                "SELECT DISTINCT wrap_algorithm \
                 FROM cirislens.federation_community_dek_member_grants \
                 WHERE community_key_id = $1",
                &[&comm],
            )
            .await
            .unwrap();
        assert!(!rows.is_empty());
        for r in &rows {
            let alg: String = r.get("wrap_algorithm");
            assert_eq!(alg, crate::federation::at_rest_cascade::WRAP_ALGORITHM_V2);
        }
    }

    /// SecReview F4 (PG parity): a FUTURE-DATED community membership
    /// revocation `effective_at` is REJECTED before any write; a non-future
    /// one is accepted AND bumps the DEK epoch. Run-scoped uuid-suffixed ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_revocation_rejects_future_dated_effective_at_pg() {
        use crate::federation::{BlobStorage, FederationDirectory};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm = format!("comm-f4-{s}");
        let bob = format!("bob-f4-{s}");
        for kid in [&comm, &bob] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "acme", now, true),
                })
                .await
                .unwrap();
        }
        let rev = |effective: chrono::DateTime<chrono::Utc>| {
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &comm,
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: comm.clone(),
                    removed_identity_key_id: bob.clone(),
                    removed_at: effective,
                    effective_at: effective,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            )
        };
        let future = chrono::Utc::now() + chrono::Duration::days(30);
        let err = backend
            .put_community_membership_revocation(rev(future))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(_)),
            "future-dated effective_at must be rejected, got {err:?}"
        );
        assert_eq!(backend.community_dek_current_epoch(&comm).await.unwrap(), 0);
        backend
            .put_community_membership_revocation(rev(chrono::Utc::now()))
            .await
            .expect("non-future revocation accepted");
        assert_eq!(backend.community_dek_current_epoch(&comm).await.unwrap(), 1);
    }

    /// CC 4.4.3.2.8 / #308 (PG parity): the `affiliations` cohort runs the full
    /// membership lifecycle (add → active-members → revoke + epoch bump) through
    /// the SAME community machinery on the Postgres backend.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn affiliations_cohort_membership_lifecycle_pg() {
        use crate::federation::cohort::{Cohort, RosterMember};
        use crate::federation::{BlobStorage, FederationDirectory};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let coop = format!("aff-coop-{suffix}");
        let alice = format!("aff-alice-{suffix}");
        let carol = format!("aff-carol-{suffix}");
        // Community key (infra-class) + two user-role human members.
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(&coop, "acme", now, true),
            })
            .await
            .unwrap();
        for kid in [&alice, &carol] {
            let mut k = fix_section_i_key(kid, "acme", now, true);
            k.identity_type = crate::federation::types::identity_type::USER.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    &coop,
                    crate::federation::Community {
                        community_key_id: coop.clone(),
                        community_name: "Affiliations Co-op".into(),
                        members: vec![crate::federation::CommunityMember {
                            key_id: alice.clone(),
                            joined_at: now,
                            role: None,
                        }],
                        founded_at: now,
                        consensus_protocol: "majority".into(),
                        policy_blob: Some(serde_json::json!({ "cohort_scope": "affiliations" })),
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();

        // add via the affiliations cohort.
        // v31.0.0 (CIRISPersist#654) — signed over the GROWN community envelope.
        let carol_row = RosterMember {
            key_id: carol.clone(),
            joined_at: now,
            role: Some("member".into()),
        };
        let admit = crate::federation::cohort::test_support::admit_roster_member_via(
            &backend,
            &coop,
            Cohort::Affiliations,
            &coop,
            &carol_row,
        )
        .await;
        let added = backend
            .add_member(Cohort::Affiliations, &coop, carol_row, &admit)
            .await
            .expect("affiliations add_member");
        assert!(added);

        let active: Vec<String> = backend
            .active_members(Cohort::Affiliations, &coop)
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(active.contains(&carol));
        // Shared roster: identical via the `community` cohort.
        let via_community: Vec<String> = backend
            .active_members(Cohort::Community, &coop)
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert_eq!(active, via_community);

        assert_eq!(backend.community_dek_current_epoch(&coop).await.unwrap(), 0);
        backend
            .revoke_member(
                Cohort::Affiliations,
                &coop,
                &carol,
                crate::federation::tier_ingest::test_support::sign_revoke_spec(
                    Cohort::Affiliations,
                    &coop,
                    &coop,
                    &carol,
                    chrono::Utc::now(),
                    Some("left".into()),
                    vec![],
                ),
            )
            .await
            .expect("affiliations revoke_member");
        assert_eq!(
            backend.community_dek_current_epoch(&coop).await.unwrap(),
            1,
            "affiliations removal bumps the CommunityDek epoch (forward secrecy)"
        );
        let active_after: Vec<String> = backend
            .active_members(Cohort::Affiliations, &coop)
            .await
            .unwrap()
            .into_iter()
            .map(|m| m.key_id)
            .collect();
        assert!(!active_after.contains(&carol));
    }

    /// SecReview F5 (PG parity): INSERT + hard_case + epoch-bump are ONE
    /// transaction — if the epoch bump fails, the revocation INSERT is
    /// rolled back. Induce a deterministic bump failure by pre-seeding the
    /// epoch row at i64::MAX so the in-transaction `epoch + 1` overflows
    /// bigint, then assert NEITHER the revocation row NOR a hard_case event
    /// was committed. Run-scoped uuid-suffixed ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn community_revocation_atomic_on_bump_failure_pg() {
        use crate::federation::hard_case::{kind, HardCaseFilter};
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let s = uuid_like();
        let comm = format!("comm-f5-{s}");
        let bob = format!("bob-f5-{s}");
        for kid in [&comm, &bob] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "acme", now, true),
                })
                .await
                .unwrap();
        }
        // Pre-seed the epoch at i64::MAX so the in-transaction `epoch + 1`
        // overflows bigint (deterministic bump failure).
        {
            let client = backend.get_client().await.unwrap();
            client
                .execute(
                    "INSERT INTO cirislens.federation_community_dek_epoch \
                        (community_key_id, epoch, rotated_at) VALUES ($1, $2, NOW())",
                    &[&comm, &i64::MAX],
                )
                .await
                .unwrap();
        }
        let rev =
            crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                &comm,
                crate::federation::CommunityMembershipRevocation {
                    community_key_id: comm.clone(),
                    removed_identity_key_id: bob.clone(),
                    removed_at: now,
                    effective_at: now,
                    reason: None,
                    witness_set: vec![],
                    persist_row_hash: String::new(),
                },
            );
        let err = backend
            .put_community_membership_revocation(rev)
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::Backend(_)),
            "bump overflow should surface, got {err:?}"
        );
        // The revocation INSERT rolled back — no durable revocation row.
        assert!(backend
            .list_community_membership_revocations_for(&comm)
            .await
            .unwrap()
            .is_empty());
        // And no hard_case event was committed either.
        let events = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::COMMUNITY_MEMBERSHIP_CHANGE.into()),
                since: None,
            })
            .await
            .unwrap();
        assert!(
            !events
                .iter()
                .any(|e| e.subject_key_id.as_deref() == Some(bob.as_str())),
            "hard_case must roll back with the txn"
        );
    }

    /// v6.2.0 (#161 A4/A5) — PG parity for the roster-grow forward path:
    /// a genuinely-new member (NOT on the roster at write time) is added by
    /// `rekey_family_member_add` (exercising the `add_family_member` UPDATE
    /// path + concurrent-guard) and is then served a FUTURE family write.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn add_family_member_grows_roster_and_serves_future_writes_pg() {
        use crate::federation::at_rest_cascade::orchestrate::{
            encrypt_and_cascade, read_for_viewer, rekey_family_member_add,
        };
        use crate::federation::types::cohort_scope::FAMILY;
        use crate::federation::{EncryptionPubkeys, FederationDirectory};
        use base64::{engine::general_purpose::STANDARD as B64, Engine as _};

        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let now = chrono::Utc::now();
        let s = uuid_like();
        let fam = format!("fam-{s}");
        let alice = format!("alice-{s}");
        let bob = format!("bob-{s}");
        let alice_p = format!("alice-phone-{s}");
        let bob_p = format!("bob-phone-{s}");
        for kid in [&fam, &alice, &bob, &alice_p, &bob_p] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "acme", now, true),
                })
                .await
                .unwrap();
        }
        let keyed = |occ_key: &str, identity: &str, seed: u8| {
            let x_pub = ciris_crypto::x25519::public_from_secret(&[seed; 32]);
            let (_mp, ml_pub) = ciris_crypto::ml_kem::generate_keypair().unwrap();
            crate::federation::IdentityOccurrence {
                identity_key_id: identity.into(),
                occurrence_key_id: occ_key.into(),
                device_class: crate::federation::types::device_class::AGENT.into(),
                hardware_attestation: None,
                asserted_at: now,
                valid_until: None,
                encryption_pubkeys: Some(EncryptionPubkeys {
                    x25519_base64: B64.encode(x_pub),
                    ml_kem_768_base64: B64.encode(&ml_pub),
                }),
                transport_binding: None,
                persist_row_hash: String::new(),
            }
        };
        backend
            .put_identity_occurrence_local(keyed(&alice_p, &alice, 0x11))
            .await
            .unwrap();
        // Roster starts with alice ONLY — bob is genuinely new.
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                &fam,
                crate::federation::Family {
                    family_key_id: fam.clone(),
                    family_name: "Household".into(),
                    members: vec![crate::federation::FamilyMember {
                        key_id: alice.clone(),
                        joined_at: now,
                        role: None,
                    }],
                    founded_at: now,
                    consensus_protocol: "unanimous".into(),
                    consensus_protocol_entrenched: false,
                    persist_row_hash: String::new(),
                },
            ))
            .await
            .unwrap();

        let blob1 = encrypt_and_cascade(&backend, FAMILY, &fam, b"before bob (pg)", None)
            .await
            .unwrap();
        assert_eq!(blob1.granted, vec![alice_p.clone()]);

        backend
            .put_identity_occurrence_local(keyed(&bob_p, &bob, 0x22))
            .await
            .unwrap();
        // v31.0.0 (CIRISPersist#654) — PG parity for the ORDER: the key-less
        // driver refuses a newcomer the roster does not name; the SIGNED
        // admission door is what grows the roster.
        let too_early = rekey_family_member_add(&backend, &fam, &bob, chrono::Utc::now())
            .await
            .expect_err("the driver must not grow the roster itself");
        assert!(
            too_early.to_string().contains("not an active member"),
            "the refusal names the precondition: {too_early}"
        );
        let fam_before = backend.lookup_family(&fam).await.unwrap().unwrap();
        assert!(
            !fam_before.members.iter().any(|m| m.key_id == bob),
            "the refused driver call left the roster alone"
        );
        let bob_row = crate::federation::FamilyMember {
            key_id: bob.clone(),
            joined_at: now,
            role: None,
        };
        let admit =
            crate::federation::cohort::test_support::admit_family(&fam, &fam_before, &bob_row);
        assert!(backend
            .add_family_member(&fam, bob_row, &admit)
            .await
            .expect("signed roster grow"));

        let rk = rekey_family_member_add(&backend, &fam, &bob, chrono::Utc::now())
            .await
            .unwrap();
        assert_eq!(rk.granted, vec![(bob_p.clone(), 1)]);
        assert!(read_for_viewer(&backend, &blob1.at_rest_sha256, &bob_p)
            .await
            .is_ok());

        // Roster grew (the PG UPDATE path).
        let looked = backend.lookup_family(&fam).await.unwrap().unwrap();
        assert!(looked.members.iter().any(|m| m.key_id == bob));

        // Forward path: a NEW write reaches BOTH alice + bob.
        let blob2 = encrypt_and_cascade(&backend, FAMILY, &fam, b"after bob (pg)", None)
            .await
            .unwrap();
        let mut granted = blob2.granted.clone();
        granted.sort();
        let mut want = vec![alice_p.clone(), bob_p.clone()];
        want.sort();
        assert_eq!(granted, want);

        // Idempotent re-add: no-op, no duplicate roster entry.
        assert!(!backend
            .add_family_member(
                &fam,
                crate::federation::FamilyMember {
                    key_id: bob.clone(),
                    joined_at: chrono::Utc::now(),
                    role: None,
                },
                &admit,
            )
            .await
            .unwrap());
        let looked2 = backend.lookup_family(&fam).await.unwrap().unwrap();
        assert_eq!(
            looked2.members.iter().filter(|m| m.key_id == bob).count(),
            1
        );
    }

    /// §I list_federation_keys round-trip + cursor pagination.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_i_list_federation_keys_cursor() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;
        use crate::read::ReadEngine;

        // Build 4 distinct keys for one identity_ref so the filter
        // narrows to our fixture set. valid_from staggered so cursor
        // ordering is deterministic.
        let identity = format!("agent-§i-{}", uuid_like());
        let base = chrono::Utc::now() - chrono::Duration::hours(2);
        let mut key_ids: Vec<String> = Vec::new();
        for i in 0..4 {
            let kid = format!("k-§i-{}-{i}", uuid_like());
            let mut key = fix_section_i_key(
                &kid,
                &identity,
                base + chrono::Duration::minutes(i64::from(i)),
                i % 2 == 0, // alternate pqc_completed
            );
            // #442: the pg SELECT once omitted `roles` and the tolerant
            // decoder silently returned [] — populate the set so the
            // page assertions below catch a dropped column.
            key.capability_roles = vec!["agent".into(), "substrate_persist".into()];
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: key })
                .await
                .unwrap();
            key_ids.push(kid);
        }
        key_ids.reverse(); // newest-first

        let filter = crate::read::FederationKeyFilter {
            agent_id_hash: Some(identity.clone()),
            ..Default::default()
        };

        // Page 1
        let p1 = backend
            .list_federation_keys(
                filter.clone(),
                None,
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(p1.items.len(), 2);
        assert_eq!(p1.items[0].key_id, key_ids[0]);
        assert_eq!(p1.items[1].key_id, key_ids[1]);
        for k in &p1.items {
            assert_eq!(
                k.capability_roles,
                vec!["agent".to_string(), "substrate_persist".to_string()],
                "#442: list_federation_keys must project the stored roles set"
            );
        }
        let c1 = p1.next_cursor.expect("page 2 cursor");

        // Page 2 — exact-fill (2 remaining items, limit=2). The
        // pagination contract (matching §A) is "next_cursor is None
        // only when items.len() < limit"; an exact-match page returns
        // Some(cursor) and the consumer fetches one more page that
        // yields zero items. Page 3 below is the empty-tail probe.
        let p2 = backend
            .list_federation_keys(
                filter.clone(),
                Some(c1),
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(p2.items.len(), 2);
        assert_eq!(p2.items[0].key_id, key_ids[2]);
        assert_eq!(p2.items[1].key_id, key_ids[3]);
        let c2 = p2.next_cursor.expect("page 3 cursor (exact-fill page)");

        // Page 3 — empty tail, cursor None.
        let p3 = backend
            .list_federation_keys(
                filter.clone(),
                Some(c2),
                2,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert!(p3.items.is_empty(), "no more items past 4-key fixture");
        assert!(p3.next_cursor.is_none(), "empty page → no cursor");

        // PQC filter: should return only 2 keys (i=0, i=2 had pqc=true,
        // i.e. key_ids[3] and key_ids[1] after reverse).
        let pqc_filter = crate::read::FederationKeyFilter {
            agent_id_hash: Some(identity.clone()),
            pqc_completed: Some(true),
            ..Default::default()
        };
        let pqc_page = backend
            .list_federation_keys(
                pqc_filter,
                None,
                100,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(pqc_page.items.len(), 2, "two pqc-complete keys");
        for k in &pqc_page.items {
            assert!(k.pqc_completed_at.is_some());
        }
    }

    /// §I list_revocations round-trip.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn read_section_i_list_revocations_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;
        use crate::read::ReadEngine;

        let identity = format!("agent-§i-rev-{}", uuid_like());
        let now = chrono::Utc::now();

        // Need attesting key + revoking key + a target key for the
        // revocation FK shape.
        let revoking_id = format!("revoke-§i-{}", uuid_like());
        let revoked_id = format!("victim-§i-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(&revoking_id, &identity, now, false),
            })
            .await
            .unwrap();
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(
                    &revoked_id,
                    &identity,
                    now - chrono::Duration::minutes(1),
                    false,
                ),
            })
            .await
            .unwrap();

        // revocation_id column is `::uuid` cast in put_revocation —
        // must be a valid UUID string, not the uuid_like() hex token.
        let rev_id = uuid::Uuid::new_v4().to_string();
        // v31.0.0 (#659) — the typed columns are BOUND INTO the bytes the
        // scrub signature covers, through the one shared producer.
        let rev = crate::federation::tier_ingest::test_support::seal_revocation(
            crate::federation::Revocation {
                revocation_id: rev_id.clone(),
                revoked_key_id: revoked_id.clone(),
                revoking_key_id: revoking_id.clone(),
                reason: Some("test".into()),
                revoked_at: now,
                effective_at: now,
                revocation_envelope: serde_json::json!({"id": rev_id}),
                original_content_hash: String::new(),
                scrub_signature_classical: String::new(),
                scrub_signature_pqc: None,
                scrub_key_id: revoking_id.clone(),
                scrub_timestamp: now,
                pqc_completed_at: None,
                observed_region: crate::federation::verify_coord::region::US.into(),
                revoked_after: None,
                persist_row_hash: String::new(),
            },
        );
        grant_slash(&backend, &revoking_id).await;
        backend
            .put_revocation(crate::federation::SignedRevocation { revocation: rev })
            .await
            .unwrap();

        let page = backend
            .list_revocations(
                crate::read::RevocationFilter {
                    revoked_key_id: Some(revoked_id.clone()),
                    ..Default::default()
                },
                None,
                100,
                crate::scope::CallerScope::Unauthenticated,
            )
            .await
            .unwrap();
        assert_eq!(page.items.len(), 1);
        assert_eq!(page.items[0].revoked_key_id, revoked_id);
        assert_eq!(page.items[0].revoking_key_id, revoking_id);
    }

