    // ─── Admission-gate tests (v2.4.0, CIRISPersist#102 Ask 3) ──────

    /// Build a federation KeyRecord with parameterized identity_type
    /// — covers the `accord_holder` vs `steward` distinction the
    /// admission gate switches on for `accord:*` dimensions.
    /// v2.5.0 (CIRISPersist#102 Ask 8): when `identity_type =
    /// accord_holder` the helper auto-fills a valid hardware-
    /// attestation evidence value so the new admission gate
    /// doesn't reject the fixture.
    fn pg_admission_key(
        key_id: &str,
        identity_ref: &str,
        identity_type: &str,
    ) -> crate::federation::KeyRecord {
        let mut k = fix_section_i_key(key_id, identity_ref, chrono::Utc::now(), false);
        k.identity_type = identity_type.into();
        if identity_type == crate::federation::types::identity_type::ACCORD_HOLDER {
            k.attestation_evidence = Some(serde_json::json!({
                "platform_attestation": {
                    "Android": {
                        "key_attestation_chain": [
                            vec![0x30u8, 0x82, 0x01, 0x00],
                            vec![0x30u8, 0x82, 0x02, 0x00],
                        ],
                        "play_integrity_token": "eyJhbGciOiJIUzI1NiJ9.fake.token",
                        "strongbox_backed": true,
                    }
                },
                "nonce_captured_at": chrono::Utc::now().to_rfc3339(),
            }));
        }
        k
    }

    /// v9.0.0 (CC 5.3.2.4.3.1) — (re-)SEAL a federation-tier PG test
    /// attestation with its `attesting_key_id`'s deterministic hybrid key so
    /// the mandatory federation-tier ingest gate verifies it. Call AFTER any
    /// post-construction mutation of `attestation_envelope` /
    /// `attesting_key_id` / `asserted_at` / `expires_at` / any of the five
    /// typed columns. Matching pubkeys are registered via
    /// [`fix_section_i_key`] / [`pg_admission_key`].
    ///
    /// v31.0.0 (CIRISPersist#598) — this helper is the postgres twin of
    /// `memory.rs::resign_fix` and `sqlite.rs::resign_fed`, and it was the ONLY
    /// one of the three still hand-rolling `sign_envelope`. Both siblings had
    /// already been redirected through
    /// [`tier_ingest::test_support::reseal`](crate::federation::tier_ingest::test_support::reseal);
    /// this one had not, so every postgres attestation fixture in this file
    /// descended from `pg_scores_attestation` was signed WITHOUT its
    /// `asserted_at` / `expires_at` twins and — wherever the envelope was
    /// replaced wholesale after construction — without its #643 typed-column
    /// mirror either. Forty-odd postgres tests were certifying a row shape no
    /// host can write, and none of them could see it, because the sqlite and
    /// memory arms of the same witnesses were sealed correctly.
    ///
    /// The three re-sign helpers now differ in NAME only. That is the point:
    /// `feedback_test_every_backend_not_just_memory` is this exact class, and
    /// the way a backend arm drifts is by keeping its own copy of a step the
    /// other arms centralized.
    fn pg_resign(row: &mut crate::federation::Attestation) {
        crate::federation::tier_ingest::test_support::reseal(row);
    }

    fn pg_scores_attestation(
        attesting: &str,
        attested: &str,
        scrub_key_id: &str,
        dimension: &str,
    ) -> crate::federation::Attestation {
        // attestation_id is `::uuid`-cast on the postgres write
        // path — needs a real UUID per `project_test_fixtures_uuid_vs_uuid_like`.
        // weight: Some(1.0) exercises the `$5::float8::numeric` cast
        // that put_attestation uses to handle f64→NUMERIC.
        let mut row = crate::federation::Attestation {
            attestation_id: uuid::Uuid::new_v4().to_string(),
            attesting_key_id: attesting.into(),
            attested_key_id: attested.into(),
            attestation_type: crate::federation::types::attestation_type::SCORES.into(),
            weight: Some(1.0),
            asserted_at: chrono::Utc::now(),
            expires_at: None,
            attestation_envelope: serde_json::json!({
                "dimension": dimension,
                "score": 1.0,
                "confidence": 0.9,
            }),
            original_content_hash: "abc123".into(),
            scrub_signature_classical: "c2ln".into(),
            scrub_signature_pqc: None,
            scrub_key_id: scrub_key_id.into(),
            scrub_timestamp: chrono::Utc::now(),
            pqc_completed_at: None,
            persist_row_hash: String::new(),
            subject_key_ids: Vec::new(),
            withdraws_admission_rule: None,
            cohort_scope: "federation".to_string(),
            tier: crate::federation::types::attestation_tier::FEDERATION.to_string(),
            promoted_at: None,
            additional_scrubs: Vec::new(),
        };
        // v9.0.0 — sign the as-built envelope (CC 5.3.2.4.3.1).
        pg_resign(&mut row);
        row
    }

    /// v8.7.1 (CIRISPersist#233) — a `delegates_to` edge `granter →
    /// grantee` bearing `scope` (+ optional `sub_delegation`) on the PG
    /// backend.
    fn pg_delegates_to(
        granter: &str,
        grantee: &str,
        scope: serde_json::Value,
        sub_delegation: bool,
    ) -> crate::federation::Attestation {
        let mut a = pg_scores_attestation(granter, grantee, granter, "x");
        a.attestation_type = crate::federation::types::attestation_type::DELEGATES_TO.into();
        crate::federation::tier_ingest::test_support::reseal(&mut a);
        a.attestation_envelope = serde_json::json!({
            "references_attestation_id": a.attestation_id,
            "scope": scope,
            "sub_delegation": sub_delegation,
        });
        pg_resign(&mut a); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        a
    }

    /// #369 (CC 4.5.4 / §11.11) — no-moderator federation-APPLY gate,
    /// broadened keying, END-TO-END through `put_attestation` (PG backend;
    /// 3-backend parity with memory's decision table + the sqlite twin). A
    /// federation-tier row attested TO a stored moderator-less community
    /// (the membership shape — NO `community_id` envelope field) is refused
    /// fail-secure; the same shape onto a moderatored community lands;
    /// storage-only community ops stay untouched. Run-scoped uuid-suffixed
    /// key ids (shared test DB).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_no_moderator_federate_apply_broadened_keying() {
        use crate::federation::admission::MEMBER_ROLE_FOUNDER;
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let founder_user = format!("nm-user-{suffix}");
        let founder_prim = format!("nm-prim-{suffix}");
        let comm_ok = format!("nm-ok-{suffix}");
        let comm_no = format!("nm-no-{suffix}");
        for (kid, ity) in [
            (&founder_user, crate::federation::types::identity_type::USER),
            (
                &founder_prim,
                crate::federation::types::identity_type::PRIMITIVE,
            ),
            (&comm_ok, crate::federation::types::identity_type::PRIMITIVE),
            (&comm_no, crate::federation::types::identity_type::PRIMITIVE),
        ] {
            let mut k = fix_section_i_key(kid, "nm", now, true);
            k.identity_type = ity.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }
        let put_comm = |cid: &str, founder: &str| {
            crate::federation::tier_ingest::test_support::sign_community(
                cid,
                crate::federation::Community {
                    community_key_id: cid.to_owned(),
                    community_name: "nm-test".into(),
                    members: vec![crate::federation::CommunityMember {
                        key_id: founder.to_owned(),
                        joined_at: now,
                        role: Some(MEMBER_ROLE_FOUNDER.into()),
                    }],
                    founded_at: now,
                    consensus_protocol: crate::federation::types::consensus_protocol::FOUNDER_ONLY
                        .into(),
                    policy_blob: None,
                    persist_row_hash: String::new(),
                },
            )
        };
        // Storage-only put_community is NOT the federate gate — both records
        // (moderatored AND moderator-less) store fine.
        backend
            .put_community(put_comm(&comm_ok, &founder_user))
            .await
            .unwrap();
        backend
            .put_community(put_comm(&comm_no, &founder_prim))
            .await
            .unwrap();

        // (1) Membership shape onto the moderator-less community → REFUSED
        //     fail-secure, nothing stored.
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_scores_attestation(
                    &founder_prim,
                    &comm_no,
                    &founder_prim,
                    "identity_binding:v1",
                ),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(
                err,
                crate::federation::Error::CommunityHasNoModerator { .. }
            ),
            "federation apply keyed on a moderator-less community must refuse, got {err:?}"
        );
        assert_eq!(err.kind(), "federation_community_no_moderator");
        assert!(backend
            .list_attestations_for(&comm_no)
            .await
            .unwrap()
            .is_empty());

        // (2) Same shape onto the MODERATORED community → ADMITTED + stored.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_scores_attestation(
                    &founder_user,
                    &comm_ok,
                    &founder_user,
                    "identity_binding:v1",
                ),
            })
            .await
            .expect("moderatored community continues to federate");
        assert_eq!(
            backend.list_attestations_for(&comm_ok).await.unwrap().len(),
            1
        );

        // (3) Storage-only membership op on the moderator-less community →
        //     untouched (loss-processing / recovery must not be blocked).
        backend
            .put_community_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_community_membership_revocation(
                    &comm_no,
                    crate::federation::CommunityMembershipRevocation {
                        community_key_id: comm_no.clone(),
                        removed_identity_key_id: founder_prim.clone(),
                        removed_at: now,
                        effective_at: now,
                        reason: None,
                        witness_set: Vec::new(),
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .expect("membership revocation is storage, not a federation apply step");

        // (4) The drivable verdict mirrors the apply decision.
        let v = crate::federation::admission::no_moderator_federate_verdict(&backend, &comm_no)
            .await
            .unwrap();
        assert_eq!(
            v,
            serde_json::json!({
                "admitted": false, "community_known": true,
                "reason": "federation_community_no_moderator"
            })
        );
        let v = crate::federation::admission::no_moderator_federate_verdict(&backend, &comm_ok)
            .await
            .unwrap();
        assert_eq!(
            v,
            serde_json::json!({ "admitted": true, "community_known": true })
        );
    }

    /// v9.0.0 (CIRISPersist#236, CC 4.4.3.4.3 / CC 1.13.5) — reject-agency-
    /// on-node-key gate, PG backend (3-backend parity with memory +
    /// sqlite). Covers (a) infra-only → ADMITTED, (b) agency:* → REJECTED
    /// + not stored, (b') legacy unprefixed agency → REJECTED, (c) empty
    /// scope → REJECTED, (d) non-node recipient w/ agency:* → ADMITTED (no
    /// over-reject). Run-scoped uuid-suffixed key ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_node_agency_scope_split_matrix() {
        use crate::federation::types::delegation_scope as ds;
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let owner = format!("owner-{suffix}");
        let node = format!("node-{suffix}");
        let agent = format!("agent-{suffix}");
        // owner = user, node = node-only, agent = agent.
        for (kid, ity) in [
            (&owner, crate::federation::types::identity_type::USER),
            (&node, crate::federation::types::identity_type::NODE),
            (&agent, crate::federation::types::identity_type::AGENT),
        ] {
            let mut k = fix_section_i_key(kid, "x", now, true);
            k.identity_type = ity.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }

        let put = |granter: &str, grantee: &str, scope: serde_json::Value| {
            let a = pg_delegates_to(granter, grantee, scope, false);
            (a.attestation_id.clone(), a)
        };

        // (a) infra-only → ADMITTED.
        let (id_a, att_a) = put(
            &owner,
            &node,
            serde_json::json!([ds::INFRA_NETWORK_PRESENCE, ds::INFRA_SERVE]),
        );
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att_a })
            .await
            .unwrap();
        let stored = backend.list_attestations_for(&node).await.unwrap();
        assert_eq!(stored.len(), 1);
        assert_eq!(stored[0].attestation_id, id_a);

        // (b) agency:* → REJECTED + not stored. THE CC 1.13.5 guard.
        let (id_b, att_b) = put(
            &owner,
            &node,
            serde_json::json!([ds::INFRA_SERVE, ds::AGENCY_ACT_ON_BEHALF]),
        );
        let err = backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att_b })
            .await
            .unwrap_err();
        match err {
            crate::federation::Error::NodeAgencyForbidden {
                ref attested_key_id,
                ref offending_scopes,
            } => {
                assert_eq!(attested_key_id, &node);
                assert_eq!(
                    offending_scopes,
                    &vec![ds::AGENCY_ACT_ON_BEHALF.to_string()]
                );
            }
            other => panic!("expected NodeAgencyForbidden, got {other:?}"),
        }
        assert_eq!(err.kind(), "federation_node_agency_forbidden");
        // Run-scoped: still exactly the one (a) row for this node; id_b absent.
        let after_b = backend.list_attestations_for(&node).await.unwrap();
        assert_eq!(after_b.len(), 1);
        assert!(after_b.iter().all(|r| r.attestation_id != id_b));

        // (b') legacy unprefixed agency kind → REJECTED.
        let (_id, att_legacy) = put(
            &owner,
            &node,
            serde_json::json!([crate::federation::self_at_login::SCOPE_ACT_ON_BEHALF]),
        );
        assert!(matches!(
            backend
                .put_attestation(crate::federation::SignedAttestation {
                    attestation: att_legacy
                })
                .await
                .unwrap_err(),
            crate::federation::Error::NodeAgencyForbidden { .. }
        ));

        // (c) empty scope set → REJECTED.
        let (_id, att_empty) = put(&owner, &node, serde_json::json!([]));
        assert!(matches!(
            backend
                .put_attestation(crate::federation::SignedAttestation {
                    attestation: att_empty
                })
                .await
                .unwrap_err(),
            crate::federation::Error::NodeAgencyForbidden { .. }
        ));

        // (d) NON-node recipient (agent) w/ agency:* → ADMITTED (no over-reject).
        let (id_d, att_d) = put(
            &owner,
            &agent,
            serde_json::json!([ds::AGENCY_ACT_ON_BEHALF, ds::AGENCY_DECIDE]),
        );
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att_d })
            .await
            .unwrap();
        let on_agent = backend.list_attestations_for(&agent).await.unwrap();
        assert_eq!(on_agent.len(), 1);
        assert_eq!(on_agent[0].attestation_id, id_d);
    }

    /// SecReview F1 (PG parity): a DUPLICATE / whitespace node token
    /// (`"node,node"` / `"node, node"`) must NOT bypass the node-agency gate
    /// — `agency:*` on such a node-only key is REJECTED + not stored. A
    /// genuine `node,agent` hybrid is still ADMITTED (no over-reject).
    /// Run-scoped uuid-suffixed key ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_node_agency_duplicate_identity_type_token() {
        use crate::federation::types::{delegation_scope as ds, identity_type};
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let owner = format!("f1-owner-{suffix}");
        let node_dup = format!("f1-node-dup-{suffix}");
        let node_ws = format!("f1-node-ws-{suffix}");
        let hybrid = format!("f1-node-agent-{suffix}");
        for (kid, ity) in [
            (&owner, identity_type::USER.to_string()),
            (&node_dup, "node,node".to_string()),
            (&node_ws, "node, node".to_string()),
            (
                &hybrid,
                format!("{},{}", identity_type::NODE, identity_type::AGENT),
            ),
        ] {
            let mut k = fix_section_i_key(kid, "x", now, true);
            k.identity_type = ity;
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }
        // Dup / whitespace node tokens → still REJECTED + not stored.
        for node in [&node_dup, &node_ws] {
            let err = backend
                .put_attestation(crate::federation::SignedAttestation {
                    attestation: pg_delegates_to(
                        &owner,
                        node,
                        serde_json::json!([ds::AGENCY_ACT_ON_BEHALF]),
                        false,
                    ),
                })
                .await
                .unwrap_err();
            assert!(
                matches!(err, crate::federation::Error::NodeAgencyForbidden { .. }),
                "{node}: dup/whitespace node token must still hit the gate, got {err:?}"
            );
            assert!(backend
                .list_attestations_for(node)
                .await
                .unwrap()
                .is_empty());
        }
        // Genuine node,agent hybrid → ADMITTED.
        let att = pg_delegates_to(
            &owner,
            &hybrid,
            serde_json::json!([ds::AGENCY_ACT_ON_BEHALF]),
            false,
        );
        let id = att.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .expect("a node,agent hybrid legitimately carries agency");
        let on_hybrid = backend.list_attestations_for(&hybrid).await.unwrap();
        assert_eq!(on_hybrid.len(), 1);
        assert_eq!(on_hybrid[0].attestation_id, id);
    }

    /// v9.0.0 (CC 3.2 / CC 3.4.7.1) — steward-binding precondition for
    /// non-infrastructure community membership, PG backend (3-backend
    /// parity with memory + sqlite). Covers: UNSTEWARDED node → REJECTED + not
    /// stored, UNSTEWARDED agent → REJECTED, STEWARD-BOUND node (infra delegation)
    /// → ADMITTED, STEWARD-BOUND agent → ADMITTED, `infrastructure` carve-out
    /// admits an unstewarded node, pure-user member not over-rejected. Each
    /// community uses a run-scoped uuid-suffixed key id and asserts only on
    /// its own row.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_community_steward_binding_matrix() {
        use crate::federation::types::delegation_scope as ds;
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let owner = format!("ob-owner-{suffix}");
        let node = format!("ob-node-{suffix}");
        let agent = format!("ob-agent-{suffix}");
        let node_wd = format!("ob-node-wd-{suffix}");
        let node_exp = format!("ob-node-exp-{suffix}");
        let node_unstewarded = format!("ob-node-unstewarded-{suffix}");
        for (kid, ity) in [
            (&owner, crate::federation::types::identity_type::USER),
            (&node, crate::federation::types::identity_type::NODE),
            (&agent, crate::federation::types::identity_type::AGENT),
            (&node_wd, crate::federation::types::identity_type::NODE),
            (&node_exp, crate::federation::types::identity_type::NODE),
            (
                &node_unstewarded,
                crate::federation::types::identity_type::NODE,
            ),
        ] {
            let mut k = fix_section_i_key(kid, "x", now, true);
            k.identity_type = ity.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }

        // Build a community keyed by a fresh run-scoped id with `members`
        // + optional cohort_subkind.
        let put_comm = |cid: &str, members: Vec<&str>, subkind: Option<&str>| {
            let policy = subkind.map(|sk| serde_json::json!({ "cohort_subkind": sk }));
            let members = members
                .into_iter()
                .map(|k| crate::federation::CommunityMember {
                    key_id: k.to_owned(),
                    joined_at: now,
                    role: None,
                })
                .collect();
            crate::federation::tier_ingest::test_support::sign_community(
                cid,
                crate::federation::Community {
                    community_key_id: cid.to_owned(),
                    community_name: "ob-test".into(),
                    members,
                    founded_at: now,
                    consensus_protocol: crate::federation::types::consensus_protocol::FOUNDER_ONLY
                        .into(),
                    policy_blob: policy,
                    persist_row_hash: String::new(),
                },
            )
        };
        // Seed every community key up front.
        let comm_unstewarded_node = format!("ob-c1-{suffix}");
        let comm_unstewarded_agent = format!("ob-c2-{suffix}");
        let comm_node_ok = format!("ob-c3-{suffix}");
        let comm_agent_ok = format!("ob-c4-{suffix}");
        let comm_infra = format!("ob-cinfra-{suffix}");
        let comm_fakeinfra = format!("ob-cfakeinfra-{suffix}");
        let comm_user = format!("ob-cuser-{suffix}");
        let comm_wd_live = format!("ob-cwdlive-{suffix}");
        let comm_wd_dead = format!("ob-cwddead-{suffix}");
        let comm_exp = format!("ob-cexp-{suffix}");
        for cid in [
            &comm_unstewarded_node,
            &comm_unstewarded_agent,
            &comm_node_ok,
            &comm_agent_ok,
            &comm_infra,
            &comm_fakeinfra,
            &comm_user,
            &comm_wd_live,
            &comm_wd_dead,
            &comm_exp,
        ] {
            let mut record = fix_section_i_key(cid, "c", now, true);
            // SecReview F2: the infra carve-out is honored only when the
            // community's own key is the `substrate_persist` governance
            // authority. `comm_infra` is the AUTHORIZED case (stamp it);
            // `comm_fakeinfra` is the unauthorized self-labeled case (plain).
            if cid == &comm_infra {
                record.identity_type =
                    crate::federation::types::identity_type::SUBSTRATE_PERSIST.into();
            }
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record })
                .await
                .unwrap();
        }

        // UNSTEWARDED node → REJECTED + not stored.
        let err = backend
            .put_community(put_comm(&comm_unstewarded_node, vec![&node], None))
            .await
            .unwrap_err();
        match err {
            crate::federation::Error::UnstewardedCommunityMember {
                ref community_key_id,
                ref member_key_id,
                member_role,
            } => {
                assert_eq!(community_key_id, &comm_unstewarded_node);
                assert_eq!(member_key_id, &node);
                assert_eq!(member_role, crate::federation::types::identity_type::NODE);
            }
            other => panic!("expected UnstewardedCommunityMember, got {other:?}"),
        }
        assert_eq!(err.kind(), "federation_unstewarded_community_member");
        assert!(backend
            .lookup_community(&comm_unstewarded_node)
            .await
            .unwrap()
            .is_none());

        // UNSTEWARDED agent → REJECTED (role reported as agent).
        let err = backend
            .put_community(put_comm(&comm_unstewarded_agent, vec![&agent], None))
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::Error::UnstewardedCommunityMember { member_role, .. }
                if member_role == crate::federation::types::identity_type::AGENT
        ));
        assert!(backend
            .lookup_community(&comm_unstewarded_agent)
            .await
            .unwrap()
            .is_none());

        // STEWARD-BOUND node (live delegates_to(user → node, infra:*)) → ADMITTED.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_delegates_to(
                    &owner,
                    &node,
                    serde_json::json!([ds::INFRA_SERVE, ds::INFRA_NETWORK_PRESENCE]),
                    false,
                ),
            })
            .await
            .unwrap();
        backend
            .put_community(put_comm(&comm_node_ok, vec![&node], None))
            .await
            .expect("steward-bound node admitted");
        assert!(backend
            .lookup_community(&comm_node_ok)
            .await
            .unwrap()
            .is_some());

        // STEWARD-BOUND agent (live delegates_to(user → agent)) → ADMITTED.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_delegates_to(&owner, &agent, serde_json::json!(["share"]), false),
            })
            .await
            .unwrap();
        backend
            .put_community(put_comm(&comm_agent_ok, vec![&agent], None))
            .await
            .expect("steward-bound agent admitted");
        assert!(backend
            .lookup_community(&comm_agent_ok)
            .await
            .unwrap()
            .is_some());

        // `infrastructure` carve-out → unstewarded node admitted (AUTHORIZED:
        // comm_infra's key is substrate_persist).
        backend
            .put_community(put_comm(&comm_infra, vec![&node], Some("infrastructure")))
            .await
            .expect("infrastructure community exempt");
        assert!(backend
            .lookup_community(&comm_infra)
            .await
            .unwrap()
            .is_some());

        // SecReview F2: an `infrastructure`-LABELED community whose own key
        // is NOT substrate_persist does NOT get the carve-out — steward-binding
        // is STILL enforced, so the UNSTEWARDED node is REJECTED + not stored.
        let err = backend
            .put_community(put_comm(
                &comm_fakeinfra,
                vec![&node_unstewarded],
                Some("infrastructure"),
            ))
            .await
            .unwrap_err();
        match err {
            crate::federation::Error::UnstewardedCommunityMember {
                ref member_key_id,
                member_role,
                ..
            } => {
                assert_eq!(member_key_id, &node_unstewarded);
                assert_eq!(member_role, crate::federation::types::identity_type::NODE);
            }
            other => panic!("expected UnstewardedCommunityMember, got {other:?}"),
        }
        assert!(backend
            .lookup_community(&comm_fakeinfra)
            .await
            .unwrap()
            .is_none());

        // SecReview F3: a WITHDRAWN delegation no longer confers
        // steward-binding. owner delegates infra:* → node_wd (admitted while
        // live); owner then withdraws the edge → a fresh community with
        // node_wd is REJECTED.
        let d_wd = pg_delegates_to(
            &owner,
            &node_wd,
            serde_json::json!([ds::INFRA_SERVE, ds::INFRA_NETWORK_PRESENCE]),
            false,
        );
        let d_wd_id = d_wd.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: d_wd })
            .await
            .unwrap();
        backend
            .put_community(put_comm(&comm_wd_live, vec![&node_wd], None))
            .await
            .expect("steward-bound (live) node admitted");
        // owner withdraws the edge (issuer-against-recipient: attested = node_wd).
        let mut w = pg_scores_attestation(&owner, &node_wd, &owner, "x");
        w.attestation_type = crate::federation::types::attestation_type::WITHDRAWS.into();
        crate::federation::tier_ingest::test_support::reseal(&mut w);
        w.attestation_envelope = serde_json::json!({"references_attestation_id": d_wd_id});
        crate::federation::tier_ingest::test_support::reseal(&mut w);
        pg_resign(&mut w);
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: w })
            .await
            .expect("owner withdraws own delegation edge");
        let err = backend
            .put_community(put_comm(&comm_wd_dead, vec![&node_wd], None))
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::Error::UnstewardedCommunityMember { .. }
        ));
        assert!(backend
            .lookup_community(&comm_wd_dead)
            .await
            .unwrap()
            .is_none());

        // SecReview F3: an EXPIRED delegation does NOT confer steward-binding.
        let mut d_exp = pg_delegates_to(
            &owner,
            &node_exp,
            serde_json::json!([ds::INFRA_SERVE, ds::INFRA_NETWORK_PRESENCE]),
            false,
        );
        d_exp.expires_at = Some("2020-01-01T00:00:00Z".parse().unwrap());
        // v31.0.0 (CIRISPersist#598) — `expires_at` is bound in BOTH directions
        // now (envelope absent ⇔ column None), so setting the column is a
        // re-sign trigger. That is this leg's own premise from the other side:
        // the expiry is what kills the delegation's liveness, and an expiry a
        // writer could set ALONE would be an unsigned mute button.
        crate::federation::tier_ingest::test_support::reseal(&mut d_exp);
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: d_exp })
            .await
            .unwrap();
        let err = backend
            .put_community(put_comm(&comm_exp, vec![&node_exp], None))
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::Error::UnstewardedCommunityMember { .. }
        ));
        assert!(backend.lookup_community(&comm_exp).await.unwrap().is_none());

        // Pure-user member → not over-rejected.
        backend
            .put_community(put_comm(&comm_user, vec![&owner], None))
            .await
            .expect("user member admitted");
        assert!(backend
            .lookup_community(&comm_user)
            .await
            .unwrap()
            .is_some());
    }

    /// v8.7.1 (CIRISPersist#233, CEG §11.10) — FULL §11.10 moderation
    /// enforcement on the PG report→`scores` path (3-backend parity with
    /// memory + sqlite). Exercises (a) as-self subject, (b1) subject-
    /// delegated chain, (b2) named-moderator (community founder, owner-
    /// bound), (c) no authority, (c2) NOTHING → REJECT (bypass guard),
    /// (d) scope isolation. Run-scoped uuid-suffixed key ids.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_moderation_scores_full_matrix() {
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let now = chrono::Utc::now();
        let suffix = uuid_like();
        let subject = format!("subject-{suffix}");
        let delegate = format!("delegate-{suffix}");
        let rando = format!("rando-{suffix}");
        let founder = format!("founder-{suffix}");
        let comm = format!("comm-{suffix}");
        // subject + founder are user-role (steward-bound); the rest agents.
        for kid in [&subject, &founder, &comm] {
            let mut k = fix_section_i_key(kid, "u", now, true);
            k.identity_type = crate::federation::types::identity_type::USER.into();
            backend
                .put_public_key(crate::federation::SignedKeyRecord { record: k })
                .await
                .unwrap();
        }
        for kid in [&delegate, &rando] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: fix_section_i_key(kid, "a", now, true),
                })
                .await
                .unwrap();
        }
        backend
            .put_community(
                crate::federation::tier_ingest::test_support::sign_community(
                    &comm,
                    crate::federation::Community {
                        community_key_id: comm.clone(),
                        community_name: "tc".into(),
                        members: vec![crate::federation::CommunityMember {
                            key_id: founder.clone(),
                            joined_at: now,
                            role: Some("founder".into()),
                        }],
                        founded_at: now,
                        consensus_protocol:
                            crate::federation::types::consensus_protocol::FOUNDER_ONLY.into(),
                        policy_blob: None,
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();

        let dim = "reconsideration:case42:v1";
        // Build a moderation/review report by `signer` over `subjects` +
        // optional `community_id`.
        let report = |signer: &str, subjects: &[&str], community: Option<&str>| {
            let mut a = pg_scores_attestation(signer, signer, signer, dim);
            a.subject_key_ids = subjects.iter().map(|s| (*s).to_owned()).collect();
            crate::federation::tier_ingest::test_support::reseal(&mut a);
            if let Some(c) = community {
                a.attestation_envelope["community_id"] = serde_json::Value::String(c.to_owned());
                pg_resign(&mut a); // envelope changed → re-sign (CC 5.3.2.4.3.1)
            }
            a
        };

        // (a) v21.11.0 (CIRISPersist#517, CC 4.5.5) — as-self subject → REJECT.
        // Reconsideration REVIEW authority is `is_named_moderator` ONLY; a
        // subject naming ITSELF confers none (`subject` is not a moderator of
        // `comm`). Was the spoof (admitted); now refused.
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&subject, &[&subject], None),
            })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_delegated_scope_unauthorized");

        // (b1) subject-delegated chain → REJECT. The subject never held review
        // authority, so it cannot delegate it (the delegation row admits; the
        // delegate's reconsideration does not) (#517).
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_delegates_to(
                    &subject,
                    &delegate,
                    serde_json::json!(["review"]),
                    false,
                ),
            })
            .await
            .unwrap();
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&delegate, &[&subject], None),
            })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_delegated_scope_unauthorized");

        // (b1') founder-delegated chain (founder → fdelegate, review over
        // comm) → ADMIT. The LEGITIMATE delegated-moderator path: authority
        // roots at a real named moderator and flows down the review-scoped
        // delegation — #517 cut only the subject-self seed, not genuine
        // moderator delegation.
        let fdelegate = format!("fdelegate-{suffix}");
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(&fdelegate, "a", now, true),
            })
            .await
            .unwrap();
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_delegates_to(
                    &founder,
                    &fdelegate,
                    serde_json::json!(["review"]),
                    false,
                ),
            })
            .await
            .unwrap();
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&fdelegate, &[], Some(&comm)),
            })
            .await
            .expect("(b1') founder-delegated review admitted");

        // (b2) named-moderator (community founder, steward-bound) → ADMIT.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&founder, &[], Some(&comm)),
            })
            .await
            .expect("(b2) named-moderator admitted");

        // (c) no authority → REJECT.
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&rando, &[&subject], None),
            })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_delegated_scope_unauthorized");

        // (c2) NOTHING → REJECT (bypass-closed regression guard).
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&rando, &[], None),
            })
            .await
            .unwrap_err();
        assert_eq!(
            err.kind(),
            "federation_delegated_scope_unauthorized",
            "(c2) absent principal must REJECT, not admit"
        );

        // (d) scope isolation — consent_revocation-only chain ⇏ review.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: pg_delegates_to(
                    &subject,
                    &rando,
                    serde_json::json!(["consent_revocation"]),
                    false,
                ),
            })
            .await
            .unwrap();
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: report(&rando, &[&subject], None),
            })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_delegated_scope_unauthorized");
    }

    // ── v17.4.0 scores read surface: postgres runtime parity (the pg SQL
    //    JOIN + `= ANY($n)` + `->>'references_attestation_id'` anti-join
    //    differ from sqlite, so they need a live-pg run — mirror of the
    //    sqlite `list_scores`/`resolve_scores` tests). ──

    /// Build + sign + put a federation `scores` row with an explicit
    /// attestation_id, attester, subject, dimension, score, and asserted_at
    /// offset (minutes). Composers (supersedes/withdraws) reference a prior
    /// id via the envelope. Returns the (uuid) attestation_id.
    #[cfg(test)]
    async fn pg_put_score(
        be: &PostgresBackend,
        attester: &str,
        subject: &str,
        dimension: &str,
        score: f64,
        base: chrono::DateTime<chrono::Utc>,
        mins: i64,
    ) -> String {
        use crate::federation::FederationDirectory;
        // Idempotent: seed the (self-attesting) key so the FK holds.
        let _ = be
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(attester, "a", chrono::Utc::now(), true),
            })
            .await;
        let id = uuid::Uuid::new_v4().to_string();
        let mut row = pg_scores_attestation(attester, attester, attester, dimension);
        row.attestation_id = id.clone();
        crate::federation::tier_ingest::test_support::reseal(&mut row);
        // `weight` is the confidence column the fold uses (score × confidence);
        // full confidence, the varying signal is `score` in the envelope.
        row.weight = Some(1.0);
        crate::federation::tier_ingest::test_support::reseal(&mut row);
        row.asserted_at = base + chrono::Duration::minutes(mins);
        row.subject_key_ids = vec![subject.to_string()];
        crate::federation::tier_ingest::test_support::reseal(&mut row);
        row.attestation_envelope = serde_json::json!({
            "dimension": dimension, "score": score, "confidence": 1.0,
        });
        pg_resign(&mut row);
        be.put_attestation(crate::federation::SignedAttestation { attestation: row })
            .await
            .expect("pg put_score");
        id
    }

    #[cfg(test)]
    async fn pg_put_composer(
        be: &PostgresBackend,
        attester: &str,
        atype: &str,
        references: &str,
        base: chrono::DateTime<chrono::Utc>,
        mins: i64,
    ) {
        use crate::federation::FederationDirectory;
        let _ = be
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_section_i_key(attester, "a", chrono::Utc::now(), true),
            })
            .await;
        let mut row = pg_scores_attestation(attester, attester, attester, "x");
        row.attestation_id = uuid::Uuid::new_v4().to_string();
        row.attestation_type = atype.to_string();
        row.weight = None;
        crate::federation::tier_ingest::test_support::reseal(&mut row);
        row.asserted_at = base + chrono::Duration::minutes(mins);
        row.attestation_envelope = serde_json::json!({ "references_attestation_id": references });
        crate::federation::tier_ingest::test_support::reseal(&mut row);
        pg_resign(&mut row);
        be.put_attestation(crate::federation::SignedAttestation { attestation: row })
            .await
            .expect("pg put_composer");
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_list_scores_subject_dimension_seek_newest_first() {
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let be = PostgresBackend::connect(&dsn).await.expect("connect");
        be.run_migrations().await.expect("migrations");
        let base = chrono::Utc::now() - chrono::Duration::hours(2);
        let subj = format!("subj-{}", uuid_like());
        let dim = "trust:demo:v1";
        let s1 = pg_put_score(&be, "k1", &subj, dim, 0.5, base, 10).await;
        let s2 = pg_put_score(&be, "k2", &subj, dim, 0.6, base, 20).await;
        let _s3 = pg_put_score(&be, "k3", &subj, "other:demo:v1", 0.6, base, 30).await;
        // exact-dimension seek, newest-first
        let f = crate::read::AttestationFilter {
            subject_key_id: Some(subj.clone()),
            dimension_exact: Some(dim.into()),
            ..Default::default()
        };
        let page = be.list_scores("", f, None, 100).await.unwrap();
        let ids: Vec<_> = page
            .items
            .iter()
            .map(|a| a.attestation_id.clone())
            .collect();
        assert_eq!(ids, vec![s2.clone(), s1.clone()], "newest-first exact-dim");
        // attester_filter Explicit set membership (`= ANY($n)`)
        let f = crate::read::AttestationFilter {
            subject_key_id: Some(subj.clone()),
            dimension_exact: Some(dim.into()),
            attester_filter: Some(crate::read::AttesterSet::Explicit(vec!["k1".into()])),
            ..Default::default()
        };
        let page = be.list_scores("", f, None, 100).await.unwrap();
        assert_eq!(
            page.items
                .iter()
                .map(|a| a.attestation_id.clone())
                .collect::<Vec<_>>(),
            vec![s1],
            "attester_filter set membership"
        );
        let _ = s2;
    }

    /// v30.0.0 (CIRISPersist#596 item 2) — the POSTGRES twin of
    /// `list_attestations_honours_window_tier_and_attester_596`.
    ///
    /// Written because the pg wiring had the **same misplacement bug** the
    /// sqlite one did — the shared emitter was called inside the
    /// `subject_key_id` block, so the axes only bound when an unrelated filter
    /// field happened to be set. It compiled, and it would have passed any test
    /// that set a subject. Parity is not inherited from the sqlite test; it is
    /// measured here.
    /// v30.2.0 (CIRISPersist#17) — **no test reaches postgres except through
    /// the per-test provisioner.**
    ///
    /// GateSpec: family `procedural` (the wrong it prevents is `empirical` — a
    /// suite green by scheduling luck) · headwaters: every `src/**.rs`,
    /// searched for a direct read of `CIRIS_PERSIST_TEST_PG_URL` · references:
    /// CIRISPersist#17, `src/test_pg.rs` · dye test:
    /// `a_direct_env_read_is_caught` below · depth: TEXTUAL — it cannot see a
    /// test handed a DSN as an argument, nor one reading the var through an
    /// alias · owner: persist.
    ///
    /// # What this replaced, and why the old gate was worse than none
    ///
    /// This slot held `every_postgres_test_takes_the_serial_lock`, enforcing
    /// `#[serial_test::serial(postgres)]` on every postgres test. That
    /// attribute **does nothing under nextest** — nextest runs each test in its
    /// own PROCESS and `serial_test`'s lock is process-local. The gate enforced
    /// a decoration while reporting protection: the check-that-cannot-fail
    /// class in a costume, and it passed cleanly the whole time it was useless.
    ///
    /// The invariant that actually holds isolation is this one. A test reading
    /// the env var directly gets the SHARED database and silently rejoins the
    /// races that cost this project a `--test-threads=1` config and a measured
    /// 2.8x wall-time penalty.
    #[test]
    fn every_postgres_test_goes_through_the_provisioner() {
        let (scanned, bad) = super::postgres_serial_scan::scan_direct_env_reads();
        assert!(
            scanned > 100,
            "scanned only {scanned} source files — the scan is not reaching the tree"
        );
        assert!(
            bad.is_empty(),
            "{} direct read(s) of CIRIS_PERSIST_TEST_PG_URL outside src/test_pg.rs:\n{}\n\n\
             Each gets the SHARED database and rejoins the cross-test races per-test \
             isolation exists to end. Use `crate::test_pg::dsn()`.",
            bad.len(),
            bad.join("\n")
        );
    }

    /// The **dye test**: a planted direct read is caught, and a correct call is
    /// not. The second half matters as much as the first — the predecessor gate
    /// produced two false positives on clean code before this pairing existed.
    #[test]
    fn a_direct_env_read_is_caught() {
        assert!(
            super::postgres_serial_scan::is_direct_env_read(
                "let dsn = std::env::var(\"CIRIS_PERSIST_TEST_PG_URL\").unwrap();" // SCAN-EXEMPT-SELF-MATCH
            ),
            "the predicate missed a direct env read — the gate cannot fire"
        );
        assert!(
            !super::postgres_serial_scan::is_direct_env_read("let dsn = crate::test_pg::dsn();"),
            "the predicate flagged a correct provisioner call — it would fail on clean code"
        );
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_list_attestations_honours_window_tier_and_attester_596() {
        use crate::ceg::ReadEngine;
        use crate::read::{AttestationFilter, AttesterSet, Tier};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let be = PostgresBackend::connect(&dsn).await.expect("connect");
        be.run_migrations().await.expect("migrations");

        let base = chrono::Utc::now() - chrono::Duration::hours(5);
        let subj = format!("subj-{}", uuid_like());
        let dim = "trust:filteraxes:v1";
        let ka = format!("ka-{}", uuid_like());
        let kb = format!("kb-{}", uuid_like());
        // Invocation-unique attesters + dimension, so this is safe against a
        // shared database and does not assert a GLOBAL row count.
        let a_old = pg_put_score(&be, &ka, &subj, dim, 0.9, base, 0).await;
        let b_mid = pg_put_score(&be, &kb, &subj, dim, 0.5, base, 120).await;
        let a_new = pg_put_score(&be, &ka, &subj, dim, 0.7, base, 240).await;

        let q = |f: AttestationFilter| {
            let be = &be;
            async move {
                let mut ids: Vec<String> = be
                    .list_attestations(f, None, 100, crate::scope::CallerScope::Unauthenticated)
                    .await
                    .unwrap()
                    .items
                    .into_iter()
                    .map(|a| a.attestation_id)
                    .collect();
                ids.sort();
                ids
            }
        };
        let only_ours = |mut v: Vec<String>| {
            v.retain(|id| id == &a_old || id == &b_mid || id == &a_new);
            v
        };

        let all = only_ours(
            q(AttestationFilter {
                dimension_exact: Some(dim.to_owned()),
                ..Default::default()
            })
            .await,
        );
        assert_eq!(all.len(), 3, "baseline: all three seeded rows are visible");

        // window — half-open, excludes the row at +240m
        let windowed = only_ours(
            q(AttestationFilter {
                dimension_exact: Some(dim.to_owned()),
                window: Some((base, base + chrono::Duration::minutes(180))),
                ..Default::default()
            })
            .await,
        );
        let mut want = vec![a_old.clone(), b_mid.clone()];
        want.sort();
        assert_eq!(windowed, want, "`window` must BIND on postgres too");

        // attester_filter
        let by_ka = only_ours(
            q(AttestationFilter {
                dimension_exact: Some(dim.to_owned()),
                attester_filter: Some(AttesterSet::Explicit(vec![ka.clone()])),
                ..Default::default()
            })
            .await,
        );
        let mut want_ka = vec![a_old.clone(), a_new.clone()];
        want_ka.sort();
        assert_eq!(
            by_ka, want_ka,
            "`attester_filter` must restrict on postgres"
        );

        assert_eq!(
            only_ours(
                q(AttestationFilter {
                    dimension_exact: Some(dim.to_owned()),
                    attester_filter: Some(AttesterSet::Explicit(vec![])),
                    ..Default::default()
                })
                .await
            ),
            Vec::<String>::new(),
            "an explicit EMPTY attester set selects nothing on postgres"
        );

        // tier — all three are federation rows
        assert_eq!(
            only_ours(
                q(AttestationFilter {
                    dimension_exact: Some(dim.to_owned()),
                    tier: Some(Tier::Local),
                    ..Default::default()
                })
                .await
            ),
            Vec::<String>::new(),
            "`tier: Local` must exclude federation rows"
        );
        assert_eq!(
            only_ours(
                q(AttestationFilter {
                    dimension_exact: Some(dim.to_owned()),
                    tier: Some(Tier::Federation),
                    ..Default::default()
                })
                .await
            )
            .len(),
            3,
            "`tier: Federation` keeps them"
        );
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_resolve_scores_latest_wins_withdraw_and_band() {
        use crate::federation::FederationDirectory;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let be = PostgresBackend::connect(&dsn).await.expect("connect");
        be.run_migrations().await.expect("migrations");
        let base = chrono::Utc::now() - chrono::Duration::hours(2);
        let subj = format!("subj-{}", uuid_like());
        let dim = "trust:demo:v1";
        // k1: 0.9 superseded by 0.4 head; k2: 0.5; k3: withdrawn.
        let k1old = pg_put_score(&be, "k1", &subj, dim, 0.9, base, 10).await;
        pg_put_score(&be, "k1", &subj, dim, 0.4, base, 20).await;
        pg_put_composer(&be, "k1", "supersedes", &k1old, base, 20).await;
        pg_put_score(&be, "k2", &subj, dim, 0.5, base, 15).await;
        let k3 = pg_put_score(&be, "k3", &subj, dim, 0.5, base, 15).await;
        pg_put_composer(
            &be,
            "k3",
            crate::federation::types::attestation_type::WITHDRAWS,
            &k3,
            base,
            25,
        )
        .await;
        let f = crate::read::AttestationFilter {
            subject_key_id: Some(subj),
            dimension_exact: Some(dim.into()),
            ..Default::default()
        };
        let v = be
            .resolve_scores("", f, "cc-4.4.2-signed-mean".into(), true)
            .await
            .unwrap();
        // live heads k1new(0.4), k2(0.5); k1old superseded, k3 withdrawn.
        assert_eq!(v.contributor_count, 2, "distinct live attesters");
        assert_eq!(
            v.band,
            crate::read::ConfidenceBand::Supported,
            "mean(0.4,0.5)=0.45"
        );
        assert_eq!(v.open_contradictions, 0);
        assert!(v.trace.is_some() && v.age_of_head.is_some());
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_put_attestation_rejects_accord_dimension_from_steward() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;
        let steward = format!("pg-steward-§102-{}", uuid_like());
        let agent_k = format!("pg-agent-§102-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &steward,
                    "registry",
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &agent_k,
                    "primitive-a",
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await
            .unwrap();
        let att = pg_scores_attestation(&steward, &agent_k, &steward, "accord:human_dignity:v1");
        let err = backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .unwrap_err();
        assert!(matches!(
            err,
            crate::federation::Error::AccordDimensionRequiresAccordHolder { .. }
        ));
    }

    /// v6.4.0 (CIRISPersist#146 Ask 2, CEG §3.2.3 / §8.1.11.2) — live-PG
    /// coverage for the broadened `withdraws` admission gate. Proves
    /// parity with the sqlite/memory suites on real Postgres: rule-2
    /// subject self-revocation, §8.1.11.2 multi-subject independent
    /// authority (any single subject suffices, no quorum), and the
    /// unrelated-issuer refusal. Self-isolating: all key_ids carry a
    /// `uuid_like()` suffix and attestation ids are `Uuid::new_v4()`, so
    /// the test does not collide on a reused local PG. Runtime
    /// verification pending (lead's docker PG, `CIRIS_PERSIST_TEST_PG_URL`).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_withdraws_admission_multisubject_rule2_and_refusal() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let prod = format!("pg-w-prod-{}", uuid_like());
        let s1 = format!("pg-w-s1-{}", uuid_like());
        let s2 = format!("pg-w-s2-{}", uuid_like());
        let rando = format!("pg-w-rando-{}", uuid_like());
        for k in [&prod, &s1, &s2, &rando] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(
                        k,
                        "primitive-a",
                        crate::federation::types::identity_type::AGENT,
                    ),
                })
                .await
                .unwrap();
        }

        // Target T with two independent subjects.
        let mut t = pg_scores_attestation(&prod, &prod, &prod, "identity_binding:v1");
        t.subject_key_ids = vec![s1.clone(), s2.clone()];
        crate::federation::tier_ingest::test_support::reseal(&mut t);
        let tid = t.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: t })
            .await
            .unwrap();

        let mk_withdraws = |issuer: &str| {
            let mut w = pg_scores_attestation(issuer, issuer, issuer, "identity_binding:v1");
            w.attestation_type = crate::federation::types::attestation_type::WITHDRAWS.into();
            crate::federation::tier_ingest::test_support::reseal(&mut w);
            w.attestation_envelope = serde_json::json!({
                "references_attestation_id": tid,
                "withdrawal_reason": "test",
            });
            pg_resign(&mut w); // envelope changed → re-sign (CC 5.3.2.4.3.1)
            w
        };

        // §8.1.11.2 — only s2 revokes; independent authority admits it
        // under rule 2 (no quorum).
        let w = mk_withdraws(&s2);
        let wid = w.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: w })
            .await
            .unwrap();
        let got = backend.get_attestation(&wid).await.unwrap().unwrap();
        assert_eq!(
            got.withdraws_admission_rule,
            Some(2),
            "a single subject of a multi-subject T admits under rule 2"
        );

        // Unrelated key cannot withdraw T.
        let bad = mk_withdraws(&rando);
        let bad_id = bad.attestation_id.clone();
        let err = backend
            .put_attestation(crate::federation::SignedAttestation { attestation: bad })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_withdraws_not_admitted");
        assert!(
            backend.get_attestation(&bad_id).await.unwrap().is_none(),
            "refused withdraws leaves no trace on PG"
        );
    }

    // ─── v6.7.0 Lane G (CEG 1.0-RC5) — consent clauses, PG parity ──────

    /// Clause 1 (#161 Ask 5, CEG §7.7) — a family-membership revocation on
    /// real Postgres emits the `family_membership_change` hard_case with
    /// `change_kind: "removed"` + the RC5 payload, and re-recording the
    /// same removal event is idempotent (ON CONFLICT DO NOTHING).
    /// Self-isolating: uuid-suffixed keys, filtered by the unique family.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_family_membership_revocation_emits_removed_hard_case() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::hard_case;
        use crate::federation::FederationDirectory;

        let fam = format!("pg-fam-{}", uuid_like());
        let member = format!("pg-carol-{}", uuid_like());
        for k in [&fam, &member] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(
                        k,
                        "primitive-a",
                        crate::federation::types::identity_type::AGENT,
                    ),
                })
                .await
                .unwrap();
        }
        backend
            .put_family(crate::federation::tier_ingest::test_support::sign_family(
                &fam,
                crate::federation::Family {
                    family_key_id: fam.clone(),
                    family_name: "PG Household".into(),
                    members: vec![crate::federation::types::FamilyMember {
                        key_id: member.clone(),
                        joined_at: chrono::Utc::now(),
                        role: None,
                    }],
                    founded_at: chrono::Utc::now(),
                    consensus_protocol: "founder_only".into(),
                    consensus_protocol_entrenched: false,
                    persist_row_hash: String::new(),
                },
            ))
            .await
            .unwrap();

        let effective = chrono::Utc.with_ymd_and_hms(2026, 6, 10, 12, 0, 0).unwrap();
        let rev = crate::federation::FamilyMembershipRevocation {
            family_key_id: fam.clone(),
            removed_identity_key_id: member.clone(),
            removed_at: chrono::Utc::now(),
            effective_at: effective,
            reason: None,
            witness_set: Vec::new(),
            persist_row_hash: String::new(),
        };
        backend
            .put_family_membership_revocation(
                crate::federation::tier_ingest::test_support::sign_family_membership_revocation(
                    &fam,
                    rev.clone(),
                ),
            )
            .await
            .unwrap();
        // Re-record the same removal event — idempotent on event_id.
        backend
            .record_hard_case(hard_case::membership_removed_event(
                hard_case::kind::FAMILY_MEMBERSHIP_CHANGE,
                &rev.family_key_id,
                &rev.removed_identity_key_id,
                rev.effective_at,
            ))
            .await
            .unwrap();

        let events = backend
            .list_hard_case_events(hard_case::HardCaseFilter {
                kind: Some(hard_case::kind::FAMILY_MEMBERSHIP_CHANGE.into()),
                since: None,
            })
            .await
            .unwrap();
        let mine: Vec<_> = events
            .into_iter()
            .filter(|e| e.target_key_id.as_deref() == Some(fam.as_str()))
            .collect();
        assert_eq!(
            mine.len(),
            1,
            "exactly one (idempotent) removal event on PG"
        );
        assert_eq!(
            mine[0].detail["change_kind"],
            hard_case::change_kind::REMOVED
        );
        assert_eq!(mine[0].detail["cohort_key_id"], fam);
        assert_eq!(mine[0].subject_key_id.as_deref(), Some(member.as_str()));
        assert_eq!(mine[0].detail["effective_at"], effective.to_rfc3339());
    }

    /// Clause 2 (#146 Ask 5, CEG §5.6.8.7) — consent_record admission on
    /// real Postgres: granted/federation admits; producer `expired` and
    /// revoked/local are rejected.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_consent_record_admission() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let subj = format!("pg-cr-subj-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &subj,
                    "primitive-a",
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await
            .unwrap();

        let mk = |stance: &str, tier: &str| {
            let mut a = pg_scores_attestation(&subj, &subj, &subj, "consent:partnership_grant:v1");
            a.attestation_envelope = serde_json::json!({
                "subject_kind": crate::federation::types::consent_record::SUBJECT_KIND,
                "subject_key_id": subj,
                "stance": stance,
                "asserted_at": "2026-06-01T00:00:00Z",
                "dimension": "consent:partnership_grant:v1",
                "score": 1.0,
                "confidence": 0.9,
            });
            pg_resign(&mut a); // envelope changed → re-sign (CC 5.3.2.4.3.1)
            a.tier = tier.to_string();
            if tier == crate::federation::types::attestation_tier::LOCAL {
                a.cohort_scope = crate::federation::types::cohort_scope::SELF.to_string();
                crate::federation::tier_ingest::test_support::reseal(&mut a);
            }
            a
        };
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: mk(
                    crate::federation::types::consent_record::stance::GRANTED,
                    crate::federation::types::attestation_tier::FEDERATION,
                ),
            })
            .await
            .expect("granted/federation consent_record admits on PG");
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: mk(
                    crate::federation::types::consent_record::stance::EXPIRED,
                    crate::federation::types::attestation_tier::FEDERATION,
                ),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("substrate-emitted only"))
        );
        // revoked / local (v12.6.0, §10.1.3 transit-not-rest): a crypto-VALID
        // one TRANSITS the local tier (accepted); a forged one is rejected.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: mk(
                    crate::federation::types::consent_record::stance::REVOKED,
                    crate::federation::types::attestation_tier::LOCAL,
                ),
            })
            .await
            .expect("crypto-valid revoked consent_record transits the local tier on PG");
        let mut forged = mk(
            crate::federation::types::consent_record::stance::REVOKED,
            crate::federation::types::attestation_tier::LOCAL,
        );
        forged.scrub_signature_classical = "AAAA".into(); // not a valid sig
        let err = backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: forged,
            })
            .await
            .unwrap_err();
        assert!(
            matches!(
                err,
                crate::federation::Error::FederationTierUnverified { .. }
            ),
            "forged revoked/local consent_record rejected at admission, got {err:?}"
        );
    }

    /// Clause 3 (#146 Ask 6, CEG §5.6.8.14) — canonical_binding widens the
    /// `withdraws` gate on real Postgres: a `withdraws` from K against a T
    /// naming canonical hash H is refused pre-binding, admitted as rule 2
    /// after K's `identity:canonical_binding:{H}` self-assertion.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_canonical_binding_widens_withdraws_rule2() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let k = format!("pg-cb-K-{}", uuid_like());
        let prod = format!("pg-cb-prod-{}", uuid_like());
        let canon = format!("canonical:sha256:{}-{}", "c".repeat(32), uuid_like());
        for key in [&k, &prod] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(
                        key,
                        "primitive-a",
                        crate::federation::types::identity_type::AGENT,
                    ),
                })
                .await
                .unwrap();
        }
        // Target T names the canonical hash H in subject_key_ids (no FK).
        let mut t = pg_scores_attestation(&prod, &prod, &prod, "identity_binding:v1");
        t.subject_key_ids = vec![canon.clone()];
        crate::federation::tier_ingest::test_support::reseal(&mut t);
        let tid = t.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: t })
            .await
            .unwrap();

        let mk_withdraws = || {
            let mut w = pg_scores_attestation(&k, &k, &k, "identity_binding:v1");
            w.attestation_type = crate::federation::types::attestation_type::WITHDRAWS.into();
            crate::federation::tier_ingest::test_support::reseal(&mut w);
            w.attestation_envelope = serde_json::json!({
                "references_attestation_id": tid,
                "withdrawal_reason": "test",
            });
            pg_resign(&mut w); // envelope changed → re-sign (CC 5.3.2.4.3.1)
            w
        };

        // Pre-binding: refused.
        let bad = mk_withdraws();
        let bad_id = bad.attestation_id.clone();
        let err = backend
            .put_attestation(crate::federation::SignedAttestation { attestation: bad })
            .await
            .unwrap_err();
        assert_eq!(err.kind(), "federation_withdraws_not_admitted");
        assert!(backend.get_attestation(&bad_id).await.unwrap().is_none());

        // K self-asserts the canonical binding K → H.
        let mut binding = pg_scores_attestation(&k, &k, &k, "identity_binding:v1");
        binding.attestation_envelope = serde_json::json!({
            "dimension": format!("identity:canonical_binding:{canon}"),
            "score": 1.0,
            "confidence": 1.0,
            "witness_relation": "self",
        });
        pg_resign(&mut binding); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: binding,
            })
            .await
            .expect("canonical_binding self-assertion admits on PG");

        // Post-binding: admitted as rule 2.
        let w = mk_withdraws();
        let wid = w.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: w })
            .await
            .expect("post-binding withdraws admits on PG");
        let got = backend.get_attestation(&wid).await.unwrap().unwrap();
        assert_eq!(got.withdraws_admission_rule, Some(2));
    }

    /// v4.6.0 (CIRISPersist#171/#176) — live-PG coverage for the
    /// deferred-PQC completion path (`attach_attestation_pqc_signature` /
    /// `attach_revocation_pqc_signature`), the sweep `Engine.run_pqc_sweep`
    /// drives via PyO3. Previously tested ONLY on the in-memory backend,
    /// whose string-keyed map never exercised the `attestation_id`/`uuid`
    /// driver serialization — so a `&str`-bound `$N::uuid` param (which
    /// panics with "error serializing parameter 0" on real Postgres) went
    /// undetected. This test closes that gap for both attach paths.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_attach_pqc_for_attestation_and_revocation() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;

        let steward = format!("pg-attach-steward-{}", uuid_like());
        let target = format!("pg-attach-target-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &steward,
                    "registry",
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &target,
                    "primitive-a",
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await
            .unwrap();

        // Federation-tier, PQC-pending attestation (real UUID id).
        let att = pg_scores_attestation(&steward, &target, &steward, "identity_binding:v1");
        let att_id = att.attestation_id.clone();
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .unwrap();
        backend
            .attach_attestation_pqc_signature(&att_id, "att-pqc-sig")
            .await
            .expect("attach attestation PQC sig must serialize the uuid param");
        let after = backend
            .get_attestation(&att_id)
            .await
            .unwrap()
            .expect("row");
        assert!(
            after.is_pqc_complete(),
            "attestation PQC-complete after attach"
        );

        // Same for a federation revocation (real UUID id; valid 64-hex
        // original_content_hash — the revocation path hex-decodes it).
        let now = chrono::Utc::now();
        let rev_id = uuid::Uuid::new_v4().to_string();
        // v31.0.0 (#659) — sealed through the one shared producer.
        let rev = crate::federation::tier_ingest::test_support::seal_revocation(
            crate::federation::Revocation {
                revocation_id: rev_id.clone(),
                revoked_key_id: target.clone(),
                revoking_key_id: steward.clone(),
                reason: Some("test".into()),
                revoked_at: now,
                effective_at: now,
                revocation_envelope: serde_json::json!({"id": rev_id}),
                original_content_hash: String::new(),
                scrub_signature_classical: String::new(),
                scrub_signature_pqc: None,
                scrub_key_id: steward.clone(),
                scrub_timestamp: now,
                pqc_completed_at: None,
                observed_region: crate::federation::verify_coord::region::US.into(),
                revoked_after: None,
                persist_row_hash: String::new(),
            },
        );
        grant_slash(&backend, &steward).await;
        backend
            .put_revocation(crate::federation::SignedRevocation { revocation: rev })
            .await
            .unwrap();
        backend
            .attach_revocation_pqc_signature(&rev_id, "rev-pqc-sig")
            .await
            .expect("attach revocation PQC sig must serialize the uuid param");
        let revs = backend.revocations_for(&target).await.unwrap();
        assert!(
            revs.iter()
                .any(|r| r.revocation_id == rev_id && r.is_pqc_complete()),
            "revocation PQC-complete after attach"
        );
    }

