    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_put_attestation_with_schema_accepts_valid_envelope() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = std::sync::Arc::new(PostgresBackend::connect(&dsn).await.unwrap());
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;
        let steward = format!("pg-sch-stw-§102-{}", uuid_like());
        let agent_k = format!("pg-sch-agt-§102-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                // CC 3.4.8 (CIRISPersist#366) — detector-only prefix; the
                // detection emitter must hold `lenscore_detector`.
                record: pg_admission_key(
                    &steward,
                    "registry",
                    crate::federation::types::identity_type::LENSCORE_DETECTOR,
                ),
            })
            .await
            .unwrap();
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &agent_k,
                    "primitive-sch",
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await
            .unwrap();

        // Schema requires score+confidence+evidence_refs.
        let schema = serde_json::json!({
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "type": "object",
            "required": ["dimension", "score", "confidence", "evidence_refs"],
        });
        let schema_bytes = serde_json::to_vec(&schema).unwrap();
        let schema_sha: [u8; 32] = {
            use sha2::{Digest, Sha256};
            Sha256::digest(&schema_bytes).into()
        };
        use crate::federation::BlobStorage;
        let now = chrono::Utc::now();
        let put_att = crate::federation::blobs::sealed_put_blob_attestation(
            &schema_sha,
            &steward,
            &steward,
            &uuid::Uuid::new_v4().to_string(),
            now,
            now,
        );
        backend
            .put_blob(
                &schema_sha,
                crate::federation::BlobBody::Inline(schema_bytes),
                Some("application/schema+json"),
                put_att,
            )
            .await
            .unwrap();
        let mut axis_index = std::collections::HashMap::new();
        axis_index.insert("rights_asymmetry".into(), schema_sha);
        let resolver = std::sync::Arc::new(crate::federation::BlobBackedSchemaResolver::new(
            axis_index,
            backend.clone(),
        ));
        backend.set_schema_resolver(resolver);

        let mut att = pg_scores_attestation(
            &steward,
            &agent_k,
            &steward,
            "detection:correlated_action:rights_asymmetry:v1",
        );
        att.attestation_envelope = serde_json::json!({
            "dimension": "detection:correlated_action:rights_asymmetry:v1",
            "score": 0.42,
            "confidence": 0.9,
            "evidence_refs": [hex::encode(schema_sha)],
        });
        pg_resign(&mut att); // envelope changed → re-sign (CC 5.3.2.4.3.1)
        backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .unwrap();
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_put_attestation_rejects_envelope_missing_required_field() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = std::sync::Arc::new(PostgresBackend::connect(&dsn).await.unwrap());
        backend.run_migrations().await.unwrap();
        use crate::federation::FederationDirectory;
        let steward = format!("pg-bsch-stw-§102-{}", uuid_like());
        let agent_k = format!("pg-bsch-agt-§102-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                // CC 3.4.8 (CIRISPersist#366) — detector-only prefix; the
                // detection emitter must hold `lenscore_detector` so the row
                // reaches the schema validator (rejected there for the missing
                // envelope field, not at the emitter gate).
                record: pg_admission_key(
                    &steward,
                    "registry",
                    crate::federation::types::identity_type::LENSCORE_DETECTOR,
                ),
            })
            .await
            .unwrap();
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &agent_k,
                    "primitive-bsch",
                    crate::federation::types::identity_type::AGENT,
                ),
            })
            .await
            .unwrap();

        let schema = serde_json::json!({
            "$schema": "https://json-schema.org/draft/2020-12/schema",
            "type": "object",
            "required": ["dimension", "score", "confidence", "evidence_refs"],
        });
        let schema_bytes = serde_json::to_vec(&schema).unwrap();
        let schema_sha: [u8; 32] = {
            use sha2::{Digest, Sha256};
            Sha256::digest(&schema_bytes).into()
        };
        use crate::federation::BlobStorage;
        let now = chrono::Utc::now();
        let put_att = crate::federation::blobs::sealed_put_blob_attestation(
            &schema_sha,
            &steward,
            &steward,
            &uuid::Uuid::new_v4().to_string(),
            now,
            now,
        );
        backend
            .put_blob(
                &schema_sha,
                crate::federation::BlobBody::Inline(schema_bytes),
                Some("application/schema+json"),
                put_att,
            )
            .await
            .unwrap();
        let mut axis_index = std::collections::HashMap::new();
        axis_index.insert("rights_asymmetry".into(), schema_sha);
        let resolver = std::sync::Arc::new(crate::federation::BlobBackedSchemaResolver::new(
            axis_index,
            backend.clone(),
        ));
        backend.set_schema_resolver(resolver);

        let mut att = pg_scores_attestation(
            &steward,
            &agent_k,
            &steward,
            "detection:correlated_action:rights_asymmetry:v1",
        );
        att.attestation_envelope = serde_json::json!({
            "dimension": "detection:correlated_action:rights_asymmetry:v1",
            "score": 0.42,
            "confidence": 0.9,
        });
        // v22.0.0 (CIRISPersist#543 / AV-76) — RE-SIGN after mutating the
        // envelope. The fixture overwrote `attestation_envelope` post-signing,
        // so the signature covered stale bytes. That was invisible while the
        // schema gate ran BEFORE the crypto; under the cheapest-first reorder
        // the hybrid verify runs first and correctly reports a bad signature,
        // so the test never reached the assertion it exists to make.
        //
        // The new ordering is also the more correct one: a writer whose
        // signature does not verify must not learn that our schema resolver
        // rejected their envelope — the information-leak discipline admission.rs
        // argues for. The old pass was asserting a leak the reorder closed.
        pg_resign(&mut att);
        let err = backend
            .put_attestation(crate::federation::SignedAttestation { attestation: att })
            .await
            .unwrap_err();
        match err {
            crate::federation::Error::EnvelopeSchemaViolation { axis, .. } => {
                assert_eq!(axis, "rights_asymmetry");
            }
            other => panic!("expected EnvelopeSchemaViolation, got {other:?}"),
        }
    }

