    // ─── v4.1 (CIRISPersist#142, Cut B) — PG ChunkDag parity ────────

    /// Build a 3-chunk inline manifest with run-unique chunk bytes (the
    /// PG test DB is shared, so the SHAs must not collide across runs).
    #[allow(clippy::type_complexity)]
    fn pg_three_chunk_manifest(
        tag: &str,
    ) -> (
        crate::federation::ChunkManifest,
        Vec<([u8; 32], crate::federation::BlobBody)>,
        [u8; 32],
    ) {
        use crate::federation::{BlobBody, ChunkManifest, ChunkRef};
        let salt = uuid_like();
        let c0 = format!("{tag}-AAAA-{salt}").into_bytes();
        let c1 = format!("{tag}-BBBB-{salt}").into_bytes();
        let c2 = format!("{tag}-CC-{salt}").into_bytes();
        let s0 = pg_sha256_of(&c0);
        let s1 = pg_sha256_of(&c1);
        let s2 = pg_sha256_of(&c2);
        let total = (c0.len() + c1.len() + c2.len()) as u64;
        let manifest = ChunkManifest {
            v: 1,
            total_size: total,
            chunks: vec![
                ChunkRef {
                    sha: s0,
                    size: c0.len() as u32,
                },
                ChunkRef {
                    sha: s1,
                    size: c1.len() as u32,
                },
                ChunkRef {
                    sha: s2,
                    size: c2.len() as u32,
                },
            ],
        };
        let manifest_sha = pg_sha256_of(&manifest.to_jcs_bytes());
        let chunks = vec![
            (s0, BlobBody::Inline(c0)),
            (s1, BlobBody::Inline(c1)),
            (s2, BlobBody::Inline(c2)),
        ];
        (manifest, chunks, manifest_sha)
    }

    /// put_blob_chunks round-trips a 3-chunk blob; get_blob returns the
    /// manifest; get_blob_range assembles across + within a chunk.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_chunk_dag_round_trip_and_range() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobRange, BlobStorage};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let (manifest, chunks, manifest_sha) = pg_three_chunk_manifest("dag-rt");
        // Compute the assembled full bytes for the assertion.
        let mut full = Vec::new();
        for (_, b) in &chunks {
            if let BlobBody::Inline(bytes) = b {
                full.extend_from_slice(bytes);
            }
        }
        let (c0_len, c1_len) = (
            manifest.chunks[0].size as u64,
            manifest.chunks[1].size as u64,
        );
        backend
            .put_blob_chunks(manifest.clone(), chunks)
            .await
            .unwrap();

        // get_blob returns the parsed manifest.
        match backend.get_blob(&manifest_sha).await.unwrap().unwrap() {
            BlobBody::ChunkDag(m) => assert_eq!(m, manifest),
            other => panic!("expected ChunkDag, got {other:?}"),
        }

        // Full range assembles the whole blob.
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, 0, manifest.total_size - 1)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(full.clone())
        );

        // A range spanning the chunk0/chunk1 boundary: last 2 of chunk0 +
        // first 2 of chunk1.
        let span_start = c0_len - 2;
        let span_end = c0_len + 1; // 2 bytes into chunk1
        let expect: Vec<u8> = full[span_start as usize..=span_end as usize].to_vec();
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, span_start, span_end)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(expect)
        );

        // A range entirely within chunk1.
        let inner_start = c0_len + 1;
        let inner_end = c0_len + c1_len - 2;
        let expect_inner: Vec<u8> = full[inner_start as usize..=inner_end as usize].to_vec();
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, inner_start, inner_end)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(expect_inner)
        );

        // Cleanup (shared DB).
        let _ = backend.delete_blob(&manifest_sha).await;
        let _ = backend.delete_blob(&manifest.chunks[0].sha).await;
        let _ = backend.delete_blob(&manifest.chunks[1].sha).await;
        let _ = backend.delete_blob(&manifest.chunks[2].sha).await;
    }

    /// SHA-mismatch chunk rejected; total_size mismatch rejected.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_chunk_dag_rejects_bad_inputs() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobError, BlobStorage};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        // SHA mismatch: corrupt chunk[0]'s bytes.
        let (manifest, mut chunks, _) = pg_three_chunk_manifest("dag-bad-sha");
        chunks[0].1 = BlobBody::Inline(b"corrupted-bytes".to_vec());
        assert!(matches!(
            backend
                .put_blob_chunks(manifest.clone(), chunks)
                .await
                .unwrap_err(),
            BlobError::HashMismatch { .. }
        ));
        // Atomicity: chunk[1] did not land.
        assert!(!backend.has_blob(&manifest.chunks[1].sha).await.unwrap());

        // total_size mismatch.
        let (mut manifest2, chunks2, _) = pg_three_chunk_manifest("dag-bad-size");
        manifest2.total_size += 1;
        assert!(matches!(
            backend
                .put_blob_chunks(manifest2, chunks2)
                .await
                .unwrap_err(),
            BlobError::InvalidArgument(_)
        ));
    }

    /// A range spanning an External chunk → typed RangeSpansExternalChunk.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_chunk_dag_range_spans_external_chunk() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{
            BlobBody, BlobError, BlobRange, BlobStorage, ChunkManifest, ChunkRef, ExternalRef,
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();
        let c0 = format!("ext-AAAA-{salt}").into_bytes();
        let s0 = pg_sha256_of(&c0);
        // A run-unique External chunk SHA.
        let mut s_ext = [0u8; 32];
        let nanos = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        s_ext[..16].copy_from_slice(&nanos.to_be_bytes());
        s_ext[16..].copy_from_slice(&nanos.to_be_bytes());
        let manifest = ChunkManifest {
            v: 1,
            total_size: c0.len() as u64 + 100,
            chunks: vec![
                ChunkRef {
                    sha: s0,
                    size: c0.len() as u32,
                },
                ChunkRef {
                    sha: s_ext,
                    size: 100,
                },
            ],
        };
        let manifest_sha = pg_sha256_of(&manifest.to_jcs_bytes());
        let chunks = vec![
            (s0, BlobBody::Inline(c0.clone())),
            (
                s_ext,
                BlobBody::External(ExternalRef {
                    uri: format!("s3://bucket/{}", uuid_like()),
                    size_bytes: 100,
                    media_type: None,
                }),
            ),
        ];
        backend
            .put_blob_chunks(manifest.clone(), chunks)
            .await
            .unwrap();

        // Range inside chunk0 only → fine.
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, 0, (c0.len() - 1) as u64)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(c0.clone())
        );
        // Range reaching into the External chunk → typed error.
        match backend
            .get_blob_range(&manifest_sha, 0, c0.len() as u64 + 10)
            .await
            .unwrap_err()
        {
            BlobError::RangeSpansExternalChunk { chunk_sha_hex } => {
                assert_eq!(chunk_sha_hex, hex::encode(s_ext));
            }
            other => panic!("expected RangeSpansExternalChunk, got {other:?}"),
        }

        // Cleanup.
        let _ = backend.delete_blob(&manifest_sha).await;
        let _ = backend.delete_blob(&s0).await;
        let _ = backend.delete_blob(&s_ext).await;
    }

    // ─── v4.1 (CIRISPersist#142, Cut C1a) — PG live stream chunks ───

    /// Append 3 chunks, seal, and read the assembled bytes back via
    /// get_blob_range over the sealed manifest sha — end-to-end with the
    /// Cut B ChunkDag path, including ranges crossing chunk boundaries.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_stream_append_seal_and_range_round_trip() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobRange, BlobStorage};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // Run-unique chunk bytes (shared test DB → SHAs must not collide).
        let salt = uuid_like();
        let c0 = format!("strm-AAAA-{salt}").into_bytes();
        let c1 = format!("strm-BBBB-{salt}").into_bytes();
        let c2 = format!("strm-CC-{salt}").into_bytes();
        let stream = format!("pg-stream-rt-{salt}");
        let (l0, l1, l2) = (c0.len() as u64, c1.len() as u64, c2.len() as u64);
        let total = l0 + l1 + l2;

        let s0 = backend
            .put_blob_chunk(&stream, 0, BlobBody::Inline(c0.clone()), 0)
            .await
            .unwrap();
        let s1 = backend
            .put_blob_chunk(&stream, 1, BlobBody::Inline(c1.clone()), 0)
            .await
            .unwrap();
        let s2 = backend
            .put_blob_chunk(&stream, 2, BlobBody::Inline(c2.clone()), 0)
            .await
            .unwrap();
        assert_eq!(s0, pg_sha256_of(&c0));
        assert_eq!(s1, pg_sha256_of(&c1));
        assert_eq!(s2, pg_sha256_of(&c2));

        let manifest_sha = backend.seal_stream(&stream).await.unwrap();

        // The sealed sha resolves as a ChunkDag manifest in seq order.
        match backend.get_blob(&manifest_sha).await.unwrap().unwrap() {
            BlobBody::ChunkDag(m) => {
                assert_eq!(m.total_size, total);
                assert_eq!(m.chunks.len(), 3);
                assert_eq!(m.chunks[0].sha, s0);
                assert_eq!(m.chunks[1].sha, s1);
                assert_eq!(m.chunks[2].sha, s2);
            }
            other => panic!("expected ChunkDag, got {other:?}"),
        }

        // Assemble the full bytes for the range assertions.
        let mut full = Vec::new();
        full.extend_from_slice(&c0);
        full.extend_from_slice(&c1);
        full.extend_from_slice(&c2);

        // Full range assembles the whole stream.
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, 0, total - 1)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(full.clone())
        );
        // A range crossing the chunk0/chunk1 boundary.
        let span_start = l0 - 2;
        let span_end = l0 + 1;
        let expect: Vec<u8> = full[span_start as usize..=span_end as usize].to_vec();
        assert_eq!(
            backend
                .get_blob_range(&manifest_sha, span_start, span_end)
                .await
                .unwrap()
                .unwrap(),
            BlobRange::Inline(expect)
        );

        // Cleanup (shared DB).
        let _ = backend.delete_blob(&manifest_sha).await;
        let _ = backend.delete_blob(&s0).await;
        let _ = backend.delete_blob(&s1).await;
        let _ = backend.delete_blob(&s2).await;
    }

    /// A re-used (stream_id, seq) is rejected (monotonicity guarantee).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_stream_seq_collision_rejected() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobError, BlobStorage};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();
        let stream = format!("pg-stream-collide-{salt}");
        let c0 = format!("first-{salt}").into_bytes();
        let s0 = backend
            .put_blob_chunk(&stream, 0, BlobBody::Inline(c0.clone()), 0)
            .await
            .unwrap();
        // Same seq, different bytes → PK conflict → InvalidArgument.
        let err = backend
            .put_blob_chunk(
                &stream,
                0,
                BlobBody::Inline(format!("second-{salt}").into_bytes()),
                0,
            )
            .await
            .unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
        // The stream seals to exactly the first chunk.
        let manifest_sha = backend.seal_stream(&stream).await.unwrap();
        match backend.get_blob(&manifest_sha).await.unwrap().unwrap() {
            BlobBody::ChunkDag(m) => {
                assert_eq!(m.chunks.len(), 1);
                assert_eq!(m.chunks[0].sha, s0);
            }
            other => panic!("expected ChunkDag, got {other:?}"),
        }
        let _ = backend.delete_blob(&manifest_sha).await;
        let _ = backend.delete_blob(&s0).await;
    }

    /// Sealing a stream with no chunks is rejected; a ChunkDag body to
    /// put_blob_chunk is rejected (can't chunk a chunk).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_stream_seal_empty_and_chunk_dag_body_rejected() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobError, BlobStorage, ChunkManifest, ChunkRef};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();

        // Empty stream → InvalidArgument.
        let err = backend
            .seal_stream(&format!("pg-empty-{salt}"))
            .await
            .unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));

        // ChunkDag body to put_blob_chunk → InvalidArgument.
        let nested = ChunkManifest {
            v: 1,
            total_size: 4,
            chunks: vec![ChunkRef {
                sha: pg_sha256_of(b"AAAA"),
                size: 4,
            }],
        };
        let err = backend
            .put_blob_chunk(&format!("pg-nest-{salt}"), 0, BlobBody::ChunkDag(nested), 0)
            .await
            .unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
    }

    // ─── v4.1 (CIRISPersist#142, Cut C1b) — PG per-stream transparency
    //     log: producer-signed STH + RFC 6962 proofs ─────────────────

    /// Register a real hybrid producer key in federation_keys (PG).
    async fn pg_register_hybrid_producer(
        backend: &PostgresBackend,
        key_id: &str,
    ) -> ciris_crypto::HybridSigner<ciris_crypto::Ed25519Signer, ciris_crypto::MlDsa65Signer> {
        use crate::federation::FederationDirectory as _;
        use base64::engine::general_purpose::STANDARD as B64;
        use base64::Engine as _;
        let ed = ciris_crypto::Ed25519Signer::from_seed(&[0x41; 32]).unwrap();
        let mldsa = ciris_crypto::MlDsa65Signer::from_seed(&[0x42; 32]).unwrap();
        let ed_pub_b64 = {
            use ciris_crypto::ClassicalSigner as _;
            B64.encode(ed.public_key().unwrap())
        };
        let mldsa_pub_b64 = {
            use ciris_crypto::PqcSigner as _;
            B64.encode(mldsa.public_key().unwrap())
        };
        // v9.0.0 — build the KeyRecord inline (NOT via `fix_section_i_key`):
        // both pubkeys are overwritten with this producer's real hybrid
        // keys anyway, and `fix_section_i_key` now derives ML-DSA pubkeys
        // (a multi-KiB keygen) which, stacked on this frame's own ML-DSA
        // signer + HybridSigner, overflowed the tokio worker stack.
        let now = chrono::Utc::now();
        let record = crate::federation::KeyRecord {
            key_id: key_id.into(),
            pubkey_ed25519_base64: ed_pub_b64,
            pubkey_ml_dsa_65_base64: Some(mldsa_pub_b64),
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: crate::federation::types::identity_type::AGENT.into(),
            identity_ref: key_id.into(),
            valid_from: now,
            valid_until: None,
            registration_envelope: serde_json::json!({ "id": key_id }),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: Some("c2ln".into()),
            scrub_key_id: key_id.into(),
            scrub_timestamp: now,
            pqc_completed_at: Some(now),
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            attestation_evidence: None,
            consent_role: None,
            additional_scrubs: Vec::new(),
        };
        backend
            .put_public_key(crate::federation::SignedKeyRecord { record })
            .await
            .unwrap();
        ciris_crypto::HybridSigner::new(ed, mldsa).unwrap()
    }

    fn pg_sign_stream_sth(
        signer: &ciris_crypto::HybridSigner<
            ciris_crypto::Ed25519Signer,
            ciris_crypto::MlDsa65Signer,
        >,
        stream_id: &str,
        chunk_hashes: &[[u8; 32]],
        tree_size: u64,
    ) -> ciris_verify_core::transparency::SignedTreeHead {
        use crate::federation::stream_sth::StreamChunkLeaf;
        use ciris_verify_core::transparency::{InMemoryTransparencyStore, TransparencyStore};
        let store: InMemoryTransparencyStore<StreamChunkLeaf> =
            InMemoryTransparencyStore::new(None);
        for sha in &chunk_hashes[..tree_size as usize] {
            store.append(StreamChunkLeaf::new(*sha)).unwrap();
        }
        let root_hash = store.root().unwrap();
        let log_id = crate::federation::stream_sth::log_id_for_stream(stream_id);
        let timestamp = chrono::Utc::now();
        let signing_bytes = ciris_verify_core::transparency::SignedTreeHead::signing_bytes(
            &log_id, tree_size, &root_hash, timestamp,
        );
        let signature = signer.sign(&signing_bytes).unwrap();
        ciris_verify_core::transparency::SignedTreeHead {
            log_id,
            tree_size,
            root_hash,
            timestamp,
            signature,
            witness_signatures: Vec::new(),
        }
    }

    /// Run an async PG-STH test body on a dedicated thread with a large
    /// stack. The ML-DSA-65 hybrid sign/verify is stack-heavy in debug
    /// builds; combined with tokio-postgres/deadpool frames it overflows
    /// the default test-thread stack. A 32 MiB std::thread + a
    /// current-thread runtime keeps the body self-contained (no
    /// RUST_MIN_STACK dependency).
    fn pg_run_big_stack<F, Fut>(f: F)
    where
        F: FnOnce() -> Fut + Send + 'static,
        Fut: std::future::Future<Output = ()>,
    {
        std::thread::Builder::new()
            .stack_size(32 * 1024 * 1024)
            .spawn(move || {
                let rt = tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .unwrap();
                rt.block_on(f());
            })
            .unwrap()
            .join()
            .unwrap();
    }

    #[test]
    #[serial_test::serial(postgres)]
    fn pg_sth_round_trip_and_proofs_verify() {
        pg_run_big_stack(pg_sth_round_trip_and_proofs_verify_inner);
    }

    async fn pg_sth_round_trip_and_proofs_verify_inner() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobStorage};
        use ciris_verify_core::transparency::{verify_consistency, verify_inclusion};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();
        let key_id = format!("pg-producer-{salt}");
        let signer = pg_register_hybrid_producer(&backend, &key_id).await;
        let stream = format!("pg-sth-rt-{salt}");

        let mut hashes = Vec::new();
        let mut shas = Vec::new();
        for (seq, tag) in ["AAAA", "BBBB", "CC", "DDDD"].iter().enumerate() {
            let body = format!("sth-{tag}-{salt}").into_bytes();
            let sha = backend
                .put_blob_chunk(&stream, seq as u64, BlobBody::Inline(body), 0)
                .await
                .unwrap();
            hashes.push(sha);
            shas.push(sha);
        }

        let sth = pg_sign_stream_sth(&signer, &stream, &hashes, 4);
        backend.put_stream_sth(sth.clone(), &key_id).await.unwrap();

        let stored = backend.latest_stream_sth(&stream).await.unwrap().unwrap();
        assert_eq!(stored.tree_size, 4);
        assert_eq!(stored.root_hash, sth.root_hash);
        assert_eq!(stored.log_id, sth.log_id);

        let proof = backend
            .stream_inclusion_proof(&stream, 2, 4)
            .await
            .unwrap()
            .unwrap();
        assert!(verify_inclusion(&proof));
        assert_eq!(proof.root, sth.root_hash);

        let sth2 = pg_sign_stream_sth(&signer, &stream, &hashes, 2);
        let cproof = backend
            .stream_consistency_proof(&stream, 2, 4)
            .await
            .unwrap()
            .unwrap();
        assert!(verify_consistency(&sth2.root_hash, 2, &sth.root_hash, 4, &cproof).unwrap());

        // Idempotent re-PUT.
        backend.put_stream_sth(sth, &key_id).await.unwrap();

        // Cleanup (shared DB).
        let client = backend.get_client().await.unwrap();
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_stream_sth WHERE stream_id = $1",
                &[&stream],
            )
            .await;
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_stream_chunks WHERE stream_id = $1",
                &[&stream],
            )
            .await;
        for sha in &shas {
            let _ = backend.delete_blob(sha).await;
        }
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_keys WHERE key_id = $1",
                &[&key_id],
            )
            .await;
    }

    /// v31.0.0 (CIRISPersist#657) — POSTGRES PARITY for the witness-cosignature
    /// gate. `put_stream_sth` stored `witness_signatures` verbatim on both
    /// backends and no verify call for them existed anywhere in `src/`; the
    /// remedy has to be witnessed on the backend production runs, not only on
    /// the one the unit tests reach for.
    #[test]
    #[serial_test::serial(postgres)]
    fn sth_witness_cosignatures_are_verified_at_the_door_pg() {
        pg_run_big_stack(sth_witness_cosignatures_are_verified_at_the_door_pg_inner);
    }

    async fn sth_witness_cosignatures_are_verified_at_the_door_pg_inner() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobStorage};
        use ciris_verify_core::transparency::WitnessConsistencyProof;
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();
        // The DISTINGUISHING part leads: key_ids are truncated at 32 bytes by
        // the shared seed derivation, and a uuid-first tag would make the
        // producer and the witness the same identity.
        let producer = format!("producer-witness-{salt}");
        let signer = pg_register_hybrid_producer(&backend, &producer).await;
        let stream = format!("pg-sth-witness-{salt}");
        let mut hashes = Vec::new();
        for (seq, tag) in ["AAAA", "BBBB"].iter().enumerate() {
            let body = format!("wit-{tag}-{salt}").into_bytes();
            hashes.push(
                backend
                    .put_blob_chunk(&stream, seq as u64, BlobBody::Inline(body), 0)
                    .await
                    .unwrap(),
            );
        }
        let base = pg_sign_stream_sth(&signer, &stream, &hashes, 2);

        // (1) UNREGISTERED witness: nothing in the directory to verify against.
        let unreg = format!("unregistered-witness-{salt}");
        let stranger = pg_witness_signer();
        let mut sth = base.clone();
        let cosig = sth
            .cosign(&unreg, &stranger, WitnessConsistencyProof::genesis())
            .expect("cosign");
        sth.witness_signatures.push(cosig);
        let err = backend
            .put_stream_sth(sth, &producer)
            .await
            .expect_err("an unregistered witness must not be stored");
        assert!(
            format!("{err}").contains("witness"),
            "the refusal names the witness leg: {err}"
        );
        assert!(
            backend.latest_stream_sth(&stream).await.unwrap().is_none(),
            "a refused STH is not stored at all"
        );

        // (2) REGISTERED witness, signature over a DIFFERENT tree.
        let wit = format!("registered-witness-{salt}");
        let witness = pg_register_witness(&backend, &wit).await;
        let other = pg_sign_stream_sth(&signer, &stream, &hashes, 1);
        let cosig = other
            .cosign(&wit, &witness, WitnessConsistencyProof::genesis())
            .expect("cosign");
        let mut sth = base.clone();
        sth.witness_signatures.push(cosig);
        backend
            .put_stream_sth(sth, &producer)
            .await
            .expect_err("a cosignature over other bytes must not be stored");

        // (3) The genuine cosignature is admitted and round-trips.
        let mut sth = base.clone();
        let cosig = sth
            .cosign(&wit, &witness, WitnessConsistencyProof::genesis())
            .expect("cosign");
        sth.witness_signatures.push(cosig);
        backend
            .put_stream_sth(sth, &producer)
            .await
            .expect("a verified cosignature is admitted");
        let stored = backend.latest_stream_sth(&stream).await.unwrap().unwrap();
        assert_eq!(stored.witness_signatures.len(), 1);
        assert_eq!(stored.witness_signatures[0].witness_id, wit);
    }

    /// v31.0.0 (CIRISPersist#657) — a witness keypair distinct from
    /// [`pg_register_hybrid_producer`]'s, NOT registered.
    fn pg_witness_signer(
    ) -> ciris_crypto::HybridSigner<ciris_crypto::Ed25519Signer, ciris_crypto::MlDsa65Signer> {
        let ed = ciris_crypto::Ed25519Signer::from_seed(&[0x51; 32]).unwrap();
        let mldsa = ciris_crypto::MlDsa65Signer::from_seed(&[0x52; 32]).unwrap();
        ciris_crypto::HybridSigner::new(ed, mldsa).unwrap()
    }

    /// v31.0.0 (CIRISPersist#657) — [`pg_witness_signer`]'s keypair, REGISTERED
    /// under `key_id` so the directory can resolve its pinned pubkeys.
    async fn pg_register_witness(
        backend: &PostgresBackend,
        key_id: &str,
    ) -> ciris_crypto::HybridSigner<ciris_crypto::Ed25519Signer, ciris_crypto::MlDsa65Signer> {
        use crate::federation::FederationDirectory as _;
        use base64::engine::general_purpose::STANDARD as B64;
        use base64::Engine as _;
        let ed = ciris_crypto::Ed25519Signer::from_seed(&[0x51; 32]).unwrap();
        let mldsa = ciris_crypto::MlDsa65Signer::from_seed(&[0x52; 32]).unwrap();
        let ed_pub_b64 = {
            use ciris_crypto::ClassicalSigner as _;
            B64.encode(ed.public_key().unwrap())
        };
        let mldsa_pub_b64 = {
            use ciris_crypto::PqcSigner as _;
            B64.encode(mldsa.public_key().unwrap())
        };
        let now = chrono::Utc::now();
        let record = crate::federation::KeyRecord {
            key_id: key_id.into(),
            pubkey_ed25519_base64: ed_pub_b64,
            pubkey_ml_dsa_65_base64: Some(mldsa_pub_b64),
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: crate::federation::types::identity_type::AGENT.into(),
            identity_ref: key_id.into(),
            valid_from: now,
            valid_until: None,
            registration_envelope: serde_json::json!({ "id": key_id }),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: Some("c2ln".into()),
            scrub_key_id: key_id.into(),
            scrub_timestamp: now,
            pqc_completed_at: Some(now),
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            attestation_evidence: None,
            consent_role: None,
            additional_scrubs: Vec::new(),
        };
        backend
            .put_public_key(crate::federation::SignedKeyRecord { record })
            .await
            .unwrap();
        ciris_crypto::HybridSigner::new(ed, mldsa).unwrap()
    }

    #[test]
    #[serial_test::serial(postgres)]
    fn pg_sth_security_gate_negatives() {
        pg_run_big_stack(pg_sth_security_gate_negatives_inner);
    }

    async fn pg_sth_security_gate_negatives_inner() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobError, BlobStorage};
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let salt = uuid_like();
        let key_id = format!("pg-producer-neg-{salt}");
        let signer = pg_register_hybrid_producer(&backend, &key_id).await;
        let stream = format!("pg-sth-neg-{salt}");

        let mut hashes = Vec::new();
        let mut shas = Vec::new();
        for (seq, tag) in ["AAAA", "BBBB"].iter().enumerate() {
            let body = format!("neg-{tag}-{salt}").into_bytes();
            let sha = backend
                .put_blob_chunk(&stream, seq as u64, BlobBody::Inline(body), 0)
                .await
                .unwrap();
            hashes.push(sha);
            shas.push(sha);
        }

        // (a) root mismatch (re-signed so the SIG is valid but the root
        //     does not match persist's chunks).
        let mut bad_root = pg_sign_stream_sth(&signer, &stream, &hashes, 2);
        bad_root.root_hash = [0xAB; 32];
        let sb = ciris_verify_core::transparency::SignedTreeHead::signing_bytes(
            &bad_root.log_id,
            2,
            &bad_root.root_hash,
            bad_root.timestamp,
        );
        bad_root.signature = signer.sign(&sb).unwrap();
        let err = backend.put_stream_sth(bad_root, &key_id).await.unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
        assert!(format!("{err}").contains("root mismatch"));

        // (b) bad/forged producer signature (root matches).
        let mut bad_sig = pg_sign_stream_sth(&signer, &stream, &hashes, 2);
        for b in &mut bad_sig.signature.classical.signature {
            *b ^= 0xFF;
        }
        let err = backend.put_stream_sth(bad_sig, &key_id).await.unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
        assert!(format!("{err}").contains("signature verification failed"));

        // (c) over-claimed tree_size (> stored chunks).
        let mut over = pg_sign_stream_sth(&signer, &stream, &hashes, 2);
        over.tree_size = 5;
        let sb = ciris_verify_core::transparency::SignedTreeHead::signing_bytes(
            &over.log_id,
            5,
            &over.root_hash,
            over.timestamp,
        );
        over.signature = signer.sign(&sb).unwrap();
        let err = backend.put_stream_sth(over, &key_id).await.unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
        assert!(format!("{err}").contains("only 2 chunks"));

        // (d) equivocation: a valid STH lands, then the stored root is
        //     tampered and the correct STH is re-PUT → different root at
        //     the same (stream, tree_size) → reject.
        let good = pg_sign_stream_sth(&signer, &stream, &hashes, 2);
        backend.put_stream_sth(good.clone(), &key_id).await.unwrap();
        let client = backend.get_client().await.unwrap();
        client
            .execute(
                "UPDATE cirislens.federation_stream_sth SET root_hash = $1 \
                   WHERE stream_id = $2 AND tree_size = 2",
                &[&vec![0xCDu8; 32], &stream],
            )
            .await
            .unwrap();
        let err = backend.put_stream_sth(good, &key_id).await.unwrap_err();
        assert!(matches!(err, BlobError::InvalidArgument(_)));
        assert!(format!("{err}").contains("equivocation"));

        // Cleanup.
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_stream_sth WHERE stream_id = $1",
                &[&stream],
            )
            .await;
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_stream_chunks WHERE stream_id = $1",
                &[&stream],
            )
            .await;
        for sha in &shas {
            let _ = backend.delete_blob(sha).await;
        }
        let _ = client
            .execute(
                "DELETE FROM cirislens.federation_keys WHERE key_id = $1",
                &[&key_id],
            )
            .await;
    }

    // ─── v3.4.0 (CIRISPersist#123) — PG sweeper parity ─────────────

    /// PG parity for `sweeper_idle_when_below_watermark_sqlite`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn sweeper_idle_when_below_watermark_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::BlobBody;
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // Seed key + a handful of small blobs.
        let host = format!("idle-host-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &host).await;
        let mut shas = Vec::new();
        for i in 0..3 {
            let bytes = vec![(i + 1) as u8; 256];
            let sha = pg_sha256_of(&bytes);
            use crate::federation::BlobStorage;
            backend
                .put_blob(
                    &sha,
                    BlobBody::Inline(bytes),
                    None,
                    pg_blob_attestation(&sha, &host, &host),
                )
                .await
                .unwrap();
            shas.push(sha);
        }
        // Compose an Engine view over this backend so we can drive
        // sweep_evictions_once with a high budget.
        use crate::signing::LocalSigner;
        use ed25519_dalek::SigningKey;
        let signer = std::sync::Arc::new(LocalSigner::from_parts(
            SigningKey::from_bytes(&[0x9A; 32]),
            host.clone(),
            None,
            None,
        ));
        let cfg = crate::federation::ReplicationConfig {
            storage_budget_bytes: 100_000_000, // 100 MB — far above seeded.
            steady_state_utilization: 0.92,
            ..Default::default()
        };
        let engine = crate::Engine::with_replication_config(signer, &dsn, cfg)
            .await
            .unwrap();
        let report = engine.sweep_evictions_once().await.expect("sweep");
        assert_eq!(report.rows_evicted, 0);
        assert_eq!(report.withdraws_emitted, 0);
        // Cleanup: caller-managed (shared PG DB).
        for sha in &shas {
            let _ = backend.delete_blob(sha).await;
        }
    }

    /// PG parity for `sweeper_emits_withdraws_on_eviction_sqlite`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn sweeper_emits_withdraws_on_eviction_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        // Each run uses a freshly-seeded host_key_id so the
        // list_attestations_by query is scoped to this test only,
        // even on the shared PG database.
        let host = format!("evict-host-{}", uuid_like());
        // v9.0.0 (CC 5.3.2.4.3.1) — a PQC-configured LocalSigner keyed on
        // `host` (deterministic; matches the hybrid pubkeys
        // pg_blob_bootstrap_host registers via fix_section_i_key) so the
        // sweeper's federation-tier withdraws verifies at the ingest gate.
        let signer = crate::federation::tier_ingest::test_support::local_signer(&host);
        // v9.3.0 (#247) — the real-node shape: the steward's registered
        // federation key_id is the DERIVED id (`<alias>-<fp>`); the sweeper
        // now matches + withdraws by it, so the FK row + holds_bytes are
        // seeded under the derived id (carrying `host`'s real pubkeys so the
        // ingest gate verifies).
        let derived = signer.derived_key_id();
        let cfg = crate::federation::ReplicationConfig {
            // Very tight budget so eviction is forced.
            storage_budget_bytes: 1024,
            steady_state_utilization: 0.5,
            eviction_decay_half_life_days: 365.0,
            ..Default::default()
        };
        let engine = crate::Engine::with_replication_config(signer.clone(), &dsn, cfg)
            .await
            .unwrap();
        // Seed the federation_keys row for the signer (FK target for
        // withdraws attestations), keyed by the DERIVED id but carrying
        // `host`'s real hybrid pubkeys.
        let pg = engine.postgres_backend().expect("pg").clone();
        {
            use crate::federation::FederationDirectory;
            let mut record = fix_section_i_key(&host, &host, chrono::Utc::now(), false);
            record.key_id = derived.clone();
            record.identity_ref = derived.clone();
            record.scrub_key_id = derived.clone();
            record.registration_envelope = serde_json::json!({ "id": derived.clone() });
            pg.put_public_key(crate::federation::SignedKeyRecord { record })
                .await
                .unwrap();
        }
        // Seed 5 × 1 KiB blobs via the Engine's put_blob_signing path
        // so each lands a holds_bytes attestation owned by the
        // signer (the derived id).
        use crate::federation::BlobBody;
        let mut shas = Vec::new();
        for i in 0..5 {
            let bytes = vec![(i + 1) as u8; 1024];
            let sha = pg_sha256_of(&bytes);
            engine
                .put_blob_signing(
                    &sha,
                    BlobBody::Inline(bytes),
                    None,
                    &derived,
                    chrono::Utc::now(),
                    uuid::Uuid::new_v4(),
                )
                .await
                .unwrap();
            shas.push(sha);
        }

        let report = engine.sweep_evictions_once().await.expect("sweep");
        assert!(report.rows_evicted > 0);
        // On a shared PG database the sweeper may evict blobs left
        // behind by other tests (they have no holds_bytes from THIS
        // signer); for those the withdraws emission is silently
        // skipped per architect's contract. So we assert the
        // emission count covers AT LEAST the blobs WE inserted
        // (whose prior holds_bytes IS owned by `host`).
        assert!(
            report.withdraws_emitted >= 1,
            "withdraws_emitted must be ≥1 since we seeded holds_bytes \
             attestations under this host"
        );
        assert!(
            report.withdraws_emitted <= report.rows_evicted,
            "withdraws_emitted ≤ rows_evicted invariant"
        );

        // Confirm at least one withdraws row exists in PG
        // federation_attestations for this signer.
        let directory = engine.federation_directory();
        let atts = directory.list_attestations_by(&derived).await.unwrap();
        let withdraws_count = atts
            .iter()
            .filter(|a| a.attestation_type == crate::federation::types::attestation_type::WITHDRAWS)
            .count();
        assert!(
            withdraws_count >= report.withdraws_emitted as usize,
            "PG must have ≥{} withdraws rows for this signer; got {}",
            report.withdraws_emitted,
            withdraws_count
        );

        // Cleanup: drop any surviving blobs so concurrent tests
        // aren't impacted by per-budget bytes-budget accumulation
        // across runs (shared PG DB).
        for sha in &shas {
            let _ = pg.delete_blob(sha).await;
        }
    }

    /// PG parity for `sweeper_evicts_lowest_score_first_sqlite`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn sweeper_evicts_lowest_score_first_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobStorage};
        let host = format!("score-host-{}", uuid_like());
        // v9.3.0 (#247) — deterministic keypair (matching hybrid_pubkeys)
        // so the signer's DERIVED id == the one `pg_blob_bootstrap_host`
        // registers; put_blob_signing's holds_bytes scrub FK then resolves.
        let signer = crate::federation::tier_ingest::test_support::local_signer(&host);
        let derived = pg_derived_id_for(&host);
        let cfg = crate::federation::ReplicationConfig {
            storage_budget_bytes: 4 * 1024,
            steady_state_utilization: 0.9,
            eviction_decay_half_life_days: 365.0,
            ..Default::default()
        };
        let engine = crate::Engine::with_replication_config(signer, &dsn, cfg)
            .await
            .unwrap();
        let pg = engine.postgres_backend().expect("pg").clone();
        pg_blob_bootstrap_host(&pg, &host).await;
        let mut shas = Vec::new();
        for i in 0..5 {
            let bytes = vec![(i + 10) as u8; 1024];
            let sha = pg_sha256_of(&bytes);
            engine
                .put_blob_signing(
                    &sha,
                    BlobBody::Inline(bytes),
                    None,
                    &derived,
                    chrono::Utc::now(),
                    uuid::Uuid::new_v4(),
                )
                .await
                .unwrap();
            shas.push(sha);
        }
        // Bump access_count on the OLDEST three so they outrank.
        for sha in &shas[..3] {
            for _ in 0..3 {
                let _ = pg.get_blob(sha).await.unwrap();
            }
        }
        let report = engine.sweep_evictions_once().await.expect("sweep");
        assert!(report.rows_evicted > 0);
        // Hot blobs must survive.
        for sha in &shas[..3] {
            assert!(
                pg.has_blob(sha).await.unwrap(),
                "PG: hot blob must survive eviction"
            );
        }
        // Cleanup.
        for sha in &shas {
            let _ = pg.delete_blob(sha).await;
        }
    }

    /// PG parity for `list_holders_filters_evicted_rows_sqlite`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn list_holders_filters_evicted_rows_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::{BlobBody, BlobStorage};
        let host = format!("list-holders-host-{}", uuid_like());
        // v9.0.0 (CC 5.3.2.4.3.1) — PQC-configured LocalSigner keyed on
        // `host` (matches pg_blob_bootstrap_host's registered pubkeys) so
        // the sweeper's federation-tier withdraws verifies at the gate.
        let signer = crate::federation::tier_ingest::test_support::local_signer(&host);
        // v9.3.0 (#247) — the holder/attester is the signer's DERIVED
        // federation key_id; the sweeper matches + withdraws by it.
        let derived = pg_derived_id_for(&host);
        let cfg = crate::federation::ReplicationConfig {
            storage_budget_bytes: 1024,
            steady_state_utilization: 0.5,
            eviction_decay_half_life_days: 365.0,
            ..Default::default()
        };
        let engine = crate::Engine::with_replication_config(signer, &dsn, cfg)
            .await
            .unwrap();
        let pg = engine.postgres_backend().expect("pg").clone();
        pg_blob_bootstrap_host(&pg, &host).await;
        let mut shas = Vec::new();
        for i in 0..3 {
            let bytes = vec![(i + 20) as u8; 1024];
            let sha = pg_sha256_of(&bytes);
            engine
                .put_blob_signing(
                    &sha,
                    BlobBody::Inline(bytes),
                    None,
                    &derived,
                    chrono::Utc::now(),
                    uuid::Uuid::new_v4(),
                )
                .await
                .unwrap();
            shas.push(sha);
        }
        // Before sweep: each blob has this signer (derived id) as holder.
        for sha in &shas {
            let holders = pg.list_holders(sha).await.unwrap();
            assert!(holders.contains(&derived));
        }
        let report = engine.sweep_evictions_once().await.expect("sweep");
        assert!(report.rows_evicted > 0);
        // Count how many of OUR test's blobs got evicted (others may
        // have been swept up from concurrent-test pollution on the
        // shared PG DB — those have no prior holds_bytes from our
        // signer so their withdraws emission is silently skipped per
        // architect's contract).
        let mut my_evicted_count = 0usize;
        for sha in &shas {
            if !pg.has_blob(sha).await.unwrap() {
                my_evicted_count += 1;
            }
        }
        assert!(
            my_evicted_count >= 1,
            "at least one of our blobs must have been evicted"
        );
        // For each of OUR evicted blobs, the host is no longer a
        // listed holder (because the withdraws covers it).
        for sha in &shas {
            if pg.has_blob(sha).await.unwrap() {
                continue;
            }
            let holders = pg.list_holders(sha).await.unwrap();
            assert!(
                !holders.contains(&derived),
                "evicted blob must have host removed from holders"
            );
        }
        for sha in &shas {
            let _ = pg.delete_blob(sha).await;
        }
    }

    // ─── v3.5.0 (CIRISPersist#125) — list_held_by + evict_actor ────

    /// v9.0.0 (CC 5.3.2.4.3.1) — a PQC-configured LocalSigner keyed on
    /// `alias` (deterministic; matches the pubkeys `fix_section_i_key` /
    /// `pg_blob_bootstrap_host` register) so the federation-tier withdraws
    /// `evict_actor` emits verifies at the ingest gate.
    fn pg_test_signer_for(alias: &str) -> std::sync::Arc<crate::signing::LocalSigner> {
        crate::federation::tier_ingest::test_support::local_signer(alias)
    }

    /// Wrap a test LocalSigner as a `&dyn HardwareSigner` for the
    /// classical-only `put_blob_signing` (holds_bytes) seeding path.
    fn pg_blob_signer(
        local: &std::sync::Arc<crate::signing::LocalSigner>,
    ) -> crate::signing::LocalSignerHardwareAdapter {
        crate::signing::LocalSignerHardwareAdapter::new(local.clone())
    }

    /// Seed `n` blobs from `actor` via the trait `put_blob_signing`
    /// path; each payload is uniquified with `uuid_like()` so PG SHAs
    /// don't collide across concurrent tests on the shared DB.
    async fn pg_seed_blobs_for_actor(
        backend: &PostgresBackend,
        actor: &str,
        signer: &std::sync::Arc<crate::signing::LocalSigner>,
        n: usize,
        tag: &str,
    ) -> Vec<[u8; 32]> {
        use crate::federation::{BlobBody, BlobStorage};
        let hw = pg_blob_signer(signer);
        let mut shas = Vec::with_capacity(n);
        for i in 0..n {
            let bytes = format!("{actor}-{tag}-{i}-{}", uuid_like()).into_bytes();
            let sha = pg_sha256_of(&bytes);
            backend
                .put_blob_signing(
                    &sha,
                    BlobBody::Inline(bytes),
                    None,
                    actor,
                    &hw,
                    chrono::Utc::now(),
                    uuid::Uuid::new_v4(),
                )
                .await
                .unwrap();
            shas.push(sha);
        }
        shas
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn list_held_by_returns_actor_shas_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let actor_a = format!("evict-A-{}", uuid_like());
        let actor_b = format!("evict-B-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &actor_a).await;
        pg_blob_bootstrap_host(&backend, &actor_b).await;
        let signer_a = pg_test_signer_for(&actor_a);
        let signer_b = pg_test_signer_for(&actor_b);
        let shas_a = pg_seed_blobs_for_actor(&backend, &actor_a, &signer_a, 3, "main").await;
        let shas_b = pg_seed_blobs_for_actor(&backend, &actor_b, &signer_b, 2, "main").await;

        use crate::federation::BlobStorage;
        let mut held_a = backend.list_held_by(&actor_a).await.unwrap();
        held_a.sort();
        let mut expected_a = shas_a.clone();
        expected_a.sort();
        assert_eq!(held_a, expected_a, "A's holdings");

        let mut held_b = backend.list_held_by(&actor_b).await.unwrap();
        held_b.sort();
        let mut expected_b = shas_b.clone();
        expected_b.sort();
        assert_eq!(held_b, expected_b, "B's holdings");

        // Cleanup.
        for sha in shas_a.iter().chain(shas_b.iter()) {
            let _ = backend.delete_blob(sha).await;
        }
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn list_held_by_filters_withdrawn_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let actor = format!("evict-W-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &actor).await;
        let signer = pg_test_signer_for(&actor);
        let shas = pg_seed_blobs_for_actor(&backend, &actor, &signer, 1, "withdrawn").await;

        use crate::federation::FederationDirectory;
        let atts = backend.list_attestations_by(&actor).await.unwrap();
        let holds_bytes = atts
            .into_iter()
            .find(|a| {
                a.attestation_type
                    .starts_with(crate::federation::HOLDS_BYTES_ATTESTATION_TYPE_PREFIX)
            })
            .expect("holds_bytes from actor");
        // v9.0.0 (CC 5.3.2.4.3.1) — build via pg_scores_attestation +
        // pg_resign so the federation-tier ingest gate verifies it.
        let mut withdraws = pg_scores_attestation(&actor, &actor, &actor, "identity_binding:v1");
        withdraws.attestation_type =
            crate::federation::types::attestation_type::WITHDRAWS.to_owned();
        withdraws.weight = None;
        crate::federation::tier_ingest::test_support::reseal(&mut withdraws);
        withdraws.attestation_envelope = serde_json::json!({
            "kind": "withdraws",
            "references_attestation_id": holds_bytes.attestation_id,
            "references_attestation_type": holds_bytes.attestation_type,
        });
        pg_resign(&mut withdraws);
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: withdraws,
            })
            .await
            .unwrap();

        use crate::federation::BlobStorage;
        let held = backend.list_held_by(&actor).await.unwrap();
        assert!(
            !held.contains(&shas[0]),
            "withdrawn blob must be excluded, got {held:?}"
        );

        for sha in &shas {
            let _ = backend.delete_blob(sha).await;
        }
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn evict_actor_evicts_blobs_and_emits_withdraws_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let actor_a = format!("evict-go-A-{}", uuid_like());
        let actor_b = format!("evict-go-B-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &actor_a).await;
        pg_blob_bootstrap_host(&backend, &actor_b).await;
        let signer_a = pg_test_signer_for(&actor_a);
        let signer_b = pg_test_signer_for(&actor_b);
        let shas_a = pg_seed_blobs_for_actor(&backend, &actor_a, &signer_a, 3, "evict").await;
        let shas_b = pg_seed_blobs_for_actor(&backend, &actor_b, &signer_b, 2, "evict").await;

        use crate::federation::BlobStorage;
        let report = backend
            .evict_actor(&actor_a, &signer_a, chrono::Utc::now())
            .await
            .unwrap();
        assert_eq!(report.blobs_evicted, 3, "A's 3 blobs evicted");
        assert_eq!(report.withdraws_emitted, 3, "3 withdraws emitted");
        assert_eq!(report.withdraws_failed, 0, "no failures");

        // A's blobs gone.
        for sha in &shas_a {
            assert!(
                !backend.has_blob(sha).await.unwrap(),
                "A's blob {sha:?} should be gone"
            );
        }
        // B's blobs intact.
        for sha in &shas_b {
            assert!(
                backend.has_blob(sha).await.unwrap(),
                "B's blob {sha:?} must remain"
            );
        }

        for sha in &shas_b {
            let _ = backend.delete_blob(sha).await;
        }
    }

