    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn evict_actor_returns_correct_report_under_partial_failure_pg() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let actor = format!("evict-partial-{}", uuid_like());
        pg_blob_bootstrap_host(&backend, &actor).await;
        let real_signer = pg_test_signer_for(&actor);
        let shas = pg_seed_blobs_for_actor(&backend, &actor, &real_signer, 1, "partial").await;

        // v9.0.0 (CC 5.3.2.4.3.1) — a NON-PQC LocalSigner cannot
        // hybrid-sign, so the withdraws emission fails (PqcNotConfigured)
        // → exercises the withdraws_failed fail-honest path (the blob row
        // is still evicted). Replaces the pre-v9.0.0 PgAlwaysFailingSigner.
        let failing = std::sync::Arc::new(crate::signing::LocalSigner::from_parts(
            ed25519_dalek::SigningKey::from_bytes(&[0x42; 32]),
            actor.clone(),
            None,
            None,
        ));
        use crate::federation::BlobStorage;
        let report = backend
            .evict_actor(&actor, &failing, chrono::Utc::now())
            .await
            .unwrap();
        assert_eq!(report.blobs_evicted, 1, "blob still evicted");
        assert_eq!(report.withdraws_emitted, 0, "no withdraws emitted");
        assert_eq!(report.withdraws_failed, 1, "1 withdraws failed");
        assert!(
            !backend.has_blob(&shas[0]).await.unwrap(),
            "blob row deletion proceeds despite withdraws failure"
        );
    }

    // ── v3.6.0 (CIRISPersist#134, CEG 0.3 §11.5.3) — trusted-publisher chain ──

    fn fix_trusted_publisher_key(
        key_id: &str,
        identity_type: &str,
    ) -> crate::federation::KeyRecord {
        // v9.0.0 (CC 5.3.2.4.3.1) — real deterministic hybrid pubkeys so
        // the federation-tier ingest gate can verify this publisher's
        // content-rating attestations.
        let (ed_pk, mldsa_pk) =
            crate::federation::tier_ingest::test_support::hybrid_pubkeys(key_id);
        crate::federation::KeyRecord {
            key_id: key_id.into(),
            pubkey_ed25519_base64: ed_pk,
            pubkey_ml_dsa_65_base64: mldsa_pk,
            algorithm: crate::federation::types::algorithm::HYBRID.into(),
            identity_type: identity_type.into(),
            identity_ref: key_id.into(),
            valid_from: "2026-05-01T00:00:00Z".parse().unwrap(),
            valid_until: None,
            registration_envelope: serde_json::json!({"id": key_id}),
            original_content_hash: "deadbeef".into(),
            scrub_signature_classical: "c2lnbmF0dXJl".into(),
            scrub_signature_pqc: None,
            scrub_key_id: key_id.into(),
            scrub_timestamp: "2026-05-01T00:00:00Z".parse().unwrap(),
            pqc_completed_at: None,
            persist_row_hash: String::new(),
            capability_roles: Vec::new(),
            attestation_evidence: None,
            consent_role: None,
            additional_scrubs: Vec::new(),
        }
    }

    fn fix_content_rating_attestation(
        att_id: &str,
        attester: &str,
        dimension: &str,
        sha_hex: &str,
    ) -> crate::federation::Attestation {
        let mut row = crate::federation::Attestation {
            attestation_id: att_id.into(),
            attesting_key_id: attester.into(),
            attested_key_id: attester.into(),
            attestation_type: crate::federation::types::attestation_type::SCORES.into(),
            weight: Some(1.0),
            asserted_at: "2026-05-01T00:00:00Z".parse().unwrap(),
            expires_at: None,
            attestation_envelope: serde_json::json!({
                "dimension": dimension,
                "score": 1.0,
                "confidence": 0.9,
                "evidence_refs": [sha_hex],
            }),
            original_content_hash: "abc123".into(),
            scrub_signature_classical: "c2ln".into(),
            scrub_signature_pqc: None,
            scrub_key_id: attester.into(),
            scrub_timestamp: "2026-05-01T00:00:00Z".parse().unwrap(),
            pqc_completed_at: None,
            persist_row_hash: String::new(),
            subject_key_ids: Vec::new(),
            withdraws_admission_rule: None,
            cohort_scope: "federation".to_string(),
            tier: crate::federation::types::attestation_tier::FEDERATION.to_string(),
            promoted_at: None,
            additional_scrubs: Vec::new(),
        };
        pg_resign(&mut row); // v9.0.0 — sign the envelope (CC 5.3.2.4.3.1)
        row
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn lookup_trusted_publisher_chain_returns_empty_for_unblessed_content_pg() {
        use crate::federation::FederationDirectory;
        use crate::store::backend::Backend;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // v30.3.0 (CIRISPersist#611) — the read door re-derives each publisher's
        // conferral against THIS NODE's trust root, so the backend must know who
        // it is. Without this the call returns the typed `NodeIdentityUnset`
        // refusal and the fixture fails on its wiring, not on its property.
        backend.set_node_key_id("tp-fixture-node-pg");
        // SHA that no trusted_publisher has rated — must yield empty.
        let sha_hex = format!(
            "e{}",
            uuid::Uuid::new_v4().as_simple().to_string().repeat(2)
        );
        // Truncate / pad to 64 chars hex.
        let sha_hex = sha_hex.chars().take(64).collect::<String>();
        let sha_hex = format!("{:0<64}", sha_hex);
        let chain = backend
            .lookup_trusted_publisher_chain(&sha_hex)
            .await
            .unwrap();
        assert!(chain.is_empty());
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn lookup_trusted_publisher_chain_returns_chain_when_trusted_publisher_attests_pg() {
        use crate::federation::FederationDirectory;
        use crate::store::backend::Backend;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // v30.3.0 (CIRISPersist#611) — the read door re-derives each publisher's
        // conferral against THIS NODE's trust root, so the backend must know who
        // it is. Without this the call returns the typed `NodeIdentityUnset`
        // refusal and the fixture fails on its wiring, not on its property.
        backend.set_node_key_id("tp-fixture-node-pg");
        // Unique-per-run publisher + att IDs so reruns against the
        // shared PG DB don't pollute (mirrors the existing
        // feedback_hundred_percent_green discipline).
        let nonce = uuid::Uuid::new_v4().simple().to_string();
        let publisher_key = format!("pub-{}", &nonce[..16]);
        // PG attestation_id column is UUID; use a fresh UUID here.
        let att_id = uuid::Uuid::new_v4().to_string();
        let sha_hex = format!("{:0<64}", nonce);
        let sha_hex = sha_hex.chars().take(64).collect::<String>();
        // Seed publisher key as trusted_publisher identity_type.
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: fix_trusted_publisher_key(
                    &publisher_key,
                    crate::federation::types::identity_type::TRUSTED_PUBLISHER,
                ),
            })
            .await
            .unwrap();
        // Seed a content_rating attestation referencing the SHA.
        backend
            .put_attestation(crate::federation::SignedAttestation {
                attestation: fix_content_rating_attestation(
                    &att_id,
                    &publisher_key,
                    "content_rating:mpa:pg13:v1",
                    &sha_hex,
                ),
            })
            .await
            .unwrap();
        // v30.3.0 (CIRISPersist#611) — holding the `trusted_publisher` identity
        // is no longer sufficient; the chain resolves a `trust:confers:v1` grant
        // of `infra:publish_rating` from a root this node trusts. Conferring it
        // keeps this fixture on its own property (the seeded row is found) rather
        // than turning it into a second copy of the #611 witness.
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            &backend,
            "tp-fixture-node-pg",
            &format!("tp-fixture-root-{}", &nonce[..8]),
            &publisher_key,
            crate::federation::types::delegation_scope::INFRA_PUBLISH_RATING,
        )
        .await;

        let chain = backend
            .lookup_trusted_publisher_chain(&sha_hex)
            .await
            .unwrap();
        assert!(
            chain.iter().any(|a| a.attestation_id == att_id),
            "chain must include the seeded attestation: {chain:?}"
        );
        for att in &chain {
            let dim = att
                .attestation_envelope
                .get("dimension")
                .and_then(|v| v.as_str())
                .unwrap_or("");
            assert!(
                dim.starts_with("content_rating:"),
                "every chain entry must be content_rating:* — got {dim:?}"
            );
        }
    }

    // ── #159 backend parity (FSD §10.4) ─────────────────────────────

    /// Build the scored event rows for one trace (THOUGHT_START +
    /// DMA_RESULTS + CONSCIENCE_RESULT + ACTION_RESULT + IDMA_RESULT),
    /// shared by the PG + SQLite halves of the parity test so both
    /// backends ingest byte-identical input.
    #[cfg(feature = "sqlite")]
    fn parity_scored_rows(
        trace_id: &str,
        domain: &str,
        ts: chrono::DateTime<chrono::Utc>,
        plausibility: f64,
        alignment: f64,
        conscience_pass: bool,
    ) -> Vec<TraceEventRow> {
        let mk = |event_type: ReasoningEventType,
                  off: i64,
                  payload: serde_json::Value|
         -> TraceEventRow {
            let payload = match payload {
                serde_json::Value::Object(m) => m.into_iter().collect(),
                _ => serde_json::Map::new(),
            };
            TraceEventRow {
                trace_id: trace_id.to_owned(),
                thought_id: format!("th-{trace_id}"),
                task_id: Some(format!("task-{trace_id}")),
                step_point: None,
                event_type,
                attempt_index: 0,
                ts: ts + chrono::Duration::milliseconds(off),
                agent_name: Some("agent-p".into()),
                agent_id_hash: "agenthash-p".into(),
                cognitive_state: Some("work".into()),
                // v19.2.0 (#494 ask 2) — Detailed: carries task_description
                // (reasoning text, detailed+ only); see the sqlite twin.
                trace_level: crate::schema::TraceLevel::Detailed,
                payload,
                cost_llm_calls: None,
                cost_tokens: None,
                cost_usd: None,
                signature: "AAAA".into(),
                signing_key_id: "test-key".into(),
                signature_verified: true,
                verification_source: crate::store::VerificationSource::Persist,
                schema_version: "2.7.0".into(),
                pii_scrubbed: false,
                original_content_hash: None,
                scrub_signature: None,
                scrub_key_id: None,
                scrub_timestamp: None,
                agent_role: None,
                agent_template: None,
                deployment_domain: Some(domain.to_owned()),
                deployment_type: Some("production".into()),
                deployment_region: Some("US".into()),
                deployment_trust_mode: None,
                cohort_scope: "federation".to_string(),
                cohort_target_id: None,
                signature_ml_dsa_65: None,
                pubkey_ml_dsa_65: None,
                pqc_key_id: None,
            }
        };
        vec![
            mk(
                ReasoningEventType::ThoughtStart,
                0,
                serde_json::json!({"thought_type": "standard", "thought_depth": 1}),
            ),
            mk(
                ReasoningEventType::DmaResults,
                10,
                serde_json::json!({
                    "csdma_plausibility_score": plausibility,
                    "dsdma_domain_alignment": alignment,
                }),
            ),
            mk(
                ReasoningEventType::ConscienceResult,
                20,
                serde_json::json!({
                    "conscience_passed": conscience_pass,
                    "entropy_passed": true,
                    "action_was_overridden": !conscience_pass,
                }),
            ),
            mk(
                ReasoningEventType::ActionResult,
                30,
                serde_json::json!({"action_executed": "SPEAK", "success": true}),
            ),
            mk(
                ReasoningEventType::IdmaResult,
                40,
                serde_json::json!({"idma_fragility_flag": false, "idma_phase": "flexibility"}),
            ),
        ]
    }

    /// §14 backend parity — the same `(filter, scope)` over identical
    /// ingested data on Postgres and SQLite returns the identical
    /// `RepositoryStatistics` struct, modulo `evaluated_at_unix_ms` (and
    /// `cache_hit`, which both run fresh here). Gated behind the
    /// `CIRIS_PERSIST_TEST_PG_URL` DSN — skipped when unset.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn parity_get_repository_statistics_pg_vs_sqlite() {
        use crate::read::ReadEngine;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };

        let ts = chrono::Utc.with_ymd_and_hms(2026, 5, 1, 12, 0, 0).unwrap();
        let rows1 = parity_scored_rows("p-1", "dom-A", ts, 0.8, 0.5, true);
        let rows2 = parity_scored_rows("p-2", "dom-A", ts, 0.6, 0.7, false);
        let rows3 = parity_scored_rows("p-3", "dom-B", ts, 0.9, 0.4, true);

        // Postgres half.
        let pg = PostgresBackend::connect(&dsn).await.unwrap();
        pg.run_migrations().await.unwrap();
        for r in [&rows1, &rows2, &rows3] {
            pg.insert_trace_events_batch(r).await.unwrap();
        }

        // SQLite half (fresh :memory:).
        let sq = crate::store::sqlite::SqliteBackend::open_in_memory()
            .await
            .unwrap();
        sq.run_migrations().await.unwrap();
        for r in [&rows1, &rows2, &rows3] {
            sq.insert_trace_events_batch(r).await.unwrap();
        }

        // Distinct window + agent filter so the PG cache key is unique to
        // this run (the cache is process-global; the SQLite half uses the
        // same key but a fresh :memory: corpus — equal answer).
        let filter = crate::ceg::RepositoryFilter {
            window: crate::ceg::TimeWindow::new(
                chrono::Utc.with_ymd_and_hms(2026, 4, 20, 0, 0, 0).unwrap(),
                chrono::Utc.with_ymd_and_hms(2026, 5, 20, 0, 0, 0).unwrap(),
            )
            .unwrap(),
            agent_id_hashes: vec!["agenthash-p".into()],
            deployment_domains: vec![],
            cohort_scope_in: vec![],
            task_classes: vec![],
            fragility_only: false,
        };

        let mut pg_stats = pg
            .get_repository_statistics(filter.clone(), crate::scope::CallerScope::Unauthenticated)
            .await
            .unwrap();
        let mut sq_stats = sq
            .get_repository_statistics(filter, crate::scope::CallerScope::Unauthenticated)
            .await
            .unwrap();

        // Normalize the per-run-variable fields before comparing.
        pg_stats.evaluated_at_unix_ms = 0;
        sq_stats.evaluated_at_unix_ms = 0;
        pg_stats.cache_hit = false;
        sq_stats.cache_hit = false;

        assert_eq!(
            pg_stats, sq_stats,
            "PG and SQLite must produce the identical RepositoryStatistics \
             modulo evaluated_at_unix_ms"
        );
        // Spot-check the shared answer is non-trivial.
        assert_eq!(pg_stats.sample_count, 3);
        assert_eq!(pg_stats.by_domain.len(), 2);
    }

    // #135 + part of #150 — list_attestations_for on Postgres: by-target
    // filtering, newest-first, cursor paging, and the §4.3 scope gate.
    // Gated behind CIRIS_PERSIST_TEST_PG_URL; skipped when unset.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn parity_list_attestations_for_scope_variants() {
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        use crate::federation::FederationDirectory;
        use crate::read::ReadEngine;
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        // Unique keys per run so the shared test DB stays parallel-safe.
        let suffix = uuid_like();
        let emit_a = format!("emit-a-{suffix}");
        let tgt_1 = format!("tgt-1-{suffix}");
        let tgt_2 = format!("tgt-2-{suffix}");
        for (id, iref) in [
            (&emit_a, "primitive-a"),
            (&tgt_1, "primitive-t1"),
            (&tgt_2, "primitive-t2"),
        ] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(
                        id,
                        iref,
                        crate::federation::types::identity_type::AGENT,
                    ),
                })
                .await
                .unwrap();
        }

        // mk: a scored attestation targeting `attested` with an explicit
        // asserted_at + cohort_scope.
        let mk = |attested: &str, at: chrono::DateTime<chrono::Utc>, scope: &str| {
            let mut a = pg_scores_attestation(&emit_a, attested, &emit_a, "identity_binding:v1");
            a.asserted_at = at;
            a.cohort_scope = scope.to_string();
            crate::federation::tier_ingest::test_support::reseal(&mut a);
            crate::federation::SignedAttestation { attestation: a }
        };
        let t = |d: u32| chrono::Utc.with_ymd_and_hms(2026, 5, d, 0, 0, 0).unwrap();

        // tgt-1: three federation rows + one self row; tgt-2: one row.
        backend
            .put_attestation(mk(&tgt_1, t(1), "federation"))
            .await
            .unwrap();
        backend
            .put_attestation(mk(&tgt_1, t(2), "federation"))
            .await
            .unwrap();
        backend
            .put_attestation(mk(&tgt_1, t(3), "federation"))
            .await
            .unwrap();
        backend
            .put_attestation(mk(&tgt_1, t(4), "self"))
            .await
            .unwrap();
        backend
            .put_attestation(mk(&tgt_2, t(5), "federation"))
            .await
            .unwrap();

        // Unauthenticated: broad-tier only, newest-first, no other target.
        // UFCS — `list_attestations_for` exists on both ReadEngine (this,
        // 4-arg) and the legacy FederationDirectory (1-arg) in scope.
        let page = ReadEngine::list_attestations_for(
            &backend,
            &tgt_1,
            None,
            100,
            crate::scope::CallerScope::Unauthenticated,
        )
        .await
        .unwrap();
        assert_eq!(page.items.len(), 3, "broad-tier rows only (self hidden)");
        assert!(page.items.iter().all(|a| a.attested_key_id == tgt_1));
        // Newest-first by asserted_at.
        assert!(page.items[0].asserted_at >= page.items[1].asserted_at);
        assert!(page.items[1].asserted_at >= page.items[2].asserted_at);
        assert!(page.items.iter().all(|a| a.cohort_scope == "federation"));

        // Cursor paging: limit=2 then continue.
        let p1 = ReadEngine::list_attestations_for(
            &backend,
            &tgt_1,
            None,
            2,
            crate::scope::CallerScope::Unauthenticated,
        )
        .await
        .unwrap();
        assert_eq!(p1.items.len(), 2);
        assert!(p1.next_cursor.is_some());
        let p2 = ReadEngine::list_attestations_for(
            &backend,
            &tgt_1,
            p1.next_cursor,
            2,
            crate::scope::CallerScope::Unauthenticated,
        )
        .await
        .unwrap();
        assert_eq!(p2.items.len(), 1);
        assert!(p2.next_cursor.is_none());

        // Authenticated, identity == tgt_1: the self row resolves.
        let auth_self = crate::scope::CallerScope::Authenticated {
            admission: crate::scope::admission::CallerAdmission::for_test(&tgt_1, &tgt_1, [], []),
        };
        let page = ReadEngine::list_attestations_for(&backend, &tgt_1, None, 100, auth_self)
            .await
            .unwrap();
        assert_eq!(page.items.len(), 4, "self row visible to its own subject");
        assert_eq!(
            page.items[0].cohort_scope, "self",
            "self row sorts first by clock"
        );

        // Authenticated, different identity: self row hidden again.
        let auth_other = crate::scope::CallerScope::Authenticated {
            admission: crate::scope::admission::CallerAdmission::for_test(
                "someone-else",
                "someone-else",
                [],
                [],
            ),
        };
        let page = ReadEngine::list_attestations_for(&backend, &tgt_1, None, 100, auth_other)
            .await
            .unwrap();
        assert_eq!(page.items.len(), 3, "self row hidden from non-owner reader");
    }

    // ─── Cut C4 — delivery-receipt JOIN gate on Postgres (CEG §10.5.4) ─
    //
    // PG-dialect parity for the SQLite delivery_receipts tests: exercises
    // V065's DDL, the BYTEA `root_hash` JOIN comparison, the BIGINT
    // bindings, and the in-transaction gate. Real hybrid signatures.

    /// Build a real hybrid-signed receipt (PQC signs
    /// `canonical || classical_sig`). Returns the receipt + the
    /// subscriber's (ed25519, ml_dsa_65) base64 pubkeys.
    async fn pg_signed_receipt(
        stream_id: &str,
        subscriber_key_id: &str,
        epoch: u64,
        k: u64,
        chunk_root: [u8; 32],
        ed_seed: u8,
        mldsa_seed: u8,
    ) -> (
        crate::federation::stream_receipt::DeliveryReceipt,
        String,
        String,
    ) {
        use base64::engine::general_purpose::STANDARD as B64;
        use base64::Engine as _;
        use ciris_keyring::PqcSigner;
        use ed25519_dalek::Signer as _;

        let canonical = crate::federation::stream_receipt::receipt_signing_bytes(
            subscriber_key_id,
            stream_id,
            epoch,
            &chunk_root,
            k,
        );
        let sk = ed25519_dalek::SigningKey::from_bytes(&[ed_seed; 32]);
        let ed_sig_bytes = sk.sign(&canonical).to_bytes();
        let ed_pk = sk.verifying_key().to_bytes();

        let mut bound = canonical.clone();
        bound.extend_from_slice(&ed_sig_bytes);
        let mldsa =
            ciris_keyring::MlDsa65SoftwareSigner::from_seed_bytes(&[mldsa_seed; 32], "c4-pg-test")
                .expect("ml-dsa seed");
        let pqc_sig = mldsa.sign(&bound).await.expect("ml-dsa sign");
        let pqc_pk = mldsa.public_key().await.expect("ml-dsa pk");

        let receipt = crate::federation::stream_receipt::DeliveryReceipt {
            stream_id: stream_id.to_owned(),
            subscriber_key_id: subscriber_key_id.to_owned(),
            epoch,
            k,
            chunk_root,
            signature: ciris_crypto::HybridSignature {
                crypto_kind: ciris_crypto::CRYPTO_KIND_CIRIS_V1,
                classical: ciris_crypto::TaggedClassicalSignature {
                    algorithm: ciris_crypto::ClassicalAlgorithm::Ed25519,
                    signature: ed_sig_bytes.to_vec(),
                    public_key: ed_pk.to_vec(),
                },
                pqc: ciris_crypto::TaggedPqcSignature {
                    algorithm: ciris_crypto::PqcAlgorithm::MlDsa65,
                    signature: pqc_sig,
                    public_key: pqc_pk.clone(),
                },
                mode: ciris_crypto::SignatureMode::HybridRequired,
            },
        };
        (receipt, B64.encode(ed_pk), B64.encode(&pqc_pk))
    }

    async fn pg_seed_subscriber_key(
        backend: &PostgresBackend,
        key_id: &str,
        ed_b64: &str,
        mldsa_b64: &str,
    ) {
        let client = backend.get_client().await.unwrap();
        client
            .execute(
                "INSERT INTO cirislens.federation_keys (\
                    key_id, pubkey_ed25519_base64, pubkey_ml_dsa_65_base64, algorithm, \
                    identity_type, identity_ref, valid_from, registration_envelope, \
                    original_content_hash, scrub_signature_classical, scrub_key_id, \
                    scrub_timestamp, persist_row_hash\
                 ) VALUES ($1, $2, $3, 'hybrid', 'agent', $1, \
                          '2026-01-01T00:00:00Z', '{}', '\\x00', '', $1, \
                          '2026-01-01T00:00:00Z', '0') \
                 ON CONFLICT (key_id) DO NOTHING",
                &[&key_id, &ed_b64, &mldsa_b64],
            )
            .await
            .expect("seed federation_keys");
    }

    async fn pg_seed_published_sth(
        backend: &PostgresBackend,
        stream_id: &str,
        tree_size: i64,
        root_hash: [u8; 32],
    ) {
        let client = backend.get_client().await.unwrap();
        let root_vec = root_hash.to_vec();
        client
            .execute(
                "INSERT INTO cirislens.federation_stream_sth (\
                    stream_id, tree_size, epoch, root_hash, signed_at, \
                    producer_key_id, signature_blob, witness_signatures\
                 ) VALUES ($1, $2, 0, $3, '2026-01-01T00:00:00Z', \
                          'producer-key', '\\x00', '[]'::jsonb) \
                 ON CONFLICT (stream_id, tree_size) DO NOTHING",
                &[&stream_id, &tree_size, &root_vec],
            )
            .await
            .expect("seed federation_stream_sth");
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_delivery_receipt_join_gate() {
        use crate::federation::BlobStorage;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();

        let suffix = uuid_like();
        let stream_id = format!("stream-c4-pg-{suffix}");
        let sub = format!("sub-pg-{suffix}");
        let root = [0x11u8; 32];
        let phantom = [0x22u8; 32];

        let (receipt, ed_b64, mldsa_b64) =
            pg_signed_receipt(&stream_id, &sub, 0, 2, root, 0x10, 0x20).await;
        pg_seed_subscriber_key(&backend, &sub, &ed_b64, &mldsa_b64).await;
        pg_seed_published_sth(&backend, &stream_id, 3, root).await;

        // Positive: signed receipt against a published root (tree_size >= k).
        backend
            .put_delivery_receipt(receipt.clone())
            .await
            .expect("receipt against published root accepted");
        let listed = backend
            .list_delivery_receipts_for(&stream_id, 10)
            .await
            .unwrap();
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].chunk_root, root);

        // Idempotent re-PUT.
        backend
            .put_delivery_receipt(receipt)
            .await
            .expect("idempotent re-PUT");
        assert_eq!(
            backend
                .list_delivery_receipts_for(&stream_id, 10)
                .await
                .unwrap()
                .len(),
            1
        );

        // Negative — phantom root (never published) is rejected by the JOIN.
        let (phantom_receipt, _e, _m) =
            pg_signed_receipt(&stream_id, &sub, 0, 7, phantom, 0x10, 0x20).await;
        let err = backend
            .put_delivery_receipt(phantom_receipt)
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                if m.contains("unpublished root")),
            "PG phantom root must be rejected, got: {err:?}"
        );

        // Negative — subscriber equivocation: a different root at the same
        // (stream, subscriber, k). Publish root_b too so the JOIN passes
        // and the equivocation check is what rejects.
        let root_b = [0x33u8; 32];
        pg_seed_published_sth(&backend, &stream_id, 4, root_b).await;
        let (equiv, _e, _m) = pg_signed_receipt(&stream_id, &sub, 0, 2, root_b, 0x10, 0x20).await;
        let err = backend.put_delivery_receipt(equiv).await.unwrap_err();
        assert!(
            matches!(err, crate::federation::BlobError::InvalidArgument(ref m)
                if m.contains("equivocation")),
            "PG subscriber equivocation must be rejected, got: {err:?}"
        );
    }

    // ── Cut #171 phase 1: local-tier write on live Postgres ──

    fn pg_local_input(
        attesting: &str,
        attestation_type: &str,
        dimension: &str,
        subjects: Vec<String>,
    ) -> crate::federation::types::LocalAttestationInput {
        crate::federation::types::LocalAttestationInput {
            attestation_id: None,
            attesting_key_id: attesting.into(),
            attested_key_id: None,
            attestation_type: attestation_type.into(),
            weight: Some(1.0),
            expires_at: None,
            attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({
                    "id": "x", "dimension": dimension, "score": 1.0, "confidence": 0.9,
                }),
            )
            .unwrap(),
            subject_key_ids: subjects,
            cohort_scope: crate::federation::types::cohort_scope::SELF.to_string(),
            scrub_signature_classical: None,
            scrub_signature_pqc: None,
        }
    }

    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_local_attestation_upsert_insert_and_gates() {
        use crate::federation::types::attestation_type::{SCORES, WITHDRAWS};
        use crate::federation::FederationDirectory;
        use crate::store::backend::Backend;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let occ = format!("occ-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &occ,
                    "registry",
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();

        // Upsert twice on the same dimension → one local row (replace).
        backend
            .attestation_upsert_local(pg_local_input(&occ, SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        backend
            .attestation_upsert_local(pg_local_input(&occ, SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        // Read local rows directly — the FederationDirectory trust-read
        // excludes tier='local' (AV-59).
        let count_local = |occ: &str| {
            let occ = occ.to_string();
            let backend = &backend;
            async move {
                let client = backend.get_client().await.unwrap();
                let row = client
                    .query_one(
                        "SELECT COUNT(*)::int8 FROM cirislens.federation_attestations \
                          WHERE attesting_key_id = $1 AND tier = 'local'",
                        &[&occ],
                    )
                    .await
                    .unwrap();
                row.try_get::<_, i64>(0).unwrap()
            }
        };
        assert_eq!(
            count_local(&occ).await,
            1,
            "PG upsert replaces on (occurrence, dimension)"
        );
        // AV-59: federation trust-read does not surface local rows.
        let trust = crate::federation::FederationDirectory::list_attestations_for(&backend, &occ)
            .await
            .unwrap();
        assert!(trust.is_empty(), "local rows must not leak (AV-59)");

        // Insert appends a distinct row.
        backend
            .attestation_insert_local(pg_local_input(&occ, SCORES, "identity_binding:v1", vec![]))
            .await
            .unwrap();
        assert_eq!(
            count_local(&occ).await,
            2,
            "insert appends (1 upsert-survivor + 1 append)"
        );

        // Gate: capacity:* ineligible for local.
        let err = backend
            .attestation_upsert_local(pg_local_input(&occ, SCORES, "capacity:core:v1", vec![]))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("capacity")),
            "got: {err:?}"
        );

        // Gate: subject-side revocation ineligible for local.
        let err = backend
            .attestation_upsert_local(pg_local_input(
                &occ,
                WITHDRAWS,
                "consent:state:revoked:v1",
                vec![occ.clone()],
            ))
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("revocation")),
            "got: {err:?}"
        );
    }

    /// v4.5 attestation_query filters on live PG — exercises the
    /// PG-specific SQL: `->>'dimension' LIKE`, `weight::float8 >=`, and
    /// the `subject_key_ids ? $n` JSONB-array-membership operator.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_attestation_query_filters() {
        use crate::ceg::ReadEngine;
        use crate::federation::FederationDirectory;
        use crate::read::AttestationFilter;
        use crate::store::backend::Backend;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let occ = format!("occ-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &occ,
                    "registry",
                    crate::federation::types::identity_type::STEWARD,
                ),
            })
            .await
            .unwrap();

        // v30.6.0 (CIRISPersist#622) — `String`, not `uuid::Uuid`: the column is
        // TEXT since V121 and the driver rejects a Uuid against it with
        // `WrongType { postgres: Text, rust: "uuid::Uuid" }`.
        let seed = |id: String,
                    dim: &'static str,
                    weight: f64,
                    subjects: serde_json::Value,
                    expires: Option<chrono::DateTime<chrono::Utc>>| {
            let occ = occ.clone();
            let backend = &backend;
            async move {
                let client = backend.get_client().await.unwrap();
                // v31.0.0 (#644) — attestation_envelope is TEXT since V122, so
                // this raw-SQL fixture binds the serialized form like the real
                // write path does.
                let env = serde_json::to_string(
                    &serde_json::json!({"id": id.to_string(), "dimension": dim, "score": 1.0}),
                )
                .unwrap();
                let empty: Vec<u8> = Vec::new();
                let asserted = "2026-05-01T00:00:00Z"
                    .parse::<chrono::DateTime<chrono::Utc>>()
                    .unwrap();
                client.execute(
                    "INSERT INTO cirislens.federation_attestations (\
                        attestation_id, attesting_key_id, attested_key_id, attestation_type, \
                        weight, asserted_at, expires_at, attestation_envelope, original_content_hash, \
                        scrub_signature_classical, scrub_signature_pqc, scrub_key_id, scrub_timestamp, \
                        pqc_completed_at, persist_row_hash, subject_key_ids, withdraws_admission_rule, \
                        cohort_scope, tier, promoted_at, additional_scrubs\
                     ) VALUES ($1, $2, $2, 'scores', $3::float8::numeric, $4, $5, $6, $7, \
                              'sig', NULL, $2, $4, NULL, '0', $8, NULL, 'federation', 'federation', NULL, '[]')",
                    &[&id, &occ, &weight, &asserted, &expires, &env, &empty, &subjects],
                ).await.unwrap();
            }
        };
        let (a, b, c, d) = (
            uuid::Uuid::new_v4(),
            uuid::Uuid::new_v4(),
            uuid::Uuid::new_v4(),
            uuid::Uuid::new_v4(),
        );
        seed(
            a.to_string(),
            "config:filter:v1",
            0.9,
            serde_json::json!([]),
            None,
        )
        .await;
        seed(
            b.to_string(),
            "config:other:v1",
            0.4,
            serde_json::json!([]),
            None,
        )
        .await;
        seed(
            c.to_string(),
            "goal:x:v1",
            0.95,
            serde_json::json!(["subj-1"]),
            "2030-01-01T00:00:00Z".parse().ok(),
        )
        .await;
        seed(
            d.to_string(),
            "goal:y:v1",
            0.7,
            serde_json::json!([]),
            "2026-05-02T00:00:00Z".parse().ok(),
        )
        .await;

        let q = |mut f: AttestationFilter| {
            let backend = &backend;
            let occ = occ.clone();
            async move {
                // Scope to THIS run's rows (shared PG DB holds other tests').
                f.attesting_key_id = Some(occ);
                let mut ids: Vec<String> = backend
                    .list_attestations(f, None, 100, crate::scope::CallerScope::Unauthenticated)
                    .await
                    .unwrap()
                    .items
                    .into_iter()
                    .map(|a| a.attestation_id)
                    .collect();
                ids.sort();
                ids
            }
        };
        let mut want_config = vec![a.to_string(), b.to_string()];
        want_config.sort();
        assert_eq!(
            q(AttestationFilter {
                dimension_prefixes: vec!["config:".into()],
                ..Default::default()
            })
            .await,
            want_config
        );
        let mut want_floor = vec![a.to_string(), c.to_string()];
        want_floor.sort();
        assert_eq!(
            q(AttestationFilter {
                confidence_floor: Some(0.8),
                ..Default::default()
            })
            .await,
            want_floor
        );
        assert_eq!(
            q(AttestationFilter {
                subject_key_id: Some("subj-1".into()),
                ..Default::default()
            })
            .await,
            vec![c.to_string()]
        );
        let at = "2026-05-03T00:00:00Z".parse().unwrap();
        let mut want_valid = vec![a.to_string(), b.to_string(), c.to_string()]; // d expired
        want_valid.sort();
        assert_eq!(
            q(AttestationFilter {
                valid_at: Some(at),
                ..Default::default()
            })
            .await,
            want_valid
        );
        // v17.5.2 (#461) — EXACT dimension match parity (was a silent no-op:
        // pre-fix returned all 4). `config:filter:v1` matches only `a`, not `b`
        // (`config:other:v1`).
        assert_eq!(
            q(AttestationFilter {
                dimension_exact: Some("config:filter:v1".into()),
                ..Default::default()
            })
            .await,
            vec![a.to_string()]
        );
    }

    /// v4.7.0 (CIRISPersist#177) — live-PG round-trip for the typed
    /// key-registration outcome. Mirrors the SQLite twin: new key →
    /// `Registered`; same key+pubkey → `AlreadyRegistered`; same key,
    /// different pubkey → `RotationCollision` (fingerprint of the stored
    /// key) and the stored row is left intact. Unique `key_id` per run
    /// for the shared DB.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_register_accord_public_key_classifies_outcomes() {
        use crate::store::{accord_key_fingerprint, KeyRegistrationOutcome};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let key_id = format!("agent-k-{}", uuid_like());

        let reg = backend
            .register_accord_public_key(&key_id, "pubA", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        assert_eq!(reg, KeyRegistrationOutcome::Registered);

        let again = backend
            .register_accord_public_key(&key_id, "pubA", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        assert_eq!(again, KeyRegistrationOutcome::AlreadyRegistered);

        let collision = backend
            .register_accord_public_key(&key_id, "pubB", "Ed25519", None, None, Some("boot"))
            .await
            .unwrap();
        match collision {
            KeyRegistrationOutcome::RotationCollision {
                existing_key_fingerprint,
            } => assert_eq!(existing_key_fingerprint, accord_key_fingerprint("pubA")),
            other => panic!("expected RotationCollision, got {other:?}"),
        }
        // Non-destructive: the stored pubkey is unchanged.
        let client = backend.get_client().await.unwrap();
        let stored: String = client
            .query_one(
                "SELECT public_key_base64 FROM cirislens.accord_public_keys WHERE key_id = $1",
                &[&key_id],
            )
            .await
            .unwrap()
            .try_get::<_, String>(0)
            .unwrap();
        assert_eq!(stored, "pubA", "rotation collision must not overwrite");
    }

    /// v4.8.0 (CIRISPersist#161) — live-PG round-trip for the membership
    /// revocation tables: put → list_*_revocations_for (exercises the
    /// JSONB `witness_set` encode/decode) → active-state filtering with a
    /// past- vs future-effective revocation. Unique key_ids per run.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_membership_revocation_round_trip_and_active_filtering() {
        use crate::federation::{
            FederationDirectory, IdentityOccurrence, IdentityOccurrenceRevocation,
        };
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let root = format!("root-{}", uuid_like());
        let phone = format!("phone-{}", uuid_like());
        let laptop = format!("laptop-{}", uuid_like());
        for (k, t) in [
            (&root, crate::federation::types::identity_type::STEWARD),
            (&phone, crate::federation::types::identity_type::PRIMITIVE),
            (&laptop, crate::federation::types::identity_type::PRIMITIVE),
        ] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(k, k, t),
                })
                .await
                .unwrap();
        }
        let occ = |o: &str| IdentityOccurrence {
            identity_key_id: root.clone(),
            occurrence_key_id: o.to_string(),
            device_class: crate::federation::types::device_class::PHONE.into(),
            hardware_attestation: None,
            asserted_at: "2026-06-01T00:00:00Z".parse().unwrap(),
            valid_until: None,
            encryption_pubkeys: None,
            transport_binding: None,
            persist_row_hash: String::new(),
        };
        backend
            .put_identity_occurrence_local(occ(&phone))
            .await
            .unwrap();
        backend
            .put_identity_occurrence_local(occ(&laptop))
            .await
            .unwrap();

        // Past-effective revocation of phone (trusted-local, #421).
        backend
            .put_identity_occurrence_revocation_local(IdentityOccurrenceRevocation {
                identity_key_id: root.clone(),
                occurrence_key_id: phone.clone(),
                revoked_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                effective_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                reason: Some("lost".into()),
                witness_set: vec![root.clone(), laptop.clone()],
                persist_row_hash: String::new(),
            })
            .await
            .unwrap();

        let revs = backend
            .list_identity_occurrence_revocations_for(&root)
            .await
            .unwrap();
        assert_eq!(revs.len(), 1);
        assert_eq!(revs[0].occurrence_key_id, phone);
        assert_eq!(
            revs[0].witness_set,
            vec![root.clone(), laptop.clone()],
            "JSONB witness_set round-trips in order"
        );
        assert!(!revs[0].persist_row_hash.is_empty());

        let active = backend
            .list_identity_occurrences_active(&root)
            .await
            .unwrap();
        let ids: Vec<_> = active.iter().map(|o| o.occurrence_key_id.clone()).collect();
        assert_eq!(ids, vec![laptop.clone()], "revoked phone excluded on PG");

        // FK violation surfaces as InvalidArgument (local path, same table).
        let err = backend
            .put_identity_occurrence_revocation_local(IdentityOccurrenceRevocation {
                identity_key_id: root.clone(),
                occurrence_key_id: format!("ghost-{}", uuid_like()),
                revoked_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                effective_at: "2026-06-05T00:00:00Z".parse().unwrap(),
                reason: None,
                witness_set: vec![],
                persist_row_hash: String::new(),
            })
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("FK")),
            "got: {err:?}"
        );
    }

    /// v4.10.0 (CIRISPersist#154) — live-PG location_proof round-trip:
    /// CIRISPersist#210 — SharedInstanceLease lifecycle on live PG: the
    /// `INSERT … ON CONFLICT … WHERE stale` atomic election, live-owner
    /// rejection, heartbeat, stale-steal (version bump + RETURNING),
    /// demotion detection, ownership-checked release.
    /// CIRISPersist#146 Ask 3 — consent-SLA watcher on live PG: exercises
    /// the `list_consent_revocations` query (JSONB `dimension` LIKE +
    /// `withdraws_admission_rule` filter) end-to-end through
    /// `run_consent_sla_watch` — breach past deadline, then suppressed by
    /// `consent:deletion_complete`.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_consent_sla_watch_emits_breach_then_suppresses() {
        use crate::federation::{hard_case::kind, FederationDirectory, HardCaseFilter};
        use std::time::Duration;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let s = uuid_like();
        let producer = format!("pg-prod-{s}");
        let subject = format!("pg-subj-{s}");
        let target = format!("pg-tgt-{s}");
        for (k, ty) in [
            (
                &producer,
                crate::federation::types::identity_type::PRIMITIVE,
            ),
            (&subject, crate::federation::types::identity_type::PRIMITIVE),
            (&target, crate::federation::types::identity_type::PRIMITIVE),
        ] {
            backend
                .put_public_key(crate::federation::SignedKeyRecord {
                    record: pg_admission_key(k, k, ty),
                })
                .await
                .unwrap();
        }
        let now = chrono::Utc::now();
        let put = |attester: &str, dim: &str, at: chrono::DateTime<chrono::Utc>| {
            let mut att = pg_scores_attestation(attester, &target, attester, dim);
            // v31.0.0 (CIRISPersist#598) — moving `asserted_at` by hand is
            // exactly what the defect permitted; it is now only expressible
            // when the SIGNED envelope says the same instant, so stamp it and
            // re-sign.
            let at = crate::federation::admission::truncate_to_substrate_resolution(at);
            att.asserted_at = at;
            att.attestation_envelope[crate::federation::envelope::paths::ASSERTED_AT] =
                serde_json::Value::String(at.to_rfc3339());
            pg_resign(&mut att);
            crate::federation::SignedAttestation { attestation: att }
        };
        backend
            .put_attestation(put(
                &producer,
                "consent:deletion_sla:1:v1",
                now - chrono::Duration::days(5),
            ))
            .await
            .unwrap();
        backend
            .put_attestation(put(
                &subject,
                "consent:state:revoked:v1",
                now - chrono::Duration::days(2),
            ))
            .await
            .unwrap();

        // Counts are global over the shared serial DB, so assert via THIS
        // target's rows, not the watcher's global counters.
        let window = Duration::from_secs(86_400);
        let r1 = backend.run_consent_sla_watch(now, window).await.unwrap();
        assert!(r1.revocations_scanned >= 1, "scan found our revocation");
        let mine = |events: Vec<crate::federation::HardCaseEvent>| {
            events
                .into_iter()
                .filter(|e| e.target_key_id.as_deref() == Some(target.as_str()))
                .collect::<Vec<_>>()
        };
        let breaches = mine(
            backend
                .list_hard_case_events(HardCaseFilter {
                    kind: Some(kind::CONSENT_SLA_BREACH.into()),
                    since: None,
                })
                .await
                .unwrap(),
        );
        assert_eq!(
            breaches.len(),
            1,
            "PG list_consent_revocations → breach for our target"
        );
        assert_eq!(
            breaches[0].subject_key_id.as_deref(),
            Some(subject.as_str())
        );
        assert_eq!(breaches[0].detail["sla_days"], 1);

        // Re-scan is row-idempotent for our target (no duplicate).
        backend.run_consent_sla_watch(now, window).await.unwrap();
        let after = mine(
            backend
                .list_hard_case_events(HardCaseFilter {
                    kind: Some(kind::CONSENT_SLA_BREACH.into()),
                    since: None,
                })
                .await
                .unwrap(),
        );
        assert_eq!(
            after.len(),
            1,
            "no duplicate breach row for our target on re-scan"
        );
    }

    /// CIRISPersist#146 Ask 3 — hard_case:* emission on live PG: JSONB
    /// `detail` round-trip, kind/since filters, and idempotency on the
    /// deterministic `event_id` (ON CONFLICT DO NOTHING).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_hard_case_event_record_list_and_idempotent() {
        use crate::federation::{
            hard_case::kind, FederationDirectory, HardCaseEvent, HardCaseFilter,
        };
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // Unique ids so serial reuse of the shared DB doesn't collide.
        let suffix = uuid_like();
        let id1 = format!("hc-breach-{suffix}");
        let id2 = format!("hc-overdue-{suffix}");
        let ev = |id: &str, k: &str| HardCaseEvent {
            event_id: id.into(),
            kind: k.into(),
            target_key_id: Some(format!("target-{suffix}")),
            subject_key_id: Some(format!("subject-{suffix}")),
            detail: serde_json::json!({ "sla_days": 30, "suffix": suffix }),
            emitted_at: "2026-06-13T00:00:00Z".parse().unwrap(),
        };
        backend
            .record_hard_case(ev(&id1, kind::CONSENT_SLA_BREACH))
            .await
            .unwrap();
        backend
            .record_hard_case(ev(&id2, kind::CONSENT_REVOCATION_PROMOTION_OVERDUE))
            .await
            .unwrap();
        // Re-record id1 — idempotent (ON CONFLICT DO NOTHING).
        backend
            .record_hard_case(ev(&id1, kind::CONSENT_SLA_BREACH))
            .await
            .unwrap();

        // Filter to this test's breach kind + this run's window; assert the
        // JSONB detail round-tripped and idempotency held.
        let breaches = backend
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::CONSENT_SLA_BREACH.into()),
                since: Some("2026-06-13T00:00:00Z".parse().unwrap()),
            })
            .await
            .unwrap();
        let mine: Vec<_> = breaches.into_iter().filter(|e| e.event_id == id1).collect();
        assert_eq!(mine.len(), 1, "idempotent on event_id — id1 not duplicated");
        assert_eq!(mine[0].detail["sla_days"], 30);
        assert_eq!(mine[0].detail["suffix"], suffix);
        assert_eq!(
            mine[0].target_key_id.as_deref(),
            Some(format!("target-{suffix}").as_str())
        );
    }

    /// `INSERT … ON CONFLICT … WHERE stale` atomic election, live-owner
    /// rejection, heartbeat, stale-steal (version bump + RETURNING),
    /// demotion detection, ownership-checked release.
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_shared_instance_lease_election_lifecycle() {
        use crate::federation::FederationDirectory;
        use std::time::Duration;
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        // Unique instance name so serial reuse of the shared test DB
        // doesn't collide with a prior run's row.
        let name = format!("reticulum:{}", uuid_like());

        // 1. Acquire on an empty slot → win, version 1.
        let lease = backend
            .try_acquire_shared_instance(&name, 1001, "hostA", None)
            .await
            .unwrap()
            .expect("first acquire wins");
        assert_eq!((lease.owner_pid, lease.lease_version), (1001, 1));

        // 2. Live contender → loses.
        assert!(
            backend
                .try_acquire_shared_instance(&name, 2002, "hostB", None)
                .await
                .unwrap()
                .is_none(),
            "a live owner blocks a second acquirer"
        );

        // 3. lookup reports the owner.
        let found = backend
            .lookup_shared_instance_lease(&name)
            .await
            .unwrap()
            .unwrap();
        assert_eq!((found.owner_pid, found.lease_version), (1001, 1));

        // 4. Owner heartbeats → still owner.
        let beat = backend
            .heartbeat_shared_instance(&lease)
            .await
            .unwrap()
            .expect("owner still holds");
        assert_eq!((beat.owner_pid, beat.lease_version), (1001, 1));

        // 5. Age the heartbeat, then steal with a small stale window.
        tokio::time::sleep(Duration::from_millis(40)).await;
        let stolen = backend
            .try_acquire_shared_instance(&name, 2002, "hostB", Some(Duration::from_millis(10)))
            .await
            .unwrap()
            .expect("a stale owner is stealable");
        assert_eq!((stolen.owner_pid, stolen.lease_version), (2002, 2));

        // 6. Demoted original owner's heartbeat → None.
        assert!(
            backend
                .heartbeat_shared_instance(&beat)
                .await
                .unwrap()
                .is_none(),
            "original owner learns its lease was stolen"
        );

        // 7. Release by the current owner → gone; next acquire fresh v1.
        backend
            .release_shared_instance_lease(&stolen)
            .await
            .unwrap();
        assert!(backend
            .lookup_shared_instance_lease(&name)
            .await
            .unwrap()
            .is_none());
        let fresh = backend
            .try_acquire_shared_instance(&name, 3003, "hostC", None)
            .await
            .unwrap()
            .expect("acquire after release wins");
        assert_eq!(fresh.lease_version, 1, "released slot → fresh lease at v1");

        // 8. Stale release must not evict the live owner.
        backend
            .release_shared_instance_lease(&stolen)
            .await
            .unwrap();
        assert!(
            backend
                .lookup_shared_instance_lease(&name)
                .await
                .unwrap()
                .is_some(),
            "stale release never deletes the current lease"
        );
    }

    /// SMALLINT `cell_resolution` + BYTEA `attestation_evidence` binding,
    /// valid res-7 admits, over-precise res-9 refused (§0.8.1).
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn pg_location_proof_round_trip_and_rough_only_gate() {
        use crate::federation::{FederationDirectory, LocationProof};
        let Some(dsn) = pg_dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let backend = PostgresBackend::connect(&dsn).await.unwrap();
        backend.run_migrations().await.unwrap();
        let subj = format!("subj-{}", uuid_like());
        backend
            .put_public_key(crate::federation::SignedKeyRecord {
                record: pg_admission_key(
                    &subj,
                    &subj,
                    crate::federation::types::identity_type::PRIMITIVE,
                ),
            })
            .await
            .unwrap();

        let ll = h3o::LatLng::new(37.0, -122.0).unwrap();
        let cell7 = ll.to_cell(h3o::Resolution::Seven).to_string();
        backend
            .put_location_proof(
                crate::federation::tier_ingest::test_support::sign_location_proof(
                    &subj,
                    LocationProof {
                        subject_key_id: subj.clone(),
                        cell_id: cell7.clone(),
                        cell_resolution: 7,
                        asserted_at: "2026-06-09T00:00:00Z".parse().unwrap(),
                        valid_until: None,
                        attestation_evidence: Some(vec![0xDEu8, 0xAD, 0xBE, 0xEF]),
                        withdrawn_at: None,
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap();
        let rows = backend.list_location_proofs_for(&subj).await.unwrap();
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].cell_id, cell7);
        assert_eq!(rows[0].cell_resolution, 7);
        assert_eq!(
            rows[0].attestation_evidence.as_deref(),
            Some(&[0xDEu8, 0xAD, 0xBE, 0xEF][..])
        );

        let cell9 = ll.to_cell(h3o::Resolution::Nine).to_string();
        let err = backend
            .put_location_proof(
                crate::federation::tier_ingest::test_support::sign_location_proof(
                    &subj,
                    LocationProof {
                        subject_key_id: subj.clone(),
                        cell_id: cell9,
                        cell_resolution: 9,
                        asserted_at: "2026-06-09T01:00:00Z".parse().unwrap(),
                        valid_until: None,
                        attestation_evidence: None,
                        withdrawn_at: None,
                        persist_row_hash: String::new(),
                    },
                ),
            )
            .await
            .unwrap_err();
        assert!(
            matches!(err, crate::federation::Error::InvalidArgument(ref m) if m.contains("rough-only")),
            "got: {err:?}"
        );
    }

    /// v4.11.0 (#154 Ask 4/5) — live-PG geographic community admission +
    /// `communities_containing` (exercises the JSONB
    /// `policy_blob->>'cohort_subkind'` query). Unique keys per run.
